import { Test, TestingModule } from '@nestjs/testing';
import { TwoFactorAuthenticationController } from './two-factor-authentication.controller';
import { TwoFactorAuthenticationService } from './two-factor-authentication.service';
import { UserService } from '../../user/user.service';
import { AuthService } from '../auth.service';
import { EncryptionService } from '../../common/services/encryption.service';
import { ConfigService } from '@nestjs/config';
import {
  BadRequestException,
  ForbiddenException,
  UnauthorizedException,
} from '@nestjs/common';
import { TurnOn2faDto } from '@live-chat/shared-dtos';
import { User } from '../../database/entities';

describe('TwoFactorAuthenticationController', () => {
  let controller: TwoFactorAuthenticationController;
  let twoFactorAuthService: jest.Mocked<TwoFactorAuthenticationService>;
  let userService: jest.Mocked<UserService>;
  let authService: jest.Mocked<AuthService>;
  let encryptionService: jest.Mocked<EncryptionService>;
  let configService: jest.Mocked<ConfigService>;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [TwoFactorAuthenticationController],
      providers: [
        {
          provide: TwoFactorAuthenticationService,
          useValue: {
            generateSecret: jest.fn(),
            generateQrCodeDataURL: jest.fn(),
            isCodeValid: jest.fn(),
          },
        },
        {
          provide: UserService,
          useValue: {
            turnOnTwoFactorAuthentication: jest.fn(),
            findOneById: jest.fn(),
            turnOffTwoFactorAuthentication: jest.fn(),
          },
        },
        {
          provide: AuthService,
          useValue: {
            loginAfter2FA: jest.fn(),
          },
        },
        {
          provide: EncryptionService,
          useValue: {
            encrypt: jest.fn(),
            decrypt: jest.fn(),
          },
        },
        {
          provide: ConfigService,
          useValue: {
            get: jest.fn(),
          },
        },
      ],
    }).compile();

    controller = module.get<TwoFactorAuthenticationController>(
      TwoFactorAuthenticationController
    );
    twoFactorAuthService = module.get(TwoFactorAuthenticationService);
    userService = module.get(UserService);
    authService = module.get(AuthService);
    encryptionService = module.get(EncryptionService);
    configService = module.get(ConfigService);
  });

  it('should be defined', () => {
    expect(controller).toBeDefined();
  });

  describe('generate', () => {
    it('should generate a QR code and set a cookie', async () => {
      const req = { user: { id: '1' } };
      const res = { cookie: jest.fn(), json: jest.fn() };
      twoFactorAuthService.generateSecret.mockResolvedValue({
        secret: 'secret',
        otpAuthUrl: 'otp',
      });
      twoFactorAuthService.generateQrCodeDataURL.mockResolvedValue('qr-code');
      encryptionService.encrypt.mockReturnValue('encrypted-secret');

      await controller.generate(req as any, res as any);

      expect(res.cookie).toHaveBeenCalledWith(
        '2fa_secret',
        'encrypted-secret',
        expect.any(Object)
      );
      expect(res.json).toHaveBeenCalledWith({ qrCodeDataURL: 'qr-code' });
    });
  });

  describe('turnOn', () => {
    const turnOnDto: TurnOn2faDto = { code: '123456' };

    it('should throw BadRequestException if cookie is missing', async () => {
      const req = { cookies: {} };
      const res = { clearCookie: jest.fn() };
      await expect(controller.turnOn(req as any, turnOnDto, res as any)).rejects.toThrow(
        BadRequestException
      );
    });

    it('should throw UnauthorizedException if code is invalid', async () => {
      const req = { user: { id: '1' }, cookies: { '2fa_secret': 'secret' } };
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(false);

      const res = { clearCookie: jest.fn() };
      await expect(controller.turnOn(req as any, turnOnDto, res as any)).rejects.toThrow(
        UnauthorizedException
      );
    });

    it('should turn on 2FA and return recovery codes', async () => {
      const req = { user: { id: '1' }, cookies: { '2fa_secret': 'secret' } };
      const recoveryCodes = ['code1'];
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(true);
      userService.turnOnTwoFactorAuthentication.mockResolvedValue({
        user: {} as User,
        recoveryCodes,
      });

      const res = { clearCookie: jest.fn() };
      const result = await controller.turnOn(req as any, turnOnDto, res as any);

      expect(result.recoveryCodes).toEqual(recoveryCodes);
    });
  });

  describe('authenticate', () => {
    const authDto: TurnOn2faDto = { code: '123456' };

    it('should throw ForbiddenException if 2FA is not enabled', async () => {
      const req = { user: { sub: '1' }, ip: 'ip', headers: {} };
      const user = { isTwoFactorAuthenticationEnabled: false } as User;
      userService.findOneById.mockResolvedValue(user);

      await expect(
        controller.authenticate(req as any, authDto, {} as any)
      ).rejects.toThrow(ForbiddenException);
    });

    it('should throw UnauthorizedException if code is invalid', async () => {
      const req = { user: { sub: '1' }, ip: 'ip', headers: {} };
      const user = {
        isTwoFactorAuthenticationEnabled: true,
        twoFactorAuthenticationSecret: 'secret',
      } as User;
      userService.findOneById.mockResolvedValue(user);
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(false);

      await expect(
        controller.authenticate(req as any, authDto, {} as any)
      ).rejects.toThrow(UnauthorizedException);
    });

    it('should return tokens and user on successful authentication', async () => {
      const req = { user: { sub: '1' }, ip: 'ip', headers: {} };
      const res = { cookie: jest.fn(), json: jest.fn(), clearCookie: jest.fn() };
      const user = {
        isTwoFactorAuthenticationEnabled: true,
        twoFactorAuthenticationSecret: 'secret',
      } as User;
      const tokens = {
        accessToken: 'access',
        refreshToken: 'refresh',
        user: { ...user, hasPassword: true } as any,
      };
      userService.findOneById.mockResolvedValue(user);
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(true);
      authService.loginAfter2FA.mockResolvedValue(tokens);
      configService.get.mockReturnValue('30d');

      await controller.authenticate(req as any, authDto, res as any);

      expect(res.cookie).toHaveBeenCalledWith(
        'refresh_token',
        'refresh',
        expect.any(Object)
      );
      expect(res.clearCookie).toHaveBeenCalledWith('2fa_partial_token');
      expect(res.json).toHaveBeenCalledWith({ accessToken: 'access', user: tokens.user });
    });
  });

  describe('turnOff', () => {
    const turnOffDto: TurnOn2faDto = { code: '123456' };

    it('should throw ForbiddenException if 2FA is not enabled', async () => {
      const req = { user: { id: '1' } };
      const user = { isTwoFactorAuthenticationEnabled: false } as User;
      userService.findOneById.mockResolvedValue(user);

      await expect(controller.turnOff(req as any, turnOffDto)).rejects.toThrow(
        ForbiddenException
      );
    });

    it('should throw UnauthorizedException if code is invalid', async () => {
      const req = { user: { id: '1' } };
      const user = {
        isTwoFactorAuthenticationEnabled: true,
        twoFactorAuthenticationSecret: 'secret',
      } as User;
      userService.findOneById.mockResolvedValue(user);
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(false);

      await expect(controller.turnOff(req as any, turnOffDto)).rejects.toThrow(
        UnauthorizedException
      );
    });

    it('should turn off 2FA successfully', async () => {
      const req = { user: { id: '1' } };
      const user = {
        isTwoFactorAuthenticationEnabled: true,
        twoFactorAuthenticationSecret: 'secret',
      } as User;
      userService.findOneById.mockResolvedValue(user);
      encryptionService.decrypt.mockReturnValue('decrypted-secret');
      twoFactorAuthService.isCodeValid.mockReturnValue(true);

      const result = await controller.turnOff(req as any, turnOffDto);

      expect(userService.turnOffTwoFactorAuthentication).toHaveBeenCalledWith('1');
      expect(result.message).toContain('disabled');
    });
  });
});

import {
  Controller,
  Post,
  UseGuards,
  Req,
  Res,
  Body,
  HttpCode,
  HttpStatus,
  UnauthorizedException,
  ForbiddenException,
  ValidationPipe,
  BadRequestException,
} from '@nestjs/common';
import { TwoFactorAuthenticationService } from './two-factor-authentication.service';
import { JwtAuthGuard } from '../guards/jwt-auth.guard';
import type { AuthenticatedRequest } from '../../common/types/authenticated-request.interface';
import { UserService } from '../../user/user.service';
import { TurnOn2faDto } from '@live-chat/shared-dtos';
import { EncryptionService } from '../../common/services/encryption.service';
import * as bcrypt from 'bcrypt';
import { ConfigService } from '@nestjs/config';
import { AuthGuard } from '@nestjs/passport';
import type { TwoFactorRequest } from '../../common/types/two-factor-request.interface';
import { type Response } from 'express';
import { ApiBody, ApiOperation, ApiResponse, ApiTags } from '@nestjs/swagger';
import { UserSecurityService } from '../../user/services/user-security.service';
import { LoginService } from '../services/login.service';

/**
 * Controller for handling two-factor authentication (2FA) related HTTP requests.
 * Provides endpoints for generating 2FA setup, turning 2FA on/off, and authenticating with 2FA.
 */
@ApiTags('2FA')
@Controller('2fa')
export class TwoFactorAuthenticationController {
  constructor(
    private readonly twoFactorAuthService: TwoFactorAuthenticationService,
    private readonly userService: UserService,
    private readonly userSecurityService: UserSecurityService,
    private readonly loginService: LoginService,
    private readonly encryptionService: EncryptionService,
    private readonly configService: ConfigService
  ) {}

  /**
   * Generates a 2FA secret and a QR code Data URL for the authenticated user.
   * The temporary secret is stored in an HttpOnly cookie.
   *
   * @param req - The authenticated request object.
   * @param res - The response object to set the 2FA secret cookie.
   * @returns An object containing the QR code Data URL.
   * @status 200 - OK.
   * @throws UnauthorizedException - If the user is not authenticated.
   */
  @Post('generate')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Generate 2FA secret and QR code' })
  @ApiResponse({ status: 200, description: 'QR code Data URL generated successfully.' })
  @ApiResponse({ status: 401, description: 'Unauthorized.' })
  async generate(@Req() req: AuthenticatedRequest, @Res() res) {
    const { user } = req;
    const { secret, otpAuthUrl } = await this.twoFactorAuthService.generateSecret(user as any);

    // Store the temporary secret in an HttpOnly cookie to be verified later
    res.cookie('2fa_secret', this.encryptionService.encrypt(secret), {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite:
        this.configService.get('NODE_ENV') === 'production' ? 'none' : 'lax',
      expires: new Date(Date.now() + 5 * 60 * 1000), // 5 minutes validity
    });

    const qrCodeDataURL = await this.twoFactorAuthService.generateQrCodeDataURL(otpAuthUrl);
    return res.json({ qrCodeDataURL });
  }

  /**
   * Turns on two-factor authentication for the authenticated user.
   * Verifies the provided 2FA code against the temporary secret stored in the cookie.
   *
   * @param req - The authenticated request object.
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @param res - The response object to clear the 2FA secret cookie.
   * @returns A success message and recovery codes.
   * @status 200 - OK.
   * @throws BadRequestException - If the 2FA secret cookie is not found.
   * @throws UnauthorizedException - If the 2FA code is wrong.
   */
  @Post('turn-on')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Turn on 2FA for the authenticated user' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: '2FA enabled successfully.' })
  @ApiResponse({ status: 400, description: 'Bad Request (2FA secret cookie not found).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (wrong authentication code).' })
  async turnOn(
    @Req() req: AuthenticatedRequest,
    @Body() body: TurnOn2faDto,
    @Res({ passthrough: true }) res: Response
  ) {
    const temporarySecretEncrypted = req.cookies['2fa_secret'];
    if (!temporarySecretEncrypted) {
      throw new BadRequestException(
        '2FA secret cookie not found. Please start over.'
      );
    }
    const temporarySecret = this.encryptionService.decrypt(
      temporarySecretEncrypted
    );

    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      temporarySecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    const { user, recoveryCodes } = await this.userSecurityService.turnOnTwoFactorAuthentication(
      req.user.id,
      temporarySecret
    );

    res.clearCookie('2fa_secret');

    return {
      message: 'Two-factor authentication has been enabled successfully.',
      recoveryCodes,
    };
  }

  /**
   * Authenticates a user with a 2FA code after a partial login.
   * Issues full access and refresh tokens upon successful 2FA verification.
   *
   * @param req - The request object containing partial user information (from 2FA partial guard).
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @param res - The response object to set cookies and return tokens.
   * @returns An object containing the access token and user details.
   * @status 200 - OK.
   * @throws UnauthorizedException - If the user is not found or the 2FA code is wrong.
   * @throws ForbiddenException - If 2FA is not enabled for the account.
   */
  @Post('authenticate')
  @UseGuards(AuthGuard('2fa-partial'))
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Authenticate with 2FA code' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: 'User successfully authenticated with 2FA.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (user not found or wrong code).' })
  @ApiResponse({ status: 403, description: 'Forbidden (2FA not enabled).' })
  async authenticate(
    @Req() req: TwoFactorRequest,
    @Body() body: TurnOn2faDto,
    @Res() res
  ) {
    const ipAddress = req.ip;
    const userAgent = req.headers['user-agent'] || 'unknown';

    const user = await this.userService.findOneById(req.user.sub);

    if (!user) {
      throw new UnauthorizedException('User not found');
    }

    if (!user.isTwoFactorAuthenticationEnabled) {
      throw new ForbiddenException('2FA is not enabled for this account.');
    }

    const decryptedSecret = this.encryptionService.decrypt(
      user.twoFactorAuthenticationSecret as string
    );
    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      decryptedSecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    const data = await this.loginService.loginAfter2FA(
      user,
      ipAddress,
      userAgent
    );
    const { accessToken, refreshToken, user: userResult } = data;

    const refreshTokenExpiresIn = this.configService.get<string>(
      'JWT_REFRESH_EXPIRES_IN'
    ) as string;
    const refreshTokenExpiryDays = parseInt(
      refreshTokenExpiresIn.slice(0, -1),
      10
    );
    // Set the refresh token in an HttpOnly cookie
    res.cookie('refresh_token', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + refreshTokenExpiryDays * 24 * 60 * 60 * 1000
      ),
    });

    // Clear the temporary cookies
    res.clearCookie('2fa_partial_token');
    res.clearCookie('2fa_secret');

    // Return full tokens, setting the refresh token in the cookie
    res.json({ accessToken, user: userResult });
  }

  /**
   * Turns off two-factor authentication for the authenticated user.
   * Requires the user to provide a valid 2FA code for verification.
   *
   * @param req - The authenticated request object.
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @returns A success message.
   * @status 200 - OK.
   * @throws ForbiddenException - If 2FA is not enabled for the account.
   * @throws UnauthorizedException - If the 2FA code is wrong.
   */
  @Post('turn-off')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Turn off 2FA for the authenticated user' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: '2FA disabled successfully.' })
  @ApiResponse({ status: 403, description: 'Forbidden (2FA not enabled).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (wrong authentication code).' })
  async turnOff(
    @Req() req: AuthenticatedRequest,
    @Body() body: TurnOn2faDto // Reuse the DTO that has the 'code' field
  ) {
    const user = await this.userService.findOneById(req.user.id);

    if (!user.isTwoFactorAuthenticationEnabled) {
      throw new ForbiddenException('2FA is not enabled for this account.');
    }

    const decryptedSecret = this.encryptionService.decrypt(
      user.twoFactorAuthenticationSecret as string
    );

    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      decryptedSecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    await this.userSecurityService.turnOffTwoFactorAuthentication(req.user.id);

    return { message: 'Two-factor authentication has been disabled.' };
  }
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { authenticator } from 'otplib';
import { User } from '../../database/entities';
import { toDataURL } from 'qrcode';

/**
 * Service responsible for handling two-factor authentication (2FA) logic.
 * This includes generating 2FA secrets, QR codes, and verifying authentication codes.
 */
@Injectable()
export class TwoFactorAuthenticationService {
  constructor(private readonly configService: ConfigService) {}

  /**
   * Generates a new 2FA secret and an OTP (One-Time Password) authentication URL for a user.
   * The secret is not saved at this stage; it's returned for the user to confirm.
   *
   * @param user - The user for whom to generate the 2FA secret.
   * @returns A promise that resolves to an object containing the generated secret and the OTP authentication URL.
   */
  public async generateSecret(
    user: User
  ): Promise<{ secret: string; otpAuthUrl: string }> {
    const secret = authenticator.generateSecret();
    const appName = this.configService.get<string>(
      'TWO_FACTOR_APP_NAME',
      'LiveChat'
    );
    const otpAuthUrl = authenticator.keyuri(user.email, appName, secret);

    // We don't save the secret yet. It will be saved only after user confirms the code.
    return { secret, otpAuthUrl };
  }

  /**
   * Generates a Data URL for a QR code from an OTP authentication URL.
   * This Data URL can be used to display the QR code image directly in a web page.
   *
   * @param otpAuthUrl - The OTP authentication URL generated by `generateSecret`.
   * @returns A promise that resolves to a string containing the Data URL of the QR code.
   */
  public async generateQrCodeDataURL(otpAuthUrl: string): Promise<string> {
    return toDataURL(otpAuthUrl);
  }

  /**
   * Verifies if a provided 2FA code is valid against a given secret.
   *
   * @param code - The 2FA code entered by the user.
   * @param secret - The 2FA secret associated with the user.
   * @returns A boolean indicating whether the code is valid.
   */
  public isCodeValid(code: string, secret: string): boolean {
    return authenticator.verify({
      token: code,
      secret: secret,
    });
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { AuthController } from './auth.controller';
import { AuthService } from './auth.service';
import { ConfigService } from '@nestjs/config';
