        twoFaReq.user,
        twoFaReq.ip,
        twoFaReq.headers['user-agent']
      );
      expect(res.cookie).toHaveBeenCalledWith(
        '2fa_partial_token',
        loginResult.partialToken,
        expect.any(Object)
      );
