import {
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from '../../common/decorators/public.decorator';

/**
 * This Guard will automatically activate JwtStrategy.
 * When applied to a route, it will check the existence and validity of the JWT
 * in the Authorization header of the request.
 * If the token is valid, it will attach the authenticated payload to request.user.
 * If the token does not exist or is invalid, it will automatically throw an UnauthorizedException (401 error).
 */
@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }
    return super.canActivate(context);
  }

  handleRequest(err, user, info) {
    // If there's an error or user does not exist, throw UnauthorizedException
    if (err || !user) {
      throw new UnauthorizedException({
        message: info?.message || 'Unauthorized',
        error: 'Unauthorized',
        statusCode: 401,
        errorCode: 'TOKEN_INVALID',
      });
    }
    return user;
  }
}

import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

/**
 * Guard này sẽ tự động kích hoạt LocalStrategy.
 * Khi được áp dụng cho một route, nó sẽ chạy logic xác thực của passport-local.
 * Nếu xác thực thành công, nó sẽ gắn đối tượng user vào request (req.user).
 * Nếu thất bại, nó sẽ tự động ném ra một UnauthorizedException (lỗi 401).
 */
@Injectable()
export class LocalAuthGuard extends AuthGuard('local') {}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

/**
 * Guard for authenticating requests using a refresh token.
 * This guard activates the 'jwt-refresh' Passport strategy.
 * It expects a refresh token to be present in the request (e.g., in cookies).
 * If the token is valid, it attaches the authenticated user payload to `req.user`.
 * If authentication fails (e.g., missing, invalid, or expired token), it throws an `UnauthorizedException`.
 */
@Injectable()
export class RefreshTokenGuard extends AuthGuard('jwt-refresh') {
  handleRequest(err, user, info) {
    // If there's an error or user does not exist, throw UnauthorizedException
    if (err || !user) {
      throw new UnauthorizedException({
        message: info?.message || 'Unauthorized',
        error: 'Unauthorized',
        statusCode: 401,
        errorCode: 'TOKEN_INVALID',
      });
    }
    return user;
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { User } from '../../database/entities';
import { TokenService } from './token.service';
import { UserService } from '../../user/user.service';
import { OAuthService } from './oauth.service';

export type LoginResult = 
  | { status: 'success'; tokens: { accessToken: string; refreshToken: string }; user: User }
  | { status: '2fa_required'; partialToken: string };

@Injectable()
export class LoginService {
  constructor(
    private readonly tokenService: TokenService,
    private readonly userService: UserService,
    private readonly configService: ConfigService,
    private readonly oauthService: OAuthService,
  ) {}

  async login(user: User, ipAddress?: string, userAgent?: string): Promise<LoginResult> {
    if (user.isTwoFactorAuthenticationEnabled) {
      const { accessToken } = await this.tokenService.generate2FAPartialToken(user.id);
      return { status: '2fa_required', partialToken: accessToken };
    }

    const tokens = await this.tokenService.generateTokens(user.id, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.tokenService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId: user.id,
      expiresAt,
      ipAddress,
      userAgent,
    });

    await this.userService.updateLastLogin(user.id);

    return { status: 'success', tokens, user };
  }

  /**
   * Login after 2FA verification - skips 2FA check since user already verified.
   */
  async loginAfter2FA(user: User, ipAddress?: string, userAgent?: string) {
    const tokens = await this.tokenService.generateTokens(user.id, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.tokenService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId: user.id,
      expiresAt,
      ipAddress,
      userAgent,
    });

    await this.userService.updateLastLogin(user.id);

    const { passwordHash, ...safeUser } = user;
    return { 
      accessToken: tokens.accessToken, 
      refreshToken: tokens.refreshToken, 
      user: { ...safeUser, hasPassword: !!passwordHash }
    };
  }

  async exchangeCodeForTokens(code: string, ip: string, userAgent: string) {
    const userId = await this.oauthService.validateOneTimeCode(code);
    const user = await this.userService.findOneById(userId);

    if (!user) {
      throw new UnauthorizedException('User not found.');
    }

    const loginResult = await this.login(user, ip, userAgent);

    if (loginResult.status === '2fa_required') {
      // Should not happen in current flow as OAuth usually bypasses 2FA or handles it differently,
      // but if we enforce 2FA on OAuth users, we need to handle it.
      // For now, assuming OAuth users are verified.
      // However, if 2FA is enabled, we must respect it.
      throw new UnauthorizedException({
        message: '2FA required',
        errorCode: '2FA_REQUIRED',
        partialToken: loginResult.partialToken
      });
    }

    return {
      accessToken: loginResult.tokens.accessToken,
      refreshToken: loginResult.tokens.refreshToken,
      user: {
        ...user,
        hasPassword: !!user.passwordHash
      }
    };
  }
}

import {
  Injectable,
  Inject,
  Logger,
  UnauthorizedException,
  ConflictException,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { EntityManager } from 'typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import * as crypto from 'crypto';
import { User, UserIdentity } from '../../database/entities';
import { UserService } from '../../user/user.service';

@Injectable()
export class OAuthService {
  private readonly logger = new Logger(OAuthService.name);

  constructor(
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly userService: UserService,
  ) {}

  async validateOAuthUser(profile: {
    provider: string;
    providerId: string;
    email: string;
    name: string;
    avatarUrl: string;
  }): Promise<User> {
    return this.entityManager.transaction(async (entityManager) => {
      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      if (existingIdentity) {
        const user = existingIdentity.user;
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          await entityManager.save(user);
        }
        return user;
      }

      let user = await entityManager.findOne(User, {
        where: { email: profile.email },
      });

      if (user) {
        let needsUpdate = false;
        if (!user.avatarUrl && profile.avatarUrl) {
          user.avatarUrl = profile.avatarUrl;
          needsUpdate = true;
        }
        if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
          user.fullName = profile.name;
          needsUpdate = true;
        }
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          needsUpdate = true;
        }
        if (needsUpdate) {
          await entityManager.save(user);
        }
      } else {
        user = entityManager.create(User, {
          email: profile.email,
          fullName: profile.name,
          avatarUrl: profile.avatarUrl,
          isEmailVerified: true,
        });
        await entityManager.save(user);
      }

      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user,
      });
      await entityManager.save(newIdentity);

      return user;
    });
  }

  async generateOneTimeCode(userId: string): Promise<string> {
    const code = crypto.randomBytes(32).toString('hex');
    const key = `one-time-code:${code}`;
    const fiveMinutesInMs = 5 * 60 * 1000;
    await this.cacheManager.set(key, userId, fiveMinutesInMs);
    return code;
  }

  async validateOneTimeCode(code: string): Promise<string> {
    const key = `one-time-code:${code}`;
    const userId = await this.cacheManager.get<string>(key);

    if (!userId) {
      throw new UnauthorizedException(`No user found with key ${key}, invalid or expired code.`);
    }

    await this.cacheManager.del(key);
    return userId;
  }

  async linkGoogleAccount(
    userId: string,
    profile: {
      provider: string;
      providerId: string;
      email: string;
      name: string;
      avatarUrl: string;
    },
  ): Promise<{ message: string; user: User }> {
    this.logger.log(`🔵 [LinkGoogleAccount] User ${userId} is linking Google account: ${profile.email}`);

    return this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      if (existingIdentity) {
        if (existingIdentity.user.id === userId) {
          throw new ConflictException('Tài khoản Google này đã được liên kết với tài khoản của bạn.');
        } else {
          throw new ConflictException('Tài khoản Google này đã được liên kết với một tài khoản khác.');
        }
      }

      if (user.email !== profile.email) {
        this.logger.warn(`⚠️ [LinkGoogleAccount] Email mismatch: user email ${user.email} vs Google email ${profile.email}`);
        throw new BadRequestException('Email của tài khoản Google không khớp với email tài khoản hiện tại.');
      }

      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user,
      });
      await entityManager.save(newIdentity);

      let needsUpdate = false;
      if (!user.avatarUrl && profile.avatarUrl) {
        user.avatarUrl = profile.avatarUrl;
        needsUpdate = true;
      }
      if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
        user.fullName = profile.name;
        needsUpdate = true;
      }
      if (needsUpdate) {
        await entityManager.save(user);
      }

      if (!user.isEmailVerified) {
        user.isEmailVerified = true;
        await entityManager.save(user);
      }

      return {
        message: 'Liên kết tài khoản Google thành công.',
        user,
      };
    });
  }

  async unlinkOAuthAccount(userId: string, provider: string): Promise<{ message: string }> {
    return this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (!user.passwordHash) {
        throw new BadRequestException(
          'Bạn cần đặt mật khẩu trước khi hủy liên kết tài khoản Google. Điều này đảm bảo bạn vẫn có thể đăng nhập vào tài khoản.',
        );
      }

      const identity = await entityManager.findOne(UserIdentity, {
        where: { userId, provider },
      });

      if (!identity) {
        throw new NotFoundException(`Không tìm thấy tài khoản ${provider} được liên kết.`);
      }

      await entityManager.remove(identity);
      return { message: `Đã hủy liên kết tài khoản ${provider} thành công.` };
    });
  }

  async getLinkedAccounts(userId: string): Promise<UserIdentity[]> {
    return this.entityManager.find(UserIdentity, {
      where: { userId },
    });
  }
}

import {
  Injectable,
  Inject,
  Logger,
  UnauthorizedException,
  BadRequestException,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { UserService } from '../../user/user.service';
import { MailService } from '../../mail/mail.service';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import { EntityManager } from 'typeorm';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import { User } from '../../database/entities';
import { UserStatus } from '@live-chat/shared-types';
import { TokenService } from './token.service';

@Injectable()
export class PasswordService {
  private readonly logger = new Logger(PasswordService.name);

  constructor(
    private readonly userService: UserService,
    private readonly mailService: MailService,
    private readonly tokenService: TokenService,
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
  ) {}

  async validateUser(email: string, pass: string): Promise<User | null> {
    const user = await this.userService.findOneByEmail(email);

    if (!user) {
      throw new ForbiddenException('Email hoặc mật khẩu không đúng.');
    }

    if (user && user.passwordHash && (await bcrypt.compare(pass, user.passwordHash))) {
      if (user.status === UserStatus.SUSPENDED) {
        throw new ForbiddenException('Tài khoản của bạn đã bị đình chỉ.');
      }

      if (user.status === UserStatus.INACTIVE) {
        return this.userService.activate(user.id);
      }

      return user;
    }
    return null;
  }

  async changePassword(userId: string, currentPassword: string | undefined, newPassword: string): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (user.passwordHash) {
        if (!currentPassword) {
          throw new BadRequestException({
            message: 'Mật khẩu hiện tại là bắt buộc khi bạn đã có mật khẩu.',
            errorCode: 'CURRENT_PASSWORD_REQUIRED',
          });
        }

        const isPasswordValid = await bcrypt.compare(currentPassword, user.passwordHash);
        if (!isPasswordValid) {
          throw new ForbiddenException({
            message: 'Mật khẩu hiện tại không đúng.',
            errorCode: 'WRONG_PASSWORD',
          });
        }
      } else {
        this.logger.log(`User ${userId} is setting password for the first time (OAuth account)`);
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      // Logout all sessions
      await this.tokenService.removeAllRefreshTokensForUser(userId);
      await this.tokenService.invalidateAllTokens(userId);
    });
  }

  async setPassword(userId: string, newPassword: string): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (user.passwordHash) {
        throw new BadRequestException({
          message: 'Bạn đã có mật khẩu. Vui lòng sử dụng chức năng đổi mật khẩu.',
          errorCode: 'PASSWORD_ALREADY_EXISTS',
        });
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      this.logger.log(`User ${userId} has set their password successfully`);
    });
  }

  async forgotPassword(email: string): Promise<{ message: string; isOAuthUser?: boolean }> {
    this.logger.log(`🔵 [ForgotPassword] Request for email: ${email}`);
    const user = await this.userService.findOneByEmail(email);

    if (!user) {
      this.logger.log(`ℹ️ [ForgotPassword] User not found for email: ${email}`);
      return {
        message: 'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
      };
    }

    if (!user.passwordHash) {
      this.logger.log(`⚠️ [ForgotPassword] User ${user.id} has no password (OAuth account)`);
      return {
        message: 'Tài khoản này được đăng nhập bằng Google. Vui lòng sử dụng nút "Đăng nhập bằng Google" để truy cập.',
        isOAuthUser: true,
      };
    }

    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `reset-password-token:${resetToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000); // 15 minutes

    await this.mailService.sendPasswordResetEmail(user, resetToken);
    this.logger.log(`✅ [ForgotPassword] Reset email sent to: ${user.email}`);

    return {
      message: 'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
    };
  }

  async resetPassword(token: string, newPassword: string): Promise<{ message: string }> {
    this.logger.log(`�� [ResetPassword] Attempting to reset password`);

    const tokenKey = `reset-password-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      this.logger.error(`❌ [ResetPassword] Token not found or expired`);
      throw new BadRequestException('Token đặt lại mật khẩu không hợp lệ hoặc đã hết hạn.');
    }

    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new NotFoundException('Người dùng không tồn tại.');
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      await this.cacheManager.del(tokenKey);

      // Logout all sessions
      await this.tokenService.removeAllRefreshTokensForUser(userId);
      await this.tokenService.invalidateAllTokens(userId);

      this.logger.log(`✅ [ResetPassword] Password updated and sessions logged out for user: ${userId}`);

      return {
        message: 'Mật khẩu đã được đặt lại thành công. Vui lòng đăng nhập với mật khẩu mới.',
      };
    });
  }
}

import {
  Injectable,
  ConflictException,
  Inject,
  NotFoundException,
  Logger,
} from '@nestjs/common';
import { UserService } from '../../user/user.service';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import {
  RegisterDto,
  ResendVerificationDto,
} from '@live-chat/shared-dtos';
import { User } from '../../database/entities';
import { EntityManager } from 'typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { type Cache } from 'cache-manager';
import { MailService } from '../../mail/mail.service';

@Injectable()
export class RegistrationService {
  private readonly logger = new Logger(RegistrationService.name);

  constructor(
    private readonly userService: UserService,
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly mailService: MailService,
  ) {}

  async register(registerDto: RegisterDto): Promise<{ message: string }> {
    this.logger.log(`🔵 [Register] Starting registration for email: ${registerDto.email}`);

    return await this.entityManager.transaction(async (entityManager) => {
      const existingUser = await this.userService.findOneByEmail(registerDto.email);
      if (existingUser) {
        throw new ConflictException('Email này đã được sử dụng.');
      }

      const passwordHash = await bcrypt.hash(registerDto.password, 12);

      const newUser = await entityManager.save(User, {
        email: registerDto.email,
        passwordHash,
        fullName: registerDto.fullName,
        isEmailVerified: false,
      });

      this.logger.log(`✅ [Register] User created with ID: ${newUser.id}`);

      const verificationToken = crypto.randomBytes(32).toString('hex');
      const tokenKey = `verification-token:${verificationToken}`;
      await this.cacheManager.set(tokenKey, newUser.id, 900000); // 15 minutes

      await this.mailService.sendUserConfirmation(newUser, verificationToken);

      if (registerDto.invitationToken) {
        try {
          const invitationKey = `pending-invitation:${newUser.id}`;
          await this.cacheManager.set(invitationKey, registerDto.invitationToken, 604800000);
        } catch (error) {
          this.logger.error(`❌ [Register] Failed to store invitation token`, error);
        }
      }

      return {
        message: 'Đăng ký thành công, vui lòng kiểm tra email để kích hoạt tài khoản.',
      };
    });
  }

  async verifyEmail(token: string): Promise<{ message: string; invitationToken?: string }> {
    const tokenKey = `verification-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      throw new NotFoundException('Token xác thực không hợp lệ hoặc đã hết hạn.');
    }

    await this.userService.markEmailAsVerified(userId);
    await this.cacheManager.del(tokenKey);

    const invitationKey = `pending-invitation:${userId}`;
    const invitationToken = await this.cacheManager.get<string>(invitationKey);

    if (invitationToken) {
      return {
        message: 'Xác thực email thành công.',
        invitationToken,
      };
    }

    return { message: 'Xác thực email thành công.' };
  }

  async resendVerificationEmail(resendVerificationDto: ResendVerificationDto): Promise<{ message: string }> {
    const user = await this.userService.findOneByEmail(resendVerificationDto.email);

    if (!user) {
      return {
        message: 'Nếu tài khoản của bạn tồn tại, một email xác thực đã được gửi đi.',
      };
    }

    if (user.isEmailVerified) {
      throw new ConflictException('Email này đã được xác thực.');
    }

    const verificationToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `verification-token:${verificationToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000);

    await this.mailService.sendUserConfirmation(user, verificationToken);

    return {
      message: 'Một email xác thực mới đã được gửi. Vui lòng kiểm tra hộp thư của bạn.',
    };
  }
}

import { Injectable, Logger, UnauthorizedException, Inject } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, EntityManager, LessThan } from 'typeorm';
import { RefreshToken, User } from '../../database/entities';
import * as bcrypt from 'bcrypt';
import { Cron, CronExpression } from '@nestjs/schedule';
import { UserStatus } from '@live-chat/shared-types';
import { UserService } from '../../user/user.service';

interface SetRefreshTokenOptions {
  refreshToken: string;
  userId: string;
  expiresAt: Date;
  expiredRefreshToken?: string;
  ipAddress?: string;
  userAgent?: string;
}

@Injectable()
export class TokenService {
  private readonly logger = new Logger(TokenService.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    @InjectRepository(RefreshToken)
    private readonly refreshTokenRepository: Repository<RefreshToken>,
    private readonly userService: UserService,
    private readonly entityManager: EntityManager,
  ) {}

  /**
   * Generates a new pair of access and refresh tokens.
   */
  async generateTokens(userId: string, email: string) {
    const accessTokenPayload = { sub: userId, email };
    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_SECRET'),
        expiresIn: this.configService.get<string>('JWT_EXPIRES_IN'),
      }),
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_REFRESH_SECRET'),
        expiresIn: this.configService.get<string>('JWT_REFRESH_EXPIRES_IN'),
      }),
    ]);
    return { accessToken, refreshToken };
  }

  /**
   * Generates a partial JWT token for 2FA authentication flow.
   */
  async generate2FAPartialToken(userId: string) {
    const payload = {
      sub: userId,
      isTwoFactorAuthenticated: false,
      is2FA: true,
    };

    const accessToken = await this.jwtService.signAsync(payload, {
      secret: this.configService.get<string>('TWO_FACTOR_AUTH_JWT_SECRET'),
      expiresIn: this.configService.get<string>('TWO_FACTOR_AUTH_JWT_EXPIRES_IN'),
    });
    return { accessToken };
  }

  /**
   * Verifies if a refresh token is valid for a user.
   */
  async verifyRefreshToken(refreshToken: string, userId: string): Promise<boolean> {
    const storedTokens = await this.refreshTokenRepository.find({
      where: { userId },
    });

    if (!storedTokens || storedTokens.length === 0) {
      return false;
    }

    let matchingToken: RefreshToken | undefined;

    for (const storedToken of storedTokens) {
      const isMatch = await bcrypt.compare(refreshToken, storedToken.hashedToken);
      if (isMatch) {
        matchingToken = storedToken;
        break;
      }
    }

    if (matchingToken) {
      if (matchingToken.expiresAt < new Date()) {
        await this.refreshTokenRepository.delete(matchingToken.id);
        throw new UnauthorizedException('Refresh token has expired');
      }
      return true;
    }

    return false;
  }

  /**
   * Stores a new refresh token in the database, enforcing session limits.
   */
  async setCurrentRefreshToken(options: SetRefreshTokenOptions): Promise<void> {
    const { refreshToken, userId, expiresAt, expiredRefreshToken, ipAddress, userAgent } = options;

    return this.entityManager.transaction(async (entityManager) => {
      const sessionLimit = parseInt(this.configService.get<string>('SESSION_LIMIT') as string) || 5;

      const userTokens = await entityManager.find(RefreshToken, {
        where: { userId },
        order: { createdAt: 'ASC' },
      });

      if (userTokens.length >= sessionLimit) {
        const tokensToRemove = userTokens.slice(0, userTokens.length - sessionLimit + 1);
        await entityManager.remove(tokensToRemove);
        this.logger.log(`[SessionLimit] Removed ${tokensToRemove.length} oldest session(s) for user ${userId}`);
      }

      const hashedToken = await bcrypt.hash(refreshToken, 12);
      let finalIpAddress = ipAddress;
      let finalUserAgent = userAgent;

      if (expiredRefreshToken) {
        const oldToken = await this.findRefreshTokenByValue(userId, expiredRefreshToken, entityManager);
        if (oldToken) {
          finalIpAddress = ipAddress || oldToken.ipAddress;
          finalUserAgent = userAgent || oldToken.userAgent;
          await entityManager.remove(oldToken);
        }
      }

      // Remove any existing token with exact same metadata to prevent duplicates
      if (finalIpAddress && finalUserAgent) {
        await entityManager.delete(RefreshToken, {
          userId,
          ipAddress: finalIpAddress,
          userAgent: finalUserAgent,
        });
      }

      const newRefreshToken = entityManager.create(RefreshToken, {
        hashedToken,
        userId,
        expiresAt,
        ipAddress: finalIpAddress,
        userAgent: finalUserAgent,
      });

      await entityManager.save(newRefreshToken);
    });
  }

  private async findRefreshTokenByValue(
    userId: string,
    refreshToken: string,
    entityManager: EntityManager,
  ): Promise<RefreshToken | null> {
    const userTokens = await entityManager.find(RefreshToken, { where: { userId } });
    for (const token of userTokens) {
      const isMatch = await bcrypt.compare(refreshToken, token.hashedToken);
      if (isMatch) {
        return token;
      }
    }
    return null;
  }

  /**
   * Revokes a specific refresh token.
   */
  async revokeRefreshToken(userId: string, rawRefreshToken: string): Promise<void> {
    const userTokens = await this.refreshTokenRepository.find({ where: { userId } });
    for (const token of userTokens) {
      const isMatch = await bcrypt.compare(rawRefreshToken, token.hashedToken);
      if (isMatch) {
        await this.refreshTokenRepository.delete(token.id);
      }
    }
  }

  /**
   * Revokes all refresh tokens for a user.
   */
  async removeAllRefreshTokensForUser(userId: string): Promise<void> {
    await this.refreshTokenRepository.delete({ userId });
  }

  /**
   * Invalidates all tokens (Access & Refresh) by updating the user's `tokensValidFrom` timestamp.
   */
  async invalidateAllTokens(userId: string): Promise<void> {
    await this.entityManager.update(User, userId, { tokensValidFrom: new Date() });
  }

  /**
   * Refreshes access and refresh tokens.
   */
  async refreshUserTokens(userId: string, refreshToken: string) {
    const user = await this.userService.findOneById(userId);
    if (!user || user.status !== UserStatus.ACTIVE) {
      throw new UnauthorizedException('Access Denied');
    }

    try {
      const isValidToken = await this.verifyRefreshToken(refreshToken, userId);
      if (!isValidToken) {
        // Security risk: Invalid token presented. Log out all sessions.
        await this.removeAllRefreshTokensForUser(userId);
        await this.invalidateAllTokens(userId);
        throw new UnauthorizedException('Access Denied');
      }
    } catch (error) {
      if (error instanceof UnauthorizedException) {
        throw new UnauthorizedException('Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại.');
      }
      throw error;
    }

    const tokens = await this.generateTokens(userId, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId,
      expiresAt,
      expiredRefreshToken: refreshToken,
    });

    return tokens;
  }

  @Cron(CronExpression.EVERY_DAY_AT_3AM)
  async handleExpiredTokensCleanup() {
    this.logger.log('[Cron] Running scheduled task to clean up expired refresh tokens...');
    const result = await this.refreshTokenRepository.delete({
      expiresAt: LessThan(new Date()),
    });
    if (result.affected && result.affected > 0) {
      this.logger.log(`[Cron] Successfully deleted ${result.affected} expired refresh tokens.`);
    }
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { Request } from 'express';
import { Injectable, Logger, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * Passport strategy for handling partial 2FA (Two-Factor Authentication) tokens.
 * This strategy is used when a user has successfully logged in but 2FA is enabled,
 * requiring an additional step to verify the 2FA code.
 * It extracts a JWT from the '2fa_partial_token' cookie and validates it.
 * The token payload should indicate that 2FA is required but not yet completed.
 */
@Injectable()
export class TwoFactorAuthenticationStrategy extends PassportStrategy(
  Strategy,
  '2fa-partial' // named this strategy as '2fa-partial'
) {
  private readonly logger = new Logger(TwoFactorAuthenticationStrategy.name);

  constructor(configService: ConfigService) {
    const twoFactorAuthenticationSecret = configService.get<string>(
      'TWO_FACTOR_AUTH_JWT_SECRET'
    );
    if (!twoFactorAuthenticationSecret) {
      throw new Error(
        'TWO_FACTOR_AUTH_JWT_SECRET is not defined in environment variables'
      );
    }

    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => {
          const data = request.cookies['2fa_partial_token'];
          this.logger.debug(
            `Extracting 2fa_partial_token: ${data ? 'Found' : 'Not found'}`
          );
          if (!data) {
            this.logger.warn('2fa_partial_token cookie not found');
            return null;
          }
          return data;
        },
      ]),
      ignoreExpiration: false,
      secretOrKey: twoFactorAuthenticationSecret,
      // pass request obj to the validate method
      passReqToCallback: true,
    });
  }

  validate(req: Request, payload: any): any {
    this.logger.debug('2FA Strategy validate called');
    this.logger.debug('Payload:', JSON.stringify(payload, null, 2));

    const partialToken = req.cookies['2fa_partial_token'];

    // Check necessary conditions
    if (!payload.sub) {
      this.logger.error('No user ID in payload');
      throw new UnauthorizedException('Authentication failed');
    }

    if (!payload.is2FA) {
      this.logger.error('Not a 2FA token');
      throw new UnauthorizedException('Authentication failed');
    }

    if (payload.isTwoFactorAuthenticated === true) {
      this.logger.error('2FA already completed');
      throw new UnauthorizedException('Authentication failed');
    }

    this.logger.log(
      `2FA Strategy validation successful for user: ${payload.sub}`
    );

    // Attach both payload and refresh token to request.user
    return { ...payload, partialToken };
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback, Profile } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * Google OAuth Strategy specifically for linking accounts
 * This strategy is used when a logged-in user wants to link their Google account
 * It doesn't validate/create a user, just returns the Google profile data
 */
@Injectable()
export class GoogleLinkStrategy extends PassportStrategy(
  Strategy,
  'google-link'
) {
  constructor(private readonly configService: ConfigService) {
    super({
      clientID: configService.get<string>('GOOGLE_CLIENT_ID') as string,
      clientSecret: configService.get<string>('GOOGLE_CLIENT_SECRET') as string,
      callbackURL: `${configService.get<string>('API_BASE_URL')}/auth/link-google/callback`,
      scope: ['email', 'profile'],
      passReqToCallback: true, // This allows us to access req.query.state
    });
  }

  // Override authenticate to pass the state parameter from query to Google OAuth
  authenticate(req: any, options?: any) {
    const state = req.query.state;
    if (state) {
      options = options || {};
      options.state = state;
    }
    super.authenticate(req, options);
  }

  async validate(
    req: any,
    accessToken: string,
    refreshToken: string,
    profile: Profile,
    done: VerifyCallback
  ): Promise<any> {
    const { id, displayName, emails, photos } = profile;

    if (!emails || emails.length === 0) {
      return done(new Error('No email associated with this account!'), false);
    }

    // Return the Google profile data along with the state parameter
    // The state will be available in req.query.state in the callback
    const googleProfile = {
      provider: 'google',
      providerId: id,
      email: emails[0].value,
      name: displayName,
      avatarUrl: photos && photos.length > 0 ? photos[0].value : '',
      state: req.query.state, // This will be the state returned from Google
    };

    done(null, googleProfile);
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback, Profile } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { OAuthService } from '../services/oauth.service';

/**
 * Passport strategy for authenticating users via Google OAuth 2.0.
 * This strategy handles the initial Google login flow, validating the Google profile
 * and either finding an existing user, linking to an existing user by email,
 * or creating a new user and identity.
 */
@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  constructor(
    private readonly configService: ConfigService,
    private readonly oauthService: OAuthService
  ) {
    super({
      clientID: configService.get<string>('GOOGLE_CLIENT_ID') as string,
      clientSecret: configService.get<string>('GOOGLE_CLIENT_SECRET') as string,
      callbackURL: `${configService.get<string>('API_BASE_URL')}/auth/google/callback`,
      scope: ['email', 'profile'],
    });
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: Profile,
    done: VerifyCallback
  ): Promise<any> {
    const { id, displayName, emails, photos } = profile;
    if (!emails || emails.length === 0) {
      return done(new Error('No email associated with this account!'), false);
    }

    if (!photos || photos.length === 0) {
      return done(
        new Error('No profile picture associated with this account!'),
        false
      );
    }

    const googleProfile = {
      provider: 'google',
      providerId: id,
      email: emails[0].value,
      name: displayName,
      avatarUrl: photos[0].value,
    };

    const user = await this.oauthService.validateOAuthUser(googleProfile);
    done(null, user);
  }
}

