import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Request, Response } from 'express';

/**
 * HTTP Logging Interceptor.
 *
 * Replaces the old LoggerMiddleware that relied on monkey-patching response.send/json.
 * Uses NestJS Interceptor pattern with RxJS tap() for clean, non-invasive logging.
 */
@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HTTP');

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    const { method, originalUrl } = request;
    const startTime = Date.now();

    return next.handle().pipe(
      tap({
        next: () => {
          const duration = Date.now() - startTime;
          const statusCode = response.statusCode;

          this.logger.log(
            `${method} ${originalUrl} ${statusCode} - ${duration}ms`
          );
        },
        error: (error) => {
          const duration = Date.now() - startTime;
          const statusCode = error.status || 500;
          const message = error.message || 'Internal Server Error';

          this.logger.error(
            `${method} ${originalUrl} ${statusCode} - ${duration}ms | ${message}`
          );
        },
      })
    );
  }
}

// src/common/middleware/logger.middleware.ts
import { Injectable, NestMiddleware, Logger } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';

@Injectable()
export class LoggerMiddleware implements NestMiddleware {
  private readonly logger = new Logger('HTTP');

  private readonly colors = {
    reset: '\x1b[0m',
    bright: '\x1b[1m',
    dim: '\x1b[2m',
    red: '\x1b[31m',
    green: '\x1b[32m',
    yellow: '\x1b[33m',
    cyan: '\x1b[36m',
    white: '\x1b[37m',
    gray: '\x1b[90m',
  };

  private colorize(text: string, color: string): string {
    return `${color}${text}${this.colors.reset}`;
  }

  private colorizeMethod(method: string): string {
    const methodColors: Record<string, string> = {
      GET: this.colors.green,
      POST: this.colors.cyan,
      PUT: this.colors.yellow,
      PATCH: this.colors.yellow,
      DELETE: this.colors.red,
    };
    return this.colorize(method, methodColors[method] || this.colors.white);
  }

  private colorizeStatus(statusCode: number): string {
    if (statusCode >= 500) return this.colorize(String(statusCode), this.colors.red);
    if (statusCode >= 400) return this.colorize(String(statusCode), this.colors.yellow);
    if (statusCode >= 300) return this.colorize(String(statusCode), this.colors.cyan);
    return this.colorize(String(statusCode), this.colors.green);
  }

  use(request: Request, response: Response, next: NextFunction) {
    const startTime = Date.now();
    const { method, originalUrl, body, headers, ip } = request;

    const oldSend = response.send;
    const oldJson = response.json;
    let responseBody: any;

    response.send = function (body?: any): Response {
      responseBody = body;
      return oldSend.call(response, body);
    };

    response.json = function (body?: any): Response {
      responseBody = body;
      return oldJson.call(response, body);
    };

    response.on('finish', () => {
      const { statusCode } = response;
      const duration = Date.now() - startTime;
      const contentLength = response.get('content-length') || '-';

      // Simple one-line log for successful requests
      const simpleLog = `${this.colorizeMethod(method.padEnd(7))} ${originalUrl} ${this.colorizeStatus(statusCode)} ${this.colorize(`${duration}ms`, this.colors.dim)}`;

      if (statusCode >= 400) {
        // Detailed log for errors
        let parsedResponse: any;
        try {
          parsedResponse = typeof responseBody === 'string' ? JSON.parse(responseBody) : responseBody;
        } catch {
          parsedResponse = responseBody;
        }

        const errorLog = [
          '',
          this.colorize('━'.repeat(60), this.colors.red),
          `${this.colorize('ERROR', this.colors.red)} ${simpleLog}`,
          this.colorize('━'.repeat(60), this.colors.red),
          `IP: ${ip}  Content-Length: ${contentLength}`,
          `User-Agent: ${headers['user-agent'] || 'unknown'}`,
          '',
          this.colorize('Request Body:', this.colors.bright),
          JSON.stringify(body || {}, null, 2),
          '',
          this.colorize('Response:', this.colors.bright),
          JSON.stringify(parsedResponse || {}, null, 2),
          this.colorize('━'.repeat(60), this.colors.red),
          '',
        ].join('\n');

        this.logger.error(errorLog);
      } else {
        // Simple log for success
        this.logger.log(simpleLog);
      }
    });

    next();
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { EncryptionService } from './encryption.service';
import { ConfigService } from '@nestjs/config';

describe('EncryptionService', () => {
  let service: EncryptionService;
  let configService: jest.Mocked<ConfigService>;

  const mockConfigService = {
    get: jest.fn(),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        {
          provide: ConfigService,
          useValue: mockConfigService,
        },
      ],
    }).compile();

    configService = module.get(ConfigService);
  });

  describe('with valid key', () => {
    beforeEach(() => {
      configService.get.mockReturnValue('12345678901234567890123456789012');
      service = new EncryptionService(configService);
    });

    it('should be defined', () => {
      expect(service).toBeDefined();
    });

    it('should encrypt and decrypt a string successfully', () => {
      const text = 'my secret text';
      const encrypted = service.encrypt(text);
      const decrypted = service.decrypt(encrypted);

      expect(encrypted).not.toEqual(text);
      expect(decrypted).toEqual(text);
    });

    it('should return a string in the correct format', () => {
      const text = 'my secret text';
      const encrypted = service.encrypt(text);
      const parts = encrypted.split(':');
      expect(parts.length).toBe(3);
    });

    it('should throw an error for invalid encrypted text format', () => {
      const invalidEncryptedText = 'invalid-text';
      expect(() => service.decrypt(invalidEncryptedText)).toThrow(
        'Could not decrypt token.'
      );
    });
  });

  describe('constructor validation', () => {
    it('should throw an error if encryption key is not configured', () => {
      configService.get.mockReturnValue(null);
      expect(() => new EncryptionService(configService)).toThrow(
        'ENCRYPTION_KEY must be defined in .env '
      );
    });

    it('should throw an error if encryption key is not 32 characters long', () => {
      configService.get.mockReturnValue('short-key');
      expect(() => new EncryptionService(configService)).toThrow(
        'ENCRYPTION_KEY must be 32 characters long.'
      );
    });
  });
});

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as crypto from 'crypto';

/**
 * @Injectable
 * A service for encrypting and decrypting text, primarily for sensitive data like access tokens.
 * Uses AES-256-GCM algorithm for authenticated encryption.
 */
@Injectable()
export class EncryptionService {
  private readonly key: Buffer;
  private readonly algorithm = 'aes-256-gcm';
  private readonly ivLength = 16; // For GCM, IV is typically 12 or 16 bytes
  private readonly authTagLength = 16;

  constructor(private readonly configService: ConfigService) {
    const secretKey = this.configService.get<string>('ENCRYPTION_KEY');
    if (!secretKey) {
      throw new Error(
        'ENCRYPTION_KEY must be defined in .env '
      );
    }

    if (secretKey.length !== 32) {
      console.log('Provided ENCRYPTION_KEY:', secretKey);
      console.log('Provided ENCRYPTION_KEY length:', secretKey.length);
      throw new Error('ENCRYPTION_KEY must be 32 characters long.');
    }
    this.key = Buffer.from(secretKey, 'utf-8');
  }

  /**
   * Encrypts a plaintext string.
   * @param text The plaintext to encrypt.
   * @returns A string containing the IV, auth tag, and encrypted text, separated by colons.
   */
  encrypt(text: string): string {
    const iv = crypto.randomBytes(this.ivLength);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);
    const encrypted = Buffer.concat([
      cipher.update(text, 'utf8'),
      cipher.final(),
    ]);
    const authTag = cipher.getAuthTag();

    // Combine IV, auth tag, and encrypted text into a single string for storage
    return `${iv.toString('hex')}:${authTag.toString('hex')}:${encrypted.toString('hex')}`;
  }

  /**
   * Decrypts a string that was encrypted with the encrypt method.
   * @param encryptedText The encrypted string (IV:authTag:encrypted).
   * @returns The original plaintext string.
   */
  decrypt(encryptedText: string): string {
    try {
      const parts = encryptedText.split(':');
      if (parts.length !== 3) {
        throw new Error('Invalid encrypted text format');
      }

      const iv = Buffer.from(parts[0], 'hex');
      const authTag = Buffer.from(parts[1], 'hex');
      const encrypted = Buffer.from(parts[2], 'hex');

      const decipher = crypto.createDecipheriv(this.algorithm, this.key, iv);
      decipher.setAuthTag(authTag);

      const decrypted = Buffer.concat([
        decipher.update(encrypted),
        decipher.final(),
      ]);
      return decrypted.toString('utf8');
    } catch (error) {
      // Log the error or handle it as needed, but avoid exposing details.
      console.error('Decryption failed:', error);
      throw new Error('Could not decrypt token.');
    }
  }
}

