import {
  Injectable,
  ConflictException,
  Inject,
  NotFoundException,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { UserService } from '../user/user.service';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import {
  RegisterDto,
  ResendVerificationDto,
} from '@live-chat/shared-dtos';
import { User } from '../database/entities';
import { ConfigService } from '@nestjs/config';
import { EntityManager } from 'typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { type Cache } from 'cache-manager';
import { MailService } from '../mail/mail.service';
import { TokenService } from './services/token.service';
import { PasswordService } from './services/password.service';
import { OAuthService } from './services/oauth.service';

export type LoginResult = 
  | { status: 'success'; tokens: { accessToken: string; refreshToken: string }; user: User }
  | { status: '2fa_required'; partialToken: string };

@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    private readonly userService: UserService,
    private readonly configService: ConfigService,
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly mailService: MailService,
    private readonly tokenService: TokenService,
    private readonly passwordService: PasswordService,
    private readonly oauthService: OAuthService,
  ) {}

  async register(registerDto: RegisterDto): Promise<{ message: string }> {
    this.logger.log(`🔵 [Register] Starting registration for email: ${registerDto.email}`);

    return await this.entityManager.transaction(async (entityManager) => {
      const existingUser = await this.userService.findOneByEmail(registerDto.email);
      if (existingUser) {
        throw new ConflictException('Email này đã được sử dụng.');
      }

      const passwordHash = await bcrypt.hash(registerDto.password, 12);

      const newUser = await entityManager.save(User, {
        email: registerDto.email,
        passwordHash,
        fullName: registerDto.fullName,
        isEmailVerified: false,
      });

      this.logger.log(`✅ [Register] User created with ID: ${newUser.id}`);

      const verificationToken = crypto.randomBytes(32).toString('hex');
      const tokenKey = `verification-token:${verificationToken}`;
      await this.cacheManager.set(tokenKey, newUser.id, 900000); // 15 minutes

      await this.mailService.sendUserConfirmation(newUser, verificationToken);

      if (registerDto.invitationToken) {
        try {
          const invitationKey = `pending-invitation:${newUser.id}`;
          await this.cacheManager.set(invitationKey, registerDto.invitationToken, 604800000);
        } catch (error) {
          this.logger.error(`❌ [Register] Failed to store invitation token`, error);
        }
      }

      return {
        message: 'Đăng ký thành công, vui lòng kiểm tra email để kích hoạt tài khoản.',
      };
    });
  }

  async verifyEmail(token: string): Promise<{ message: string; invitationToken?: string }> {
    const tokenKey = `verification-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      throw new NotFoundException('Token xác thực không hợp lệ hoặc đã hết hạn.');
    }

    await this.userService.markEmailAsVerified(userId);
    await this.cacheManager.del(tokenKey);

    const invitationKey = `pending-invitation:${userId}`;
    const invitationToken = await this.cacheManager.get<string>(invitationKey);

    if (invitationToken) {
      return {
        message: 'Xác thực email thành công.',
        invitationToken,
      };
    }

    return { message: 'Xác thực email thành công.' };
  }

  async resendVerificationEmail(resendVerificationDto: ResendVerificationDto): Promise<{ message: string }> {
    const user = await this.userService.findOneByEmail(resendVerificationDto.email);

    if (!user) {
      return {
        message: 'Nếu tài khoản của bạn tồn tại, một email xác thực đã được gửi đi.',
      };
    }

    if (user.isEmailVerified) {
      throw new ConflictException('Email này đã được xác thực.');
    }

    const verificationToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `verification-token:${verificationToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000);

    await this.mailService.sendUserConfirmation(user, verificationToken);

    return {
      message: 'Một email xác thực mới đã được gửi. Vui lòng kiểm tra hộp thư của bạn.',
    };
  }

  async login(user: User, ipAddress?: string, userAgent?: string): Promise<LoginResult> {
    if (user.isTwoFactorAuthenticationEnabled) {
      const { accessToken } = await this.tokenService.generate2FAPartialToken(user.id);
      return { status: '2fa_required', partialToken: accessToken };
    }

    const tokens = await this.tokenService.generateTokens(user.id, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.tokenService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId: user.id,
      expiresAt,
      ipAddress,
      userAgent,
    });

    await this.userService.updateLastLogin(user.id);

    return { status: 'success', tokens, user };
  }

  /**
   * Login after 2FA verification - skips 2FA check since user already verified.
   */
  async loginAfter2FA(user: User, ipAddress?: string, userAgent?: string) {
    const tokens = await this.tokenService.generateTokens(user.id, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.tokenService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId: user.id,
      expiresAt,
      ipAddress,
      userAgent,
    });

    await this.userService.updateLastLogin(user.id);

    const { passwordHash, ...safeUser } = user;
    return { 
      accessToken: tokens.accessToken, 
      refreshToken: tokens.refreshToken, 
      user: { ...safeUser, hasPassword: !!passwordHash }
    };
  }

  async exchangeCodeForTokens(code: string, ip: string, userAgent: string) {
    const userId = await this.oauthService.validateOneTimeCode(code);
    const user = await this.userService.findOneById(userId);

    if (!user) {
      throw new UnauthorizedException('User not found.');
    }

    const loginResult = await this.login(user, ip, userAgent);

    if (loginResult.status === '2fa_required') {
      // Should not happen in current flow as OAuth usually bypasses 2FA or handles it differently,
      // but if we enforce 2FA on OAuth users, we need to handle it.
      // For now, assuming OAuth users are verified.
      // However, if 2FA is enabled, we must respect it.
      throw new UnauthorizedException({
        message: '2FA required',
        errorCode: '2FA_REQUIRED',
        partialToken: loginResult.partialToken
      });
    }

    return {
      accessToken: loginResult.tokens.accessToken,
      refreshToken: loginResult.tokens.refreshToken,
      user: {
        ...user,
        hasPassword: !!user.passwordHash
      }
    };
  }

  // Facade methods delegating to specific services
  async validateUser(email: string, pass: string) {
    return this.passwordService.validateUser(email, pass);
  }

  async changePassword(userId: string, current: string | undefined, newPass: string) {
    return this.passwordService.changePassword(userId, current, newPass);
  }

  async setPassword(userId: string, newPass: string) {
    return this.passwordService.setPassword(userId, newPass);
  }

  async forgotPassword(email: string) {
    return this.passwordService.forgotPassword(email);
  }

  async resetPassword(token: string, newPass: string) {
    return this.passwordService.resetPassword(token, newPass);
  }

  async validateOAuthUser(profile: any) {
    return this.oauthService.validateOAuthUser(profile);
  }

  async generateOneTimeCode(userId: string) {
    return this.oauthService.generateOneTimeCode(userId);
  }

  async linkGoogleAccount(userId: string, profile: any) {
    const result = await this.oauthService.linkGoogleAccount(userId, profile);
    const { passwordHash, ...userResult } = result.user;
    return {
      message: result.message,
      user: { ...userResult, hasPassword: !!passwordHash }
    };
  }

  async unlinkOAuthAccount(userId: string, provider: string) {
    return this.oauthService.unlinkOAuthAccount(userId, provider);
  }

  async getLinkedAccounts(userId: string) {
    return this.oauthService.getLinkedAccounts(userId);
  }

  async logout(userId: string, refreshToken: string) {
    return this.tokenService.revokeRefreshToken(userId, refreshToken);
  }

  async logoutAll(userId: string) {
    await this.tokenService.removeAllRefreshTokensForUser(userId);
    await this.tokenService.invalidateAllTokens(userId);
  }

  async refreshTokens(userId: string, refreshToken: string) {
    return this.tokenService.refreshUserTokens(userId, refreshToken);
  }

  async verifyEmailChange(token: string) {
    return this.userService.verifyEmailChange(token);
  }

  // Helper for 2FA controller
  async generate2FAPartialToken(userId: string) {
    return this.tokenService.generate2FAPartialToken(userId);
  }

  // Helper to get user by ID (used by controllers after password change)
  async findUserById(userId: string) {
    return this.userService.findOneById(userId);
  }
}

import {
  Injectable,
  ConflictException,
  ForbiddenException,
  UnauthorizedException,
  Inject,
  NotFoundException,
  Logger,
  BadRequestException,
} from '@nestjs/common';
import { UserService } from '../user/user.service';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import {
  RegisterDto,
  ResendVerificationDto,
  ForgotPasswordDto,
  ResetPasswordDto,
} from '@live-chat/shared-dtos';
import {
  User,
  RefreshToken,
  UserIdentity,
} from '../database/entities';

import { UserStatus } from '@live-chat/shared-types';
import { ConfigService } from '@nestjs/config';
import { EntityManager } from 'typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { type Cache } from 'cache-manager';
import { MailService } from '../mail/mail.service';

/**
 * Service responsible for all authentication-related business logic.
 * This includes user registration, email verification, login, token management,
 * password changes, 2FA partial token generation, OAuth user validation,
 * and account linking/unlinking.
 */
@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    private readonly userService: UserService,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly mailService: MailService
  ) {}

  /**
   * Registers a new user with the provided credentials.
   * Handles password hashing, email verification token generation,
   * sending confirmation email, and optionally storing an invitation token.
   *
   * @param registerDto - Data transfer object containing user registration details (email, password, fullName, invitationToken).
   * @returns A promise that resolves to an object with a success message.
   * @throws ConflictException if the email is already in use.
   */
  async register(registerDto: RegisterDto): Promise<{ message: string }> {
    this.logger.log(
      `🔵 [Register] Starting registration for email: ${registerDto.email}`
    );
    this.logger.log(
      `🔵 [Register] Has invitation token: ${!!registerDto.invitationToken}`
    );
    if (registerDto.invitationToken) {
      this.logger.log(
        `🔵 [Register] Invitation token: ${registerDto.invitationToken}`
      );
    }

    return await this.entityManager.transaction(async (entityManager) => {
      const existingUser = await this.userService.findOneByEmail(
        registerDto.email
      );
      if (existingUser) {
        throw new ConflictException('Email này đã được sử dụng.');
      }

      const passwordHash = await bcrypt.hash(registerDto.password, 12);

      const newUser = await entityManager.save(User, {
        email: registerDto.email,
        passwordHash,
        fullName: registerDto.fullName,
        isEmailVerified: false, // Explicitly set to false
      });

      this.logger.log(`✅ [Register] User created with ID: ${newUser.id}`);

      const verificationToken = crypto.randomBytes(32).toString('hex');
      const tokenKey = `verification-token:${verificationToken}`;
      await this.cacheManager.set(tokenKey, newUser.id, 900000); // 15 minutes

      this.logger.log(`✅ [Register] Verification token stored in Redis`);

      await this.mailService.sendUserConfirmation(newUser, verificationToken);

      // Handle invitation token if provided
      if (registerDto.invitationToken) {
        try {
          // Store invitation token for later acceptance (after email verification)
          const invitationKey = `pending-invitation:${newUser.id}`;
          await this.cacheManager.set(
            invitationKey,
            registerDto.invitationToken,
            604800000 // 7 days in milliseconds
          );
          this.logger.log(
            `✅ [Register] Stored invitation token for user ${newUser.id}: ${registerDto.invitationToken}`
          );
        } catch (error) {
          this.logger.error(
            `❌ [Register] Failed to store invitation token for user ${newUser.id}`,
            error
          );
          // Don't fail registration if invitation storage fails
        }
      } else {
        this.logger.log(
          `ℹ️ [Register] No invitation token provided for user ${newUser.id}`
        );
      }

      return {
        message:
          'Đăng ký thành công, vui lòng kiểm tra email để kích hoạt tài khoản.',
      };
    });
  }

  /**
   * Verifies a user's email address using a provided token.
   * Marks the email as verified and deletes the verification token.
   * If a pending invitation token exists for the user, it is returned.
   *
   * @param token - The email verification token received via email.
   * @returns A promise that resolves to an object with a success message and an optional invitation token.
   * @throws NotFoundException if the token is invalid or expired.
   */
  async verifyEmail(
    token: string
  ): Promise<{ message: string; invitationToken?: string }> {
    this.logger.log(
      `🔵 [VerifyEmail] Starting email verification with token: ${token}`
    );

    const tokenKey = `verification-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      this.logger.error(
        `❌ [VerifyEmail] Token not found or expired: ${token}`
      );
      throw new NotFoundException(
        'Token xác thực không hợp lệ hoặc đã hết hạn.'
      );
    }

    this.logger.log(`✅ [VerifyEmail] Found userId from token: ${userId}`);

    await this.userService.markEmailAsVerified(userId);
    await this.cacheManager.del(tokenKey);

    this.logger.log(`✅ [VerifyEmail] Email verified for user: ${userId}`);

    // Check if there's a pending invitation for this user
    const invitationKey = `pending-invitation:${userId}`;
    const invitationToken = await this.cacheManager.get<string>(invitationKey);

    if (invitationToken) {
      this.logger.log(
        `🎉 [VerifyEmail] User ${userId} has a pending invitation token: ${invitationToken}. Returning it in response.`
      );
      // Return the invitation token so the frontend can redirect the user
      return {
        message: 'Xác thực email thành công.',
        invitationToken,
      };
    }

    this.logger.log(
      `ℹ️ [VerifyEmail] No pending invitation found for user: ${userId}`
    );
    return { message: 'Xác thực email thành công.' };
  }

  /**
   * Resends an email verification link to the specified email address.
   * Generates a new verification token and sends a new confirmation email.
   *
   * @param resendVerificationDto - Data transfer object containing the email to resend verification to.
   * @returns A promise that resolves to an object with a success message.
   * @throws ConflictException if the email is already verified.
   */
  async resendVerificationEmail(
    resendVerificationDto: ResendVerificationDto
  ): Promise<{ message: string }> {
    const user = await this.userService.findOneByEmail(
      resendVerificationDto.email
    );

    if (!user) {
      // To prevent email enumeration, we send a generic success message even if the user doesn't exist.
      return {
        message:
          'Nếu tài khoản của bạn tồn tại, một email xác thực đã được gửi đi.',
      };
    }

    if (user.isEmailVerified) {
      throw new ConflictException('Email này đã được xác thực.');
    }

    const verificationToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `verification-token:${verificationToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000); // 15 minutes

    await this.mailService.sendUserConfirmation(user, verificationToken);

    return {
      message:
        'Một email xác thực mới đã được gửi. Vui lòng kiểm tra hộp thư của bạn.',
    };
  }

  /**
   * Validates user credentials (email and password).
   * Checks if the user exists, if the password is correct, and if the user's status allows login.
   *
   * @param email - The user's email address.
   * @param pass - The user's plain text password.
   * @returns A promise that resolves to the User object if credentials are valid, otherwise null.
   * @throws ForbiddenException if email/password is incorrect or user is suspended.
   */
  async validateUser(email: string, pass: string): Promise<User | null> {
    const user = await this.userService.findOneByEmail(email);

    if (!user) {
      throw new ForbiddenException('Email hoặc mật khẩu không đúng.');
    }

    if (user && (await bcrypt.compare(pass, user.passwordHash as string))) {
      if (user.status === UserStatus.SUSPENDED) {
        throw new ForbiddenException('Tài khoản của bạn đã bị đình chỉ.');
      }

      if (user.status === UserStatus.INACTIVE) {
        return this.userService.activate(user.id);
      }

      return user;
    }
    return null;
  }

  /**
   * Allows an authenticated user to change their password.
   * Requires the current password for verification if one is set.
   * Logs out all sessions after a successful password change for security.
   *
   * @param userId - The ID of the authenticated user.
   * @param currentPassword - The user's current password (optional for OAuth users setting a password for the first time).
   * @param newPassword - The new password for the user.
   * @returns A promise that resolves when the password has been successfully changed.
   * @throws UnauthorizedException if the user does not exist.
   * @throws BadRequestException if current password is required but not provided.
   * @throws ForbiddenException if the current password is incorrect.
   */
  async changePassword(
    userId: string,
    currentPassword: string | undefined,
    newPassword: string
  ): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      // If user has a password, require current password verification
      if (user.passwordHash) {
        if (!currentPassword) {
          throw new BadRequestException({
            message: 'Mật khẩu hiện tại là bắt buộc khi bạn đã có mật khẩu.',
            errorCode: 'CURRENT_PASSWORD_REQUIRED',
          });
        }

        const isPasswordValid = await bcrypt.compare(
          currentPassword,
          user.passwordHash
        );
        if (!isPasswordValid) {
          throw new ForbiddenException({
            message: 'Mật khẩu hiện tại không đúng.',
            errorCode: 'WRONG_PASSWORD',
          });
        }
      }
      // If user doesn't have a password (OAuth account), they can set one without current password
      else {
        this.logger.log(
          `User ${userId} is setting password for the first time (OAuth account)`
        );
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      await this.logoutAll(userId);
    });
  }

  /**
   * Allows an authenticated user to set a password for their account if they don't already have one (e.g., OAuth-only users).
   *
   * @param userId - The ID of the authenticated user.
   * @param newPassword - The new password to set for the user.
   * @returns A promise that resolves when the password has been successfully set.
   * @throws UnauthorizedException if the user does not exist.
   * @throws BadRequestException if the user already has a password.
   */
  async setPassword(userId: string, newPassword: string): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      // Only allow setting password if user doesn't have one
      if (user.passwordHash) {
        throw new BadRequestException({
          message:
            'Bạn đã có mật khẩu. Vui lòng sử dụng chức năng đổi mật khẩu.',
          errorCode: 'PASSWORD_ALREADY_EXISTS',
        });
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      this.logger.log(`User ${userId} has set their password successfully`);
    });
  }

  /**
   * Log in a user by generating access and refresh tokens.
   * The refresh token is stored in the database and the access token is returned to the client.
   *
   * @param user - The user entity for whom to generate tokens.
   * @param ipAddress - The IP address of the user (optional).
   * @param userAgent - The user agent string of the user's device (optional).
   * @returns A promise that resolves to an object containing the access token, refresh token, and user information (without password hash).
   */
  async loginAndReturnTokens(
    user: User,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{
    accessToken: string;
    refreshToken: string;
    user: Omit<User, 'passwordHash'> & { hasPassword: boolean };
  }> {
    const tokens = await this._generateTokens(user.id, user.email);

    const liveTime =
      this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 30);

    // Calculate expiration date (30 days from now)
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    // Use UserService method to set refresh token
    await this.userService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId: user.id,
      expiresAt,
      ipAddress,
      userAgent,
    });

    await this.userService.updateLastLogin(user.id);
    const { passwordHash, ...userResult } = user;

    return {
      ...tokens,
      user: {
        ...userResult,
        hasPassword: !!passwordHash, // Add hasPassword field to indicate if user has a password
      },
    };
  }

  /**
   * Generates a partial JWT token for 2FA authentication flow.
   * This token indicates that 2FA is required but not yet completed.
   *
   * @param userId - The ID of the user requiring 2FA.
   * @returns A promise that resolves to an object containing the partial access token.
   */
  async generate2FAPartialToken(userId: string) {
    const payload = {
      sub: userId,
      isTwoFactorAuthenticated: false,
      is2FA: true, // A flag to identify this as a 2FA-required token
    };

    const accessToken = await this.jwtService.signAsync(payload, {
      secret: this.configService.get<string>('TWO_FACTOR_AUTH_JWT_SECRET'),
      expiresIn: this.configService.get<string>(
        'TWO_FACTOR_AUTH_JWT_EXPIRES_IN'
      ),
    });
    return { accessToken };
  }

  /**
   * Logs out a user by invalidating a specific refresh token.
   * Iterates through all refresh tokens for the user and deletes any that match the provided raw refresh token.
   *
   * @param userId - The ID of the user to log out.
   * @param rawRefreshToken - The raw refresh token to invalidate.
   * @returns A promise that resolves when the refresh token(s) have been deleted.
   */
  async logout(userId: string, rawRefreshToken: string): Promise<void> {
    const userTokens = await this.entityManager.find(RefreshToken, {
      where: { userId },
    });

    console.log('User tokens:', userTokens);

    if (!userTokens || userTokens.length === 0) {
      return;
    }

    for (const token of userTokens) {
      console.log('Checking token:', token);
      const isMatch = await bcrypt.compare(rawRefreshToken, token.hashedToken);
      if (isMatch) {
        await this.entityManager.delete(RefreshToken, token.id);
      }
    }
  }

  /**
   * Logs out a user from all sessions by removing all their refresh tokens.
   * Also invalidates all JWTs issued to the user.
   *
   * @param userId - The ID of the user to log out from all sessions.
   * @returns A promise that resolves when all refresh tokens and JWTs are invalidated.
   */
  async logoutAll(userId: string): Promise<void> {
    await this.userService.removeAllRefreshTokensForUser(userId);
    await this.userService.invalidateAllTokens(userId);
  }

  /**
   * Refreshes access and refresh tokens for a user using a valid refresh token.
   * Verifies the provided refresh token, generates new tokens, and updates the stored refresh token in the database.
   *
   * @param userId - The unique identifier of the user.
   * @param refreshToken - The refresh token to verify.
   * @returns A promise that resolves to an object containing the new access and refresh tokens.
   * @throws ForbiddenException if access is denied (e.g., user not active, token invalid).
   * @throws UnauthorizedException if the login session has expired.
   */
  async refreshTokens(userId: string, refreshToken: string) {
    const user = await this.userService.findOneById(userId);
    if (!user || user.status !== UserStatus.ACTIVE) {
      throw new ForbiddenException('Access Denied');
    }

    try {
      // Verify the refresh token using the injected UserService instance
      const isValidToken = await this.userService.verifyRefreshToken(
        refreshToken,
        userId
      );

      // If token is not valid (doesn't exist), it's a security risk.
      // Log out all sessions.
      if (!isValidToken) {
        await this.logoutAll(userId);
        throw new ForbiddenException('Access Denied');
      }
    } catch (error) {
      // If the error is due to an expired token, re-throw it so the user
      // gets a clear message to log in again.
      if (error instanceof UnauthorizedException) {
        throw new UnauthorizedException(
          'Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại.'
        );
      }
      // For any other unexpected errors, re-throw them.
      throw error;
    }

    // If we reach here, the token was valid. Proceed with rotation.
    const tokens = await this._generateTokens(userId, user.email);
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    // Set the new refresh token (this will remove the old one)
    await this.userService.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId,
      expiresAt,
      expiredRefreshToken: refreshToken,
    });

    return tokens;
  }

  /**
   * Private helper method to generate a new pair of access and refresh tokens.
   *
   * @param userId - The ID of the user.
   * @param email - The email of the user.
   * @returns A promise that resolves to an object containing the generated access and refresh tokens.
   */
  private async _generateTokens(userId: string, email: string) {
    const accessTokenPayload = { sub: userId, email };
    const [accessToken, refreshToken] = await Promise.all([
      // Generate Access Token
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_SECRET'),
        expiresIn: this.configService.get<string>('JWT_EXPIRES_IN'),
      }),
      // Generate Refresh Token (also JWT)
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_REFRESH_SECRET'),
        expiresIn: this.configService.get<string>('JWT_REFRESH_EXPIRES_IN'),
      }),
    ]);
    return { accessToken, refreshToken };
  }

  /**
   * Validates a user from an OAuth provider (e.g., Google).
   * This method handles linking existing identities, linking to existing users by email,
   * or creating new users and identities if none exist.
   *
   * @param profile - The OAuth profile data containing provider, providerId, email, name, and avatarUrl.
   * @returns A promise that resolves to the User object after validation or creation.
   */
  async validateOAuthUser(profile: {
    provider: string;
    providerId: string;
    email: string;
    name: string;
    avatarUrl: string;
  }): Promise<User> {
    // Wrap all logic in a transaction to ensure data integrity
    return this.entityManager.transaction(async (entityManager) => {
      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      // 1. User already exists with this provider
      if (existingIdentity) {
        const user = existingIdentity.user;
        // Ensure email is marked as verified since OAuth provider has verified it
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          await entityManager.save(user);
        }
        return user;
      }

      // 2. Link with an existing account with the same email
      let user = await entityManager.findOne(User, {
        where: { email: profile.email },
      });

      if (user) {
        // Update user information from Google profile if not already set
        // and mark email as verified since Google has already verified it
        let needsUpdate = false;

        // Update avatar if not set
        if (!user.avatarUrl && profile.avatarUrl) {
          user.avatarUrl = profile.avatarUrl;
          needsUpdate = true;
        }

        // Update full name if not set or is empty
        if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
          user.fullName = profile.name;
          needsUpdate = true;
        }

        // Mark email as verified
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          needsUpdate = true;
        }

        if (needsUpdate) {
          await entityManager.save(user);
        }
      }
      // If no user found with the email, create a new user
      else {
        // 3. Create a completely new user with verified email
        // since Google has already verified this email
        user = entityManager.create(User, {
          email: profile.email,
          fullName: profile.name,
          avatarUrl: profile.avatarUrl,
          isEmailVerified: true, // Email is already verified by Google
        });
        await entityManager.save(user);
      }

      // Create new identity for the user
      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user, // Directly assign the User object
      });
      await entityManager.save(newIdentity);

      return user;
    });
  }

  /**
   * Generates a one-time code for temporary use, typically for OAuth callbacks or state management.
   * The code is stored in Redis with an expiration time.
   *
   * @param userId - The ID of the user associated with the one-time code.
   * @returns A promise that resolves to the generated one-time code.
   */
  async generateOneTimeCode(userId: string): Promise<string> {
    const code = crypto.randomBytes(32).toString('hex');
    const key = `one-time-code:${code}`;
    const fiveMinutesInMs = 5 * 60 * 1000;

    // Store key-value in Redis with an expiration time (TTL) of 5 minutes
    await this.cacheManager.set(key, userId, fiveMinutesInMs);
    console.log('Storing one-time code in Redis with key:', key);

    const userid = await this.cacheManager.get<string>(key);
    console.log('Retrieved userId from Redis for key:', key, 'userId:', userid);
    return code;
  }

  /**
   * Exchanges a one-time code (e.g., from an OAuth callback) for full access and refresh tokens.
   * Invalidates the one-time code after use.
   *
   * @param code - The one-time code to exchange.
   * @param ip - The IP address of the client.
   * @param userAgent - The user agent string of the client.
   * @returns A promise that resolves to an object containing the access token, refresh token, and user information.
   * @throws UnauthorizedException if the code is invalid or expired, or if the user is not found.
   */
  async exchangeCodeForTokens(
    code: string,
    ip: string,
    userAgent: string
  ): Promise<{
    accessToken: string;
    refreshToken: string;
    user: Omit<User, 'passwordHash'>;
  }> {
    const key = `one-time-code:${code}`;

    // 1. Get userId from Redis by key
    const userId = await this.cacheManager.get<string>(key);

    // 2. Validate the code
    if (!userId) {
      throw new UnauthorizedException(
        `No user found with key ${key}, invalid or expired code.`
      );
    }
    console.log('One-time code valid for userId:', userId);
    // 3. Invalidate the code immediately by deleting it from Redis
    await this.cacheManager.del(key);

    // 4. Get user information and create tokens (this logic remains the same)
    const user = await this.userService.findOneById(userId);
    if (!user) {
      throw new UnauthorizedException('User not found.');
    }

    return await this.loginAndReturnTokens(user, ip, userAgent);
  }

  /**
   * Handle forgot password request.
   * Sends a password reset email with a token.
   * Generates a reset token and stores it in Redis.
   *
   * @param email - The email address of the user who forgot their password.
   * @returns A promise that resolves to a success message, indicating if an email was sent or if an email was sent or if the user is OAuth-only.
   */
  async forgotPassword(
    email: string
  ): Promise<{ message: string; isOAuthUser?: boolean }> {
    this.logger.log(`🔵 [ForgotPassword] Request for email: ${email}`);

    const user = await this.userService.findOneByEmail(email);

    // To prevent email enumeration, we always return the same success message
    // regardless of whether the user exists or not
    if (!user) {
      this.logger.log(`ℹ️ [ForgotPassword] User not found for email: ${email}`);
      return {
        message:
          'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
      };
    }

    // Check if user has a password (OAuth users might not have one)
    if (!user.passwordHash) {
      this.logger.log(
        `⚠️ [ForgotPassword] User ${user.id} has no password (OAuth account)`
      );
      return {
        message:
          'Tài khoản này được đăng nhập bằng Google. Vui lòng sử dụng nút "Đăng nhập bằng Google" để truy cập.',
        isOAuthUser: true,
      };
    }

    // Generate reset token
    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `reset-password-token:${resetToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000); // 15 minutes

    this.logger.log(
      `✅ [ForgotPassword] Reset token stored in Redis for user: ${user.id}`
    );

    // Send reset email
    await this.mailService.sendPasswordResetEmail(user, resetToken);

    this.logger.log(`✅ [ForgotPassword] Reset email sent to: ${user.email}`);

    return {
      message:
        'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
    };
  }

  /**
   * Resets a user's password using a valid reset token.
   * Hashes the new password, updates the user record, deletes the reset token, and logs out all sessions for security.
   *
   * @param token - The password reset token received via email.
   * @param newPassword - The new password for the user.
   * @returns A promise that resolves to a success message.
   * @throws BadRequestException if the token is invalid or expired.
   * @throws NotFoundException if the user associated with the token does not exist.
   */
  async resetPassword(
    token: string,
    newPassword: string
  ): Promise<{ message: string }> {
    this.logger.log(`🔵 [ResetPassword] Attempting to reset password`);

    const tokenKey = `reset-password-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      this.logger.error(`❌ [ResetPassword] Token not found or expired`);
      throw new BadRequestException(
        'Token đặt lại mật khẩu không hợp lệ hoặc đã hết hạn.'
      );
    }

    this.logger.log(`✅ [ResetPassword] Found userId from token: ${userId}`);

    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new NotFoundException('Người dùng không tồn tại.');
      }

      // Hash new password
      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      this.logger.log(
        `✅ [ResetPassword] Password updated for user: ${userId}`
      );

      // Delete the reset token (one-time use)
      await this.cacheManager.del(tokenKey);

      this.logger.log(`✅ [ResetPassword] Reset token deleted`);

      // Logout all sessions for security
      await this.logoutAll(userId);

      this.logger.log(
        `✅ [ResetPassword] All sessions logged out for user: ${userId}`
      );

      return {
        message:
          'Mật khẩu đã được đặt lại thành công. Vui lòng đăng nhập với mật khẩu mới.',
      };
    });
  }

  /**
   * Links a Google account to an existing user account.
   * Performs checks for existing links, email mismatches, and updates user profile information.
   *
   * @param userId - The ID of the currently logged-in user.
   * @param profile - The Google OAuth profile data.
   * @returns A promise that resolves to a success message and updated user information.
   * @throws UnauthorizedException if the user does not exist.
   * @throws ConflictException if the Google account is already linked to this or another user.
   * @throws BadRequestException if the Google account email does not match the user's current email.
   */
  async linkGoogleAccount(
    userId: string,
    profile: {
      provider: string;
      providerId: string;
      email: string;
      name: string;
      avatarUrl: string;
    }
  ): Promise<{
    message: string;
    user: Omit<User, 'passwordHash'> & { hasPassword: boolean };
  }> {
    this.logger.log(
      `🔵 [LinkGoogleAccount] User ${userId} is linking Google account: ${profile.email}`
    );

    return this.entityManager.transaction(async (entityManager) => {
      // 1. Get the current user
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      // 2. Check if this Google account is already linked to another user
      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      if (existingIdentity) {
        if (existingIdentity.user.id === userId) {
          // Already linked to this user
          throw new ConflictException(
            'Tài khoản Google này đã được liên kết với tài khoản của bạn.'
          );
        } else {
          // Linked to a different user
          throw new ConflictException(
            'Tài khoản Google này đã được liên kết với một tài khoản khác.'
          );
        }
      }

      // 3. Check if the email matches (optional security check)
      if (user.email !== profile.email) {
        this.logger.warn(
          `⚠️ [LinkGoogleAccount] Email mismatch: user email ${user.email} vs Google email ${profile.email}`
        );
        throw new BadRequestException(
          'Email của tài khoản Google không khớp với email tài khoản hiện tại.'
        );
      }

      // 4. Create new identity for the user
      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user,
      });
      await entityManager.save(newIdentity);

      this.logger.log(
        `✅ [LinkGoogleAccount] Successfully linked Google account for user ${userId}`
      );

      // 5. Update user information from Google profile if not already set
      let needsUpdate = false;

      // Update avatar if not set
      if (!user.avatarUrl && profile.avatarUrl) {
        user.avatarUrl = profile.avatarUrl;
        needsUpdate = true;
      }

      // Update full name if not set or is empty
      if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
        user.fullName = profile.name;
        needsUpdate = true;
      }

      if (needsUpdate) {
        await entityManager.save(user);
      }

      // 6. Mark email as verified since Google has verified it
      if (!user.isEmailVerified) {
        user.isEmailVerified = true;
        await entityManager.save(user);
      }

      const { passwordHash, ...userResult } = user;

      return {
        message: 'Liên kết tài khoản Google thành công.',
        user: {
          ...userResult,
          hasPassword: !!passwordHash,
        },
      };
    });
  }

  /**
   * Unlinks an OAuth account (e.g., Google) from a user's profile.
   * Prevents unlinking if it's the user's only authentication method and they don't have a password set.
   *
   * @param userId - The ID of the user.
   * @param provider - The OAuth provider to unlink (e.g., 'google').
   * @returns A promise that resolves to a success message.
   * @throws UnauthorizedException if the user does not exist.
   * @throws BadRequestException if the user tries to unlink their only login method without a password.
   * @throws NotFoundException if the specified OAuth account is not linked.
   */
  async unlinkOAuthAccount(
    userId: string,
    provider: string
  ): Promise<{ message: string }> {
    this.logger.log(
      `🔵 [UnlinkOAuthAccount] User ${userId} is unlinking ${provider} account`
    );

    return this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      // Check if user has a password, if not, they can't unlink their only auth method
      if (!user.passwordHash) {
        throw new BadRequestException(
          'Bạn cần đặt mật khẩu trước khi hủy liên kết tài khoản Google. Điều này đảm bảo bạn vẫn có thể đăng nhập vào tài khoản.'
        );
      }

      const identity = await entityManager.findOne(UserIdentity, {
        where: { userId, provider },
      });

      if (!identity) {
        throw new NotFoundException(
          `Không tìm thấy tài khoản ${provider} được liên kết.`
        );
      }

      await entityManager.remove(identity);

      this.logger.log(
        `✅ [UnlinkOAuthAccount] Successfully unlinked ${provider} account for user ${userId}`
      );

      return {
        message: `Đã hủy liên kết tài khoản ${provider} thành công.`,
      };
    });
  }

  /**
   * Retrieves a list of all OAuth accounts linked to a specific user.
   *
   * @param userId - The ID of the user.
   * @returns A promise that resolves to an array of UserIdentity objects.
   */
  async getLinkedAccounts(userId: string): Promise<UserIdentity[]> {
    return this.entityManager.find(UserIdentity, {
      where: { userId },
    });
  }

  /**
   * Proxies the email change verification request to the UserService.
   *
   * @param token - The verification token for the email change.
   * @returns A promise that resolves to an object containing a success message and the new email.
   */
  async verifyEmailChange(
    token: string
  ): Promise<{ message: string; newEmail: string }> {
    return this.userService.verifyEmailChange(token);
  }
}

import {
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from '../../common/decorators/public.decorator';

/**
 * This Guard will automatically activate JwtStrategy.
 * When applied to a route, it will check the existence and validity of the JWT
 * in the Authorization header of the request.
 * If the token is valid, it will attach the authenticated payload to request.user.
 * If the token does not exist or is invalid, it will automatically throw an UnauthorizedException (401 error).
 */
@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }
    return super.canActivate(context);
  }

  handleRequest(err, user, info) {
    // If there's an error or user does not exist, throw UnauthorizedException
    if (err || !user) {
      throw new UnauthorizedException({
        message: info?.message || 'Unauthorized',
        error: 'Unauthorized',
        statusCode: 401,
        errorCode: 'TOKEN_INVALID',
      });
    }
    return user;
  }
}

import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

/**
 * Guard này sẽ tự động kích hoạt LocalStrategy.
 * Khi được áp dụng cho một route, nó sẽ chạy logic xác thực của passport-local.
 * Nếu xác thực thành công, nó sẽ gắn đối tượng user vào request (req.user).
 * Nếu thất bại, nó sẽ tự động ném ra một UnauthorizedException (lỗi 401).
 */
@Injectable()
export class LocalAuthGuard extends AuthGuard('local') {}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

/**
 * Guard for authenticating requests using a refresh token.
 * This guard activates the 'jwt-refresh' Passport strategy.
 * It expects a refresh token to be present in the request (e.g., in cookies).
 * If the token is valid, it attaches the authenticated user payload to `req.user`.
 * If authentication fails (e.g., missing, invalid, or expired token), it throws an `UnauthorizedException`.
 */
@Injectable()
export class RefreshTokenGuard extends AuthGuard('jwt-refresh') {
  handleRequest(err, user, info) {
    // If there's an error or user does not exist, throw UnauthorizedException
    if (err || !user) {
      throw new UnauthorizedException({
        message: info?.message || 'Unauthorized',
        error: 'Unauthorized',
        statusCode: 401,
        errorCode: 'TOKEN_INVALID',
      });
    }
    return user;
  }
}

import {
  Injectable,
  Inject,
  Logger,
  UnauthorizedException,
  ConflictException,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { EntityManager } from 'typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import * as crypto from 'crypto';
import { User, UserIdentity } from '../../database/entities';
import { UserService } from '../../user/user.service';

@Injectable()
export class OAuthService {
  private readonly logger = new Logger(OAuthService.name);

  constructor(
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly userService: UserService,
  ) {}

  async validateOAuthUser(profile: {
    provider: string;
    providerId: string;
    email: string;
    name: string;
    avatarUrl: string;
  }): Promise<User> {
    return this.entityManager.transaction(async (entityManager) => {
      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      if (existingIdentity) {
        const user = existingIdentity.user;
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          await entityManager.save(user);
        }
        return user;
      }

      let user = await entityManager.findOne(User, {
        where: { email: profile.email },
      });

      if (user) {
        let needsUpdate = false;
        if (!user.avatarUrl && profile.avatarUrl) {
          user.avatarUrl = profile.avatarUrl;
          needsUpdate = true;
        }
        if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
          user.fullName = profile.name;
          needsUpdate = true;
        }
        if (!user.isEmailVerified) {
          user.isEmailVerified = true;
          needsUpdate = true;
        }
        if (needsUpdate) {
          await entityManager.save(user);
        }
      } else {
        user = entityManager.create(User, {
          email: profile.email,
          fullName: profile.name,
          avatarUrl: profile.avatarUrl,
          isEmailVerified: true,
        });
        await entityManager.save(user);
      }

      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user,
      });
      await entityManager.save(newIdentity);

      return user;
    });
  }

  async generateOneTimeCode(userId: string): Promise<string> {
    const code = crypto.randomBytes(32).toString('hex');
    const key = `one-time-code:${code}`;
    const fiveMinutesInMs = 5 * 60 * 1000;
    await this.cacheManager.set(key, userId, fiveMinutesInMs);
    return code;
  }

  async validateOneTimeCode(code: string): Promise<string> {
    const key = `one-time-code:${code}`;
    const userId = await this.cacheManager.get<string>(key);

    if (!userId) {
      throw new UnauthorizedException(`No user found with key ${key}, invalid or expired code.`);
    }

    await this.cacheManager.del(key);
    return userId;
  }

  async linkGoogleAccount(
    userId: string,
    profile: {
      provider: string;
      providerId: string;
      email: string;
      name: string;
      avatarUrl: string;
    },
  ): Promise<{ message: string; user: User }> {
    this.logger.log(`🔵 [LinkGoogleAccount] User ${userId} is linking Google account: ${profile.email}`);

    return this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      const existingIdentity = await entityManager.findOne(UserIdentity, {
        where: { provider: profile.provider, providerId: profile.providerId },
        relations: ['user'],
      });

      if (existingIdentity) {
        if (existingIdentity.user.id === userId) {
          throw new ConflictException('Tài khoản Google này đã được liên kết với tài khoản của bạn.');
        } else {
          throw new ConflictException('Tài khoản Google này đã được liên kết với một tài khoản khác.');
        }
      }

      if (user.email !== profile.email) {
        this.logger.warn(`⚠️ [LinkGoogleAccount] Email mismatch: user email ${user.email} vs Google email ${profile.email}`);
        throw new BadRequestException('Email của tài khoản Google không khớp với email tài khoản hiện tại.');
      }

      const newIdentity = entityManager.create(UserIdentity, {
        provider: profile.provider,
        providerId: profile.providerId,
        user: user,
      });
      await entityManager.save(newIdentity);

      let needsUpdate = false;
      if (!user.avatarUrl && profile.avatarUrl) {
        user.avatarUrl = profile.avatarUrl;
        needsUpdate = true;
      }
      if ((!user.fullName || user.fullName.trim() === '') && profile.name) {
        user.fullName = profile.name;
        needsUpdate = true;
      }
      if (needsUpdate) {
        await entityManager.save(user);
      }

      if (!user.isEmailVerified) {
        user.isEmailVerified = true;
        await entityManager.save(user);
      }

      return {
        message: 'Liên kết tài khoản Google thành công.',
        user,
      };
    });
  }

  async unlinkOAuthAccount(userId: string, provider: string): Promise<{ message: string }> {
    return this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (!user.passwordHash) {
        throw new BadRequestException(
          'Bạn cần đặt mật khẩu trước khi hủy liên kết tài khoản Google. Điều này đảm bảo bạn vẫn có thể đăng nhập vào tài khoản.',
        );
      }

      const identity = await entityManager.findOne(UserIdentity, {
        where: { userId, provider },
      });

      if (!identity) {
        throw new NotFoundException(`Không tìm thấy tài khoản ${provider} được liên kết.`);
      }

      await entityManager.remove(identity);
      return { message: `Đã hủy liên kết tài khoản ${provider} thành công.` };
    });
  }

  async getLinkedAccounts(userId: string): Promise<UserIdentity[]> {
    return this.entityManager.find(UserIdentity, {
      where: { userId },
    });
  }
}

import {
  Injectable,
  Inject,
  Logger,
  UnauthorizedException,
  BadRequestException,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { UserService } from '../../user/user.service';
import { MailService } from '../../mail/mail.service';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import { EntityManager } from 'typeorm';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import { User } from '../../database/entities';
import { UserStatus } from '@live-chat/shared-types';
import { TokenService } from './token.service';

@Injectable()
export class PasswordService {
  private readonly logger = new Logger(PasswordService.name);

  constructor(
    private readonly userService: UserService,
    private readonly mailService: MailService,
    private readonly tokenService: TokenService,
    private readonly entityManager: EntityManager,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
  ) {}

  async validateUser(email: string, pass: string): Promise<User | null> {
    const user = await this.userService.findOneByEmail(email);

    if (!user) {
      throw new ForbiddenException('Email hoặc mật khẩu không đúng.');
    }

    if (user && user.passwordHash && (await bcrypt.compare(pass, user.passwordHash))) {
      if (user.status === UserStatus.SUSPENDED) {
        throw new ForbiddenException('Tài khoản của bạn đã bị đình chỉ.');
      }

      if (user.status === UserStatus.INACTIVE) {
        return this.userService.activate(user.id);
      }

      return user;
    }
    return null;
  }

  async changePassword(userId: string, currentPassword: string | undefined, newPassword: string): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (user.passwordHash) {
        if (!currentPassword) {
          throw new BadRequestException({
            message: 'Mật khẩu hiện tại là bắt buộc khi bạn đã có mật khẩu.',
            errorCode: 'CURRENT_PASSWORD_REQUIRED',
          });
        }

        const isPasswordValid = await bcrypt.compare(currentPassword, user.passwordHash);
        if (!isPasswordValid) {
          throw new ForbiddenException({
            message: 'Mật khẩu hiện tại không đúng.',
            errorCode: 'WRONG_PASSWORD',
          });
        }
      } else {
        this.logger.log(`User ${userId} is setting password for the first time (OAuth account)`);
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      // Logout all sessions
      await this.tokenService.removeAllRefreshTokensForUser(userId);
      await this.tokenService.invalidateAllTokens(userId);
    });
  }

  async setPassword(userId: string, newPassword: string): Promise<void> {
    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new UnauthorizedException('Người dùng không tồn tại.');
      }

      if (user.passwordHash) {
        throw new BadRequestException({
          message: 'Bạn đã có mật khẩu. Vui lòng sử dụng chức năng đổi mật khẩu.',
          errorCode: 'PASSWORD_ALREADY_EXISTS',
        });
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      this.logger.log(`User ${userId} has set their password successfully`);
    });
  }

  async forgotPassword(email: string): Promise<{ message: string; isOAuthUser?: boolean }> {
    this.logger.log(`🔵 [ForgotPassword] Request for email: ${email}`);
    const user = await this.userService.findOneByEmail(email);

    if (!user) {
      this.logger.log(`ℹ️ [ForgotPassword] User not found for email: ${email}`);
      return {
        message: 'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
      };
    }

    if (!user.passwordHash) {
      this.logger.log(`⚠️ [ForgotPassword] User ${user.id} has no password (OAuth account)`);
      return {
        message: 'Tài khoản này được đăng nhập bằng Google. Vui lòng sử dụng nút "Đăng nhập bằng Google" để truy cập.',
        isOAuthUser: true,
      };
    }

    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenKey = `reset-password-token:${resetToken}`;
    await this.cacheManager.set(tokenKey, user.id, 900000); // 15 minutes

    await this.mailService.sendPasswordResetEmail(user, resetToken);
    this.logger.log(`✅ [ForgotPassword] Reset email sent to: ${user.email}`);

    return {
      message: 'Nếu email của bạn tồn tại trong hệ thống, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.',
    };
  }

  async resetPassword(token: string, newPassword: string): Promise<{ message: string }> {
    this.logger.log(`�� [ResetPassword] Attempting to reset password`);

    const tokenKey = `reset-password-token:${token}`;
    const userId = await this.cacheManager.get<string>(tokenKey);

    if (!userId) {
      this.logger.error(`❌ [ResetPassword] Token not found or expired`);
      throw new BadRequestException('Token đặt lại mật khẩu không hợp lệ hoặc đã hết hạn.');
    }

    return await this.entityManager.transaction(async (entityManager) => {
      const user = await this.userService.findOneById(userId);
      if (!user) {
        throw new NotFoundException('Người dùng không tồn tại.');
      }

      const newHashedPassword = await bcrypt.hash(newPassword, 12);
      user.passwordHash = newHashedPassword;
      await entityManager.save(user);

      await this.cacheManager.del(tokenKey);

      // Logout all sessions
      await this.tokenService.removeAllRefreshTokensForUser(userId);
      await this.tokenService.invalidateAllTokens(userId);

      this.logger.log(`✅ [ResetPassword] Password updated and sessions logged out for user: ${userId}`);

      return {
        message: 'Mật khẩu đã được đặt lại thành công. Vui lòng đăng nhập với mật khẩu mới.',
      };
    });
  }
}

import { Injectable, Logger, UnauthorizedException, Inject } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, EntityManager, LessThan } from 'typeorm';
import { RefreshToken, User } from '../../database/entities';
import * as bcrypt from 'bcrypt';
import { Cron, CronExpression } from '@nestjs/schedule';
import { UserStatus } from '@live-chat/shared-types';
import { UserService } from '../../user/user.service';

interface SetRefreshTokenOptions {
  refreshToken: string;
  userId: string;
  expiresAt: Date;
  expiredRefreshToken?: string;
  ipAddress?: string;
  userAgent?: string;
}

@Injectable()
export class TokenService {
  private readonly logger = new Logger(TokenService.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    @InjectRepository(RefreshToken)
    private readonly refreshTokenRepository: Repository<RefreshToken>,
    private readonly userService: UserService,
    private readonly entityManager: EntityManager,
  ) {}

  /**
   * Generates a new pair of access and refresh tokens.
   */
  async generateTokens(userId: string, email: string) {
    const accessTokenPayload = { sub: userId, email };
    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_SECRET'),
        expiresIn: this.configService.get<string>('JWT_EXPIRES_IN'),
      }),
      this.jwtService.signAsync(accessTokenPayload, {
        secret: this.configService.get<string>('JWT_REFRESH_SECRET'),
        expiresIn: this.configService.get<string>('JWT_REFRESH_EXPIRES_IN'),
      }),
    ]);
    return { accessToken, refreshToken };
  }

  /**
   * Generates a partial JWT token for 2FA authentication flow.
   */
  async generate2FAPartialToken(userId: string) {
    const payload = {
      sub: userId,
      isTwoFactorAuthenticated: false,
      is2FA: true,
    };

    const accessToken = await this.jwtService.signAsync(payload, {
      secret: this.configService.get<string>('TWO_FACTOR_AUTH_JWT_SECRET'),
      expiresIn: this.configService.get<string>('TWO_FACTOR_AUTH_JWT_EXPIRES_IN'),
    });
    return { accessToken };
  }

  /**
   * Verifies if a refresh token is valid for a user.
   */
  async verifyRefreshToken(refreshToken: string, userId: string): Promise<boolean> {
    const storedTokens = await this.refreshTokenRepository.find({
      where: { userId },
    });

    if (!storedTokens || storedTokens.length === 0) {
      return false;
    }

    let matchingToken: RefreshToken | undefined;

    for (const storedToken of storedTokens) {
      const isMatch = await bcrypt.compare(refreshToken, storedToken.hashedToken);
      if (isMatch) {
        matchingToken = storedToken;
        break;
      }
    }

    if (matchingToken) {
      if (matchingToken.expiresAt < new Date()) {
        await this.refreshTokenRepository.delete(matchingToken.id);
        throw new UnauthorizedException('Refresh token has expired');
      }
      return true;
    }

    return false;
  }

  /**
   * Stores a new refresh token in the database, enforcing session limits.
   */
  async setCurrentRefreshToken(options: SetRefreshTokenOptions): Promise<void> {
    const { refreshToken, userId, expiresAt, expiredRefreshToken, ipAddress, userAgent } = options;

    return this.entityManager.transaction(async (entityManager) => {
      const sessionLimit = parseInt(this.configService.get<string>('SESSION_LIMIT') as string) || 5;

      const userTokens = await entityManager.find(RefreshToken, {
        where: { userId },
        order: { createdAt: 'ASC' },
      });

      if (userTokens.length >= sessionLimit) {
        const tokensToRemove = userTokens.slice(0, userTokens.length - sessionLimit + 1);
        await entityManager.remove(tokensToRemove);
        this.logger.log(`[SessionLimit] Removed ${tokensToRemove.length} oldest session(s) for user ${userId}`);
      }

      const hashedToken = await bcrypt.hash(refreshToken, 12);
      let finalIpAddress = ipAddress;
      let finalUserAgent = userAgent;

      if (expiredRefreshToken) {
        const oldToken = await this.findRefreshTokenByValue(userId, expiredRefreshToken, entityManager);
        if (oldToken) {
          finalIpAddress = ipAddress || oldToken.ipAddress;
          finalUserAgent = userAgent || oldToken.userAgent;
          await entityManager.remove(oldToken);
        }
      }

      // Remove any existing token with exact same metadata to prevent duplicates
      if (finalIpAddress && finalUserAgent) {
        await entityManager.delete(RefreshToken, {
          userId,
          ipAddress: finalIpAddress,
          userAgent: finalUserAgent,
        });
      }

      const newRefreshToken = entityManager.create(RefreshToken, {
        hashedToken,
        userId,
        expiresAt,
        ipAddress: finalIpAddress,
        userAgent: finalUserAgent,
      });

      await entityManager.save(newRefreshToken);
    });
  }

  private async findRefreshTokenByValue(
    userId: string,
    refreshToken: string,
    entityManager: EntityManager,
  ): Promise<RefreshToken | null> {
    const userTokens = await entityManager.find(RefreshToken, { where: { userId } });
    for (const token of userTokens) {
      const isMatch = await bcrypt.compare(refreshToken, token.hashedToken);
      if (isMatch) {
        return token;
      }
    }
    return null;
  }

  /**
   * Revokes a specific refresh token.
   */
  async revokeRefreshToken(userId: string, rawRefreshToken: string): Promise<void> {
    const userTokens = await this.refreshTokenRepository.find({ where: { userId } });
    for (const token of userTokens) {
      const isMatch = await bcrypt.compare(rawRefreshToken, token.hashedToken);
      if (isMatch) {
        await this.refreshTokenRepository.delete(token.id);
      }
    }
  }

  /**
   * Revokes all refresh tokens for a user.
   */
  async removeAllRefreshTokensForUser(userId: string): Promise<void> {
    await this.refreshTokenRepository.delete({ userId });
  }

  /**
   * Invalidates all tokens (Access & Refresh) by updating the user's `tokensValidFrom` timestamp.
   */
  async invalidateAllTokens(userId: string): Promise<void> {
    await this.entityManager.update(User, userId, { tokensValidFrom: new Date() });
  }

  /**
   * Refreshes access and refresh tokens.
   */
  async refreshUserTokens(userId: string, refreshToken: string) {
    const user = await this.userService.findOneById(userId);
    if (!user || user.status !== UserStatus.ACTIVE) {
      throw new UnauthorizedException('Access Denied');
    }

    try {
      const isValidToken = await this.verifyRefreshToken(refreshToken, userId);
      if (!isValidToken) {
        // Security risk: Invalid token presented. Log out all sessions.
        await this.removeAllRefreshTokensForUser(userId);
        await this.invalidateAllTokens(userId);
        throw new UnauthorizedException('Access Denied');
      }
    } catch (error) {
      if (error instanceof UnauthorizedException) {
        throw new UnauthorizedException('Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại.');
      }
      throw error;
    }

    const tokens = await this.generateTokens(userId, user.email);
    const liveTime = this.configService.get<string>('JWT_REFRESH_EXPIRES_IN') || '30d';
    const refreshTokenExpiresIn = parseInt(liveTime.slice(0, -1), 10) || 30;

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + refreshTokenExpiresIn);

    await this.setCurrentRefreshToken({
      refreshToken: tokens.refreshToken,
      userId,
      expiresAt,
      expiredRefreshToken: refreshToken,
    });

    return tokens;
  }

  @Cron(CronExpression.EVERY_DAY_AT_3AM)
  async handleExpiredTokensCleanup() {
    this.logger.log('[Cron] Running scheduled task to clean up expired refresh tokens...');
    const result = await this.refreshTokenRepository.delete({
      expiresAt: LessThan(new Date()),
    });
    if (result.affected && result.affected > 0) {
      this.logger.log(`[Cron] Successfully deleted ${result.affected} expired refresh tokens.`);
    }
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { Request } from 'express';
import { Injectable, Logger, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * Passport strategy for handling partial 2FA (Two-Factor Authentication) tokens.
 * This strategy is used when a user has successfully logged in but 2FA is enabled,
 * requiring an additional step to verify the 2FA code.
 * It extracts a JWT from the '2fa_partial_token' cookie and validates it.
 * The token payload should indicate that 2FA is required but not yet completed.
 */
@Injectable()
export class TwoFactorAuthenticationStrategy extends PassportStrategy(
  Strategy,
  '2fa-partial' // named this strategy as '2fa-partial'
) {
  private readonly logger = new Logger(TwoFactorAuthenticationStrategy.name);

  constructor(configService: ConfigService) {
    const twoFactorAuthenticationSecret = configService.get<string>(
      'TWO_FACTOR_AUTH_JWT_SECRET'
    );
    if (!twoFactorAuthenticationSecret) {
      throw new Error(
        'TWO_FACTOR_AUTH_JWT_SECRET is not defined in environment variables'
      );
    }

    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => {
          const data = request.cookies['2fa_partial_token'];
          this.logger.debug(
            `Extracting 2fa_partial_token: ${data ? 'Found' : 'Not found'}`
          );
          if (!data) {
            this.logger.warn('2fa_partial_token cookie not found');
            return null;
          }
          return data;
        },
      ]),
      ignoreExpiration: false,
      secretOrKey: twoFactorAuthenticationSecret,
      // pass request obj to the validate method
      passReqToCallback: true,
    });
  }

  validate(req: Request, payload: any): any {
    this.logger.debug('2FA Strategy validate called');
    this.logger.debug('Payload:', JSON.stringify(payload, null, 2));

    const partialToken = req.cookies['2fa_partial_token'];

    // Check necessary conditions
    if (!payload.sub) {
      this.logger.error('No user ID in payload');
      throw new UnauthorizedException('Authentication failed');
    }

    if (!payload.is2FA) {
      this.logger.error('Not a 2FA token');
      throw new UnauthorizedException('Authentication failed');
    }

    if (payload.isTwoFactorAuthenticated === true) {
      this.logger.error('2FA already completed');
      throw new UnauthorizedException('Authentication failed');
    }

    this.logger.log(
      `2FA Strategy validation successful for user: ${payload.sub}`
    );

    // Attach both payload and refresh token to request.user
    return { ...payload, partialToken };
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback, Profile } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * Google OAuth Strategy specifically for linking accounts
 * This strategy is used when a logged-in user wants to link their Google account
 * It doesn't validate/create a user, just returns the Google profile data
 */
@Injectable()
export class GoogleLinkStrategy extends PassportStrategy(
  Strategy,
  'google-link'
) {
  constructor(private readonly configService: ConfigService) {
    super({
      clientID: configService.get<string>('GOOGLE_CLIENT_ID') as string,
      clientSecret: configService.get<string>('GOOGLE_CLIENT_SECRET') as string,
      callbackURL: `${configService.get<string>('API_BASE_URL')}/auth/link-google/callback`,
      scope: ['email', 'profile'],
      passReqToCallback: true, // This allows us to access req.query.state
    });
  }

  // Override authenticate to pass the state parameter from query to Google OAuth
  authenticate(req: any, options?: any) {
    const state = req.query.state;
    if (state) {
      options = options || {};
      options.state = state;
    }
    super.authenticate(req, options);
  }

  async validate(
    req: any,
    accessToken: string,
    refreshToken: string,
    profile: Profile,
    done: VerifyCallback
  ): Promise<any> {
    const { id, displayName, emails, photos } = profile;

    if (!emails || emails.length === 0) {
      return done(new Error('No email associated with this account!'), false);
    }

    // Return the Google profile data along with the state parameter
    // The state will be available in req.query.state in the callback
    const googleProfile = {
      provider: 'google',
      providerId: id,
      email: emails[0].value,
      name: displayName,
      avatarUrl: photos && photos.length > 0 ? photos[0].value : '',
      state: req.query.state, // This will be the state returned from Google
    };

    done(null, googleProfile);
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback, Profile } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AuthService } from '../auth.service';

/**
 * Passport strategy for authenticating users via Google OAuth 2.0.
 * This strategy handles the initial Google login flow, validating the Google profile
 * and either finding an existing user, linking to an existing user by email,
 * or creating a new user and identity.
 */
@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  constructor(
    private readonly configService: ConfigService,
    private readonly authService: AuthService
  ) {
    super({
      clientID: configService.get<string>('GOOGLE_CLIENT_ID') as string,
      clientSecret: configService.get<string>('GOOGLE_CLIENT_SECRET') as string,
      callbackURL: `${configService.get<string>('API_BASE_URL')}/auth/google/callback`,
      scope: ['email', 'profile'],
    });
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: Profile,
    done: VerifyCallback
  ): Promise<any> {
    const { id, displayName, emails, photos } = profile;
    if (!emails || emails.length === 0) {
      return done(new Error('No email associated with this account!'), false);
    }

    if (!photos || photos.length === 0) {
      return done(
        new Error('No profile picture associated with this account!'),
        false
      );
    }

    const googleProfile = {
      provider: 'google',
      providerId: id,
      email: emails[0].value,
      name: displayName,
      avatarUrl: photos[0].value,
    };

    const user = await this.authService.validateOAuthUser(googleProfile);
    done(null, user);
  }
}

