@Unique(["userId", "projectId"]) // Ensures a user can only be a member of a project once.
export class ProjectMember {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ type: "int" })
  projectId: number;

  @Column("uuid") // Make sure the type matches the User's id type
  userId: string;

  // Project-specific role (manager or agent)
  @Column({
    type: "enum",
    enum: ProjectRole,
    comment: "The role of the user within this specific project.",
  })
  role: ProjectRole;

  @ManyToOne(() => Project, (project) => project.members, {
    onDelete: "CASCADE",
  })
  @JoinColumn({ name: "project_id" })
  project: Project;

  @ManyToOne(() => User, (user) => user.projectMemberships, {
    onDelete: "CASCADE",
  })
  @JoinColumn({ name: "user_id" })
  user: User;

  // Timestamp for when the membership was created.
  @CreateDateColumn({ type: "timestamptz" })
  createdAt: Date;

  // Timestamp for when the membership was last updated.
  @UpdateDateColumn({ type: "timestamptz" })
  updatedAt: Date;
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  ManyToOne,
  JoinColumn,
  OneToMany,
} from "typeorm";
import { Conversation } from "./conversation.entity";
import { ProjectMember } from "./project-member.entity";
import type { IWidgetSettingsDto } from "@live-chat/shared-types";

@Entity("projects")
export class Project {
  @PrimaryGeneratedColumn("increment")
  id: number;

  @OneToMany(() => Conversation, (conversation) => conversation.project)
  conversations: Conversation[];

  @Column({ type: "varchar" })
  name: string;

  @Column({ type: "jsonb", default: {} })
  widgetSettings: IWidgetSettingsDto;

  @Column({
    type: "text",
    array: true,
    nullable: true,
    name: "whitelisted_domains",
  })
  whitelistedDomains: string[];

  @OneToMany(() => ProjectMember, (member) => member.project)
  members: ProjectMember[];

  @CreateDateColumn({ type: "timestamptz" })
  createdAt: Date;
}

