import { Test, TestingModule } from '@nestjs/testing';
import { EventsGateway } from './events.gateway';
import { RealtimeSessionService } from '../realtime-session/realtime-session.service';
import { REDIS_SUBSCRIBER_CLIENT } from '../redis/redis.module';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Server, Socket } from 'socket.io';
import { JwtService } from '@nestjs/jwt';
import { UserService } from '../user/user.service';
import { ProjectService } from '../projects/project.service';
import { ConfigService } from '@nestjs/config';

describe('EventsGateway', () => {
  let gateway: EventsGateway;
  let realtimeSessionService: jest.Mocked<RealtimeSessionService>;
  let redisSubscriber: jest.Mocked<any>;
  let eventEmitter: jest.Mocked<EventEmitter2>;
  let server: jest.Mocked<Server>;
  let client: jest.Mocked<Socket>;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EventsGateway,
        {
          provide: RealtimeSessionService,
          useValue: {
            deleteVisitorSession: jest.fn(),
            setVisitorCurrentUrl: jest.fn(),
          },
        },
        {
          provide: REDIS_SUBSCRIBER_CLIENT,
          useValue: {
            subscribe: jest.fn(),
            on: jest.fn(),
          },
        },
        {
          provide: EventEmitter2,
          useValue: {
            emit: jest.fn(),
          },
        },
        {
          provide: JwtService,
          useValue: {
            verify: jest.fn(),
          },
        },
        {
          provide: UserService,
          useValue: {
            findOneById: jest.fn(),
          },
        },
        {
          provide: ProjectService,
          useValue: {
            findByProjectId: jest.fn(),
          },
        },
        {
          provide: ConfigService,
          useValue: {
            get: jest.fn((key: string) => {
              if (key === 'FRONTEND_URL') return 'http://localhost:3000';
              return null;
            }),
          },
        },
      ],
    }).compile();

    gateway = module.get<EventsGateway>(EventsGateway);
    realtimeSessionService = module.get(RealtimeSessionService);
    redisSubscriber = module.get(REDIS_SUBSCRIBER_CLIENT);
    eventEmitter = module.get(EventEmitter2);

    server = { to: jest.fn().mockReturnThis(), emit: jest.fn(), use: jest.fn() } as unknown as jest.Mocked<Server>;
    client = {
      id: 'socket-id',
      data: {},
      join: jest.fn(),
      leave: jest.fn(),
    } as unknown as jest.Mocked<Socket>;

    gateway.server = server;
  });

  it('should be defined', () => {
    expect(gateway).toBeDefined();
  });

  describe('handleDisconnect', () => {
    it('should delete visitor session on disconnect', () => {
      client.data.visitorUid = 'visitor-123';
      gateway.handleDisconnect(client);
      expect(
        realtimeSessionService.deleteVisitorSession
      ).toHaveBeenCalledWith('visitor-123');
    });
  });

  describe('afterInit', () => {
    it('should subscribe to the new message channel', () => {
      gateway.afterInit(server);
      expect(redisSubscriber.subscribe).toHaveBeenCalledWith(
        'new_message_channel',
        expect.any(Function)
      );
    });
  });

  describe('handleIdentify', () => {
    it('should emit a visitor.identified event', async () => {
      const payload = { projectId: 1, visitorUid: 'visitor-123' };
      await gateway.handleIdentify(client, payload);
      expect(eventEmitter.emit).toHaveBeenCalledWith(
        'visitor.identified',
        expect.objectContaining(payload)
      );
    });
  });

  describe('handleSendMessage', () => {
    it('should emit a visitor.message.received event', async () => {
      client.data.visitorUid = 'visitor-123';
      client.data.projectId = 1;
      const payload = { content: 'Hello', tempId: 'temp-id' };
      await gateway.handleSendMessage(payload, client);
      expect(eventEmitter.emit).toHaveBeenCalledWith(
        'visitor.message.received',
        expect.objectContaining({
          ...payload,
          visitorUid: 'visitor-123',
          projectId: 1,
        })
      );
    });
  });

  describe('handleVisitorTyping', () => {
    it('should emit visitorIsTyping to the project room', () => {
      client.data.projectId = 1;
      client.data.conversationId = 2;
      gateway.handleVisitorTyping(client, { isTyping: true });
      expect(server.to).toHaveBeenCalledWith('project:1');
      expect(server.emit).toHaveBeenCalledWith('visitorIsTyping', {
        conversationId: 2,
        isTyping: true,
      });
    });
  });

  describe('handleUpdateContext', () => {
    it('should set current URL and emit visitorContextUpdated', async () => {
      client.data.projectId = 1;
      client.data.conversationId = 2;
      client.data.visitorUid = 'visitor-123';
      const payload = { currentUrl: 'https://new-url.com' };
      await gateway.handleUpdateContext(client, payload);

      expect(realtimeSessionService.setVisitorCurrentUrl).toHaveBeenCalledWith(
        'visitor-123',
        'https://new-url.com'
      );
      expect(server.to).toHaveBeenCalledWith('project:1');
      expect(server.emit).toHaveBeenCalledWith('visitorContextUpdated', {
        conversationId: 2,
        currentUrl: 'https://new-url.com',
      });
    });
  });

  describe('handleJoinProjectRoom', () => {
    it('should make the client join the project room', () => {
      gateway.handleJoinProjectRoom(client, { projectId: 1 });
      expect(client.join).toHaveBeenCalledWith('project:1');
    });
  });

  describe('handleLeaveProjectRoom', () => {
    it('should make the client leave the project room', () => {
      gateway.handleLeaveProjectRoom(client, { projectId: 1 });
      expect(client.leave).toHaveBeenCalledWith('project:1');
    });
  });
});

// src/gateway/events.gateway.ts
import {
  WebSocketGateway,
  SubscribeMessage,
  MessageBody,
  WebSocketServer,
  ConnectedSocket,
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger, Inject, UseGuards } from '@nestjs/common';
import { RealtimeSessionService } from '../realtime-session/realtime-session.service';
import { type Redis } from 'ioredis';
import { REDIS_SUBSCRIBER_CLIENT } from '../redis/redis.module';
import { WsJwtAuthGuard } from './guards/ws-jwt-auth.guard';
import { EventEmitter2 } from '@nestjs/event-emitter';
import {
  VisitorIdentifiedEvent,
  VisitorMessageReceivedEvent,
} from '../inbox/events';
import { AgentTypingDto } from '@live-chat/shared-dtos';
import { Conversation, Visitor, Message } from '../database/entities';
import { MessageStatus, WidgetMessageDto } from '@live-chat/shared-types';
import { ProjectService } from '../projects/project.service';
import { ConfigService } from '@nestjs/config';

const NEW_MESSAGE_CHANNEL = 'new_message_channel';

@UseGuards(WsJwtAuthGuard)
@WebSocketGateway()
export class EventsGateway
  implements OnGatewayConnection, OnGatewayDisconnect, OnGatewayInit
{
  @WebSocketServer()
  server!: Server;

  private readonly logger = new Logger(EventsGateway.name);

  constructor(
    private readonly realtimeSessionService: RealtimeSessionService,
    @Inject(REDIS_SUBSCRIBER_CLIENT) private readonly redisSubscriber: Redis,
    private readonly eventEmitter: EventEmitter2,
    private readonly projectService: ProjectService,
    private readonly configService: ConfigService
  ) {}

  async handleConnection(client: Socket) {
    this.logger.log(`Client connected: ${client.id}`);

    const origin = client.handshake.headers.origin;
    const projectId = client.handshake.query.projectId;
    const frontendUrl = this.configService.get<string>('FRONTEND_URL');

    // Allow main frontend app without further checks
    if (origin === frontendUrl) {
      return;
    }

    if (projectId && typeof projectId === 'string') {
      const project = await this.projectService.findByProjectId(+projectId);
      if (!project) {
        this.logger.warn(`Connection rejected: Project ${projectId} not found.`);
        client.disconnect(true);
        return;
      }

      if (
        !project.whitelistedDomains ||
        project.whitelistedDomains.length === 0
      ) {
        this.logger.warn(
          `Project ${projectId} has no whitelisted domains configured. WS connection denied for origin ${origin}.`
        );
        client.disconnect(true);
        return;
      }

      if (origin) {
        const originUrl = new URL(origin);
        const originDomain = originUrl.hostname;

        if (!project.whitelistedDomains.includes(originDomain)) {
          this.logger.warn(
            `Connection rejected: Origin ${origin} not whitelisted for project ${projectId}`
          );
          client.disconnect(true);
          return;
        }
      } else {
        // No origin header provided for a widget connection
        this.logger.warn(
          `Connection rejected: Missing Origin header for project ${projectId}`
        );
        client.disconnect(true);
        return;
      }
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client disconnected: ${client.id}`);
    if (client.data.visitorUid) {
      this.realtimeSessionService.deleteVisitorSession(client.data.visitorUid);
    }
  }

  afterInit(server: Server) {
    this.logger.log('Gateway Initialized. Subscribing to Redis channel...');
    this.redisSubscriber.subscribe(NEW_MESSAGE_CHANNEL, (err) => {
      if (err) {
        this.logger.error('Failed to subscribe to Redis channel', err);
      } else {
        this.logger.log(`Subscribed successfully to "${NEW_MESSAGE_CHANNEL}"`);
      }
    });

    this.redisSubscriber.on('message', (channel, message) => {
      this.logger.log(`Received message on channel: ${channel}`);
      if (channel === NEW_MESSAGE_CHANNEL) {
        this.eventEmitter.emit('redis.message.received', message);
      }
    });

    this.server.use((socket, next) => {
      socket.onAny((event, ...args) => {
        this.logger.log(`Socket event: ${event}`, {
          socketId: socket.id,
        });
      });
      next();
    });
  }

  public prepareSocketForVisitor(
    socketId: string,
    visitor: Visitor,
    conversation: Conversation,
    projectId: number,
    visitorUid: string
  ) {
    const socket = this.server.sockets.sockets.get(socketId);
    if (!socket) {
      this.logger.warn(`Could not find socket with id: ${socketId}`);
      return;
    }

    socket.data.projectId = projectId;
    socket.data.visitorUid = visitorUid;

    if (visitor && visitor.id) {
      this.logger.log(
        `Associating visitorId ${visitor.id} with socket ${socket.id}`
      );
      socket.data.visitorId = visitor.id;
    }

    let messagesForFrontend: WidgetMessageDto[] = [];

    if (conversation && conversation.messages) {
      messagesForFrontend = conversation.messages.map((msg) => ({
        id: msg.id,
        content: msg.content || '',
        sender: {
          type: msg.fromCustomer ? 'visitor' : 'agent',
          name: msg.senderId,
        },
        status: msg.status as MessageStatus,
        timestamp: msg.createdAt.toISOString(),
      }));
    } else {
      this.logger.log(
        `No messages found for conversationId ${conversation.id}`
      );
      this.logger.log(`messages: ${JSON.stringify(conversation.messages)}`);
    }

    this.logger.log(`Emitting conversationHistory to ${socket.id}`);
    socket.data.conversationId = conversation.id;
    socket.emit('conversationHistory', {
      messages: messagesForFrontend,
    });
  }

  @SubscribeMessage('identify')
  async handleIdentify(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { projectId: number; visitorUid: string }
  ): Promise<void> {
    this.logger.debug(
      `Identify event from client ${client.id} for visitorUid: ${payload.visitorUid} in projectId: ${payload.projectId}`
    );

    const event = new VisitorIdentifiedEvent();
    event.projectId = payload.projectId;
    event.visitorUid = payload.visitorUid;
    event.socketId = client.id;
    this.eventEmitter.emit('visitor.identified', event);
  }

  @SubscribeMessage('sendMessage')
  async handleSendMessage(
    @MessageBody() data: { content: string; tempId: string },
    @ConnectedSocket() client: Socket
  ): Promise<void> {
    if (!client.data.visitorUid || !client.data.projectId) {
      return;
    }

    const event = new VisitorMessageReceivedEvent();
    event.tempId = data.tempId;
    event.content = data.content;
    event.visitorUid = client.data.visitorUid;
    event.projectId = client.data.projectId;
    event.socketId = client.id;
    this.eventEmitter.emit('visitor.message.received', event);
  }

  @SubscribeMessage('visitorIsTyping')
  handleVisitorTyping(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { isTyping: boolean }
  ): void {
    const { projectId, conversationId } = client.data;
    if (projectId) {
      this.logger.log(`Emitting visitorIsTyping to project ${projectId}`);
      this.server.to(`project:${projectId}`).emit('visitorIsTyping', {
        conversationId,
        isTyping: payload.isTyping,
      });
    }
  }

  @SubscribeMessage('updateContext')
  async handleUpdateContext(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { currentUrl: string }
  ): Promise<void> {
    const { projectId, conversationId, visitorUid } = client.data;
    this.logger.debug(
      `updateContext event from client ${client.id} for visitorUid: ${visitorUid} in projectId: ${projectId}`
    );

    let missingData = false;
    if (!projectId) {
      this.logger.warn(
        `Missing projectId for socket ${client.id} in handleUpdateContext`
      );
      missingData = true;
    }
    if (!conversationId) {
      this.logger.warn(
        `Missing conversationId for socket ${client.id} in handleUpdateContext`
      );
      missingData = true;
    }
    if (!visitorUid) {
      this.logger.warn(
        `Missing visitorUid for socket ${client.id} in handleUpdateContext`
      );
      missingData = true;
    }

    if (missingData) {
      return;
    }

    // Store currentUrl in Redis
    await this.realtimeSessionService.setVisitorCurrentUrl(
      visitorUid,
      payload.currentUrl
    );

    // Broadcast to agents
    this.logger.log(`Emitting visitorContextUpdated to project ${projectId}`);
    this.server.to(`project:${projectId}`).emit('visitorContextUpdated', {
      conversationId,
      currentUrl: payload.currentUrl,
    });
  }

  @SubscribeMessage('joinProjectRoom')
  handleJoinProjectRoom(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { projectId: number }
  ): { status: string; roomName: string } {
    const roomName = `project:${payload.projectId}`;
    client.join(roomName);
    this.logger.log(`Client with ${client.id} joined room: ${roomName}`);
    return { status: 'ok', roomName };
  }

  @SubscribeMessage('leaveProjectRoom')
  handleLeaveProjectRoom(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { projectId: number }
  ): { status: string; roomName: string } {
    const roomName = `project:${payload.projectId}`;
    client.leave(roomName);
    this.logger.log(`Client with ${client.id} left room: ${roomName}`);
    return { status: 'ok', roomName };
  }

  public sendAgentTypingToVisitor(
    visitorSocketId: string,
    isTyping: boolean,
    agentName: string
  ) {
    this.logger.log(`Emitting agentIsTyping to ${visitorSocketId}`);
    this.server.to(visitorSocketId).emit('agentIsTyping', {
      agentName,
      isTyping,
    });
  }

  public sendReplyToVisitor(visitorSocketId: string, message: any) {
    this.logger.log(`Emitting agentReplied to ${visitorSocketId}`);
    this.server.to(visitorSocketId).emit('agentReplied', message);
  }

  public visitorMessageSent(visitorSocketId: string, data: any) {
    try {
      this.logger.log(`Emitting messageSent to ${visitorSocketId}`);
      this.server.to(visitorSocketId).emit('messageSent', data);
    } catch (error) {
      this.logger.log(error);
    }
  }
}

