import {
  CanActivate,
  ExecutionContext,
  Injectable,
  Logger,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { WsException } from '@nestjs/websockets';
import { Socket } from 'socket.io';
import { UserService } from '../../user/user.service';

@Injectable()
export class WsJwtAuthGuard implements CanActivate {
  private readonly logger = new Logger(WsJwtAuthGuard.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly userService: UserService
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    try {
      const client: Socket = context.switchToWs().getClient<Socket>();
      const authToken = client.handshake.auth?.token;

      if (!authToken) {
        this.logger.log('Websocket connection from widget');
        return true;
      }

      const payload = await this.jwtService.verifyAsync(authToken);

      // Attach user to the socket for later use
      const user = await this.userService.findOneById(payload.sub);
      if (!user) {
        throw new WsException('Unauthorized: User not found');
      }

      // Important: Attach user payload to the client object
      client.data.user = { id: user.id, email: user.email };
      this.logger.log(`WebSocket authenticated user: ${user.email}`);

      return true;
    } catch (err) {
      if (err instanceof Error) {
        this.logger.error(`WebSocket Authentication Error: ${err.message}`);
      } else {
        this.logger.error(
          'An unknown WebSocket authentication error occurred',
          err
        );
      }
      // Throwing WsException will emit an 'exception' event to the client
      throw new WsException('Unauthorized: Invalid token');
    }
  }
}

import { RedisIoAdapter } from './redis-io.adapter';
import { ConfigService } from '@nestjs/config';
import { INestApplication } from '@nestjs/common';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient } from 'redis';
import { IoAdapter } from '@nestjs/platform-socket.io';

jest.mock('@socket.io/redis-adapter');
jest.mock('redis');

describe('RedisIoAdapter', () => {
  let adapter: RedisIoAdapter;
  let app: jest.Mocked<INestApplication>;
  let configService: jest.Mocked<ConfigService>;

  beforeEach(() => {
    app = {
      get: jest.fn(),
    } as unknown as jest.Mocked<INestApplication>;

    configService = {
      get: jest.fn((key: string, defaultValue?: any) => {
        if (key === 'REDIS_HOST') return 'localhost';
        if (key === 'REDIS_PORT') return 6379;
        if (key === 'FRONTEND_URL') return 'http://localhost:3000';
        return defaultValue;
      }),
    } as unknown as jest.Mocked<ConfigService>;

    adapter = new RedisIoAdapter(app, configService);
  });

  it('should be defined', () => {
    expect(adapter).toBeDefined();
  });

  describe('connectToRedis', () => {
    it('should create and connect redis clients', async () => {
      const pubClient = { connect: jest.fn(), duplicate: jest.fn() };
      const subClient = { connect: jest.fn() };
      (createClient as jest.Mock).mockReturnValue(pubClient);
      pubClient.duplicate.mockReturnValue(subClient);

      await adapter.connectToRedis();

      expect(createClient).toHaveBeenCalled();
      expect(pubClient.connect).toHaveBeenCalled();
      expect(subClient.connect).toHaveBeenCalled();
      expect(createAdapter).toHaveBeenCalledWith(pubClient, subClient);
    });

    it('should throw error if redis connection fails', async () => {
      const pubClient = { 
        connect: jest.fn().mockRejectedValue(new Error('Connection failed')), 
        duplicate: jest.fn().mockReturnValue({ connect: jest.fn() })
      };
      (createClient as jest.Mock).mockReturnValue(pubClient);

      await expect(adapter.connectToRedis()).rejects.toThrow('Connection failed');
    });
  });

  describe('createIOServer', () => {
    let server: any;

    beforeEach(async () => {
      // Setup redis connection first
      const pubClient = { connect: jest.fn(), duplicate: jest.fn() };
      const subClient = { connect: jest.fn() };
      (createClient as jest.Mock).mockReturnValue(pubClient);
      pubClient.duplicate.mockReturnValue(subClient);
      await adapter.connectToRedis();

      server = {
        use: jest.fn(),
        adapter: jest.fn(),
      };
      jest.spyOn(IoAdapter.prototype, 'createIOServer').mockReturnValue(server);
    });

    it('should create a Socket.IO server with CORS enabled', () => {
      const result = adapter.createIOServer(3000);

      expect(IoAdapter.prototype.createIOServer).toHaveBeenCalledWith(
        3000,
        expect.objectContaining({
          cors: expect.objectContaining({
            origin: true,
            methods: ['GET', 'POST'],
            credentials: true,
          }),
        })
      );
      expect(result).toBe(server);
    });

    it('should apply the redis adapter', () => {
      adapter.createIOServer(3000);
      expect(server.adapter).toHaveBeenCalled();
    });
  });
});

import { IoAdapter } from '@nestjs/platform-socket.io';
import { Server, ServerOptions } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient } from 'redis';
import { ConfigService } from '@nestjs/config';
import { INestApplication, Logger } from '@nestjs/common';

export class RedisIoAdapter extends IoAdapter {
  private readonly logger = new Logger(RedisIoAdapter.name);
  private adapterConstructor!: ReturnType<typeof createAdapter>;

  constructor(
    private readonly app: INestApplication,
    private readonly configService: ConfigService
  ) {
    super(app);
    this.logger.log('RedisIoAdapter constructor invoked.');
  }

  async connectToRedis(): Promise<void> {
    const redisHost = this.configService.get<string>('REDIS_HOST', 'localhost');
    const redisPort = this.configService.get<number>('REDIS_PORT', 6379);
    const redisUrl = `redis://${redisHost}:${redisPort}`;

    this.logger.log(`Attempting to connect to Redis at ${redisUrl}...`);

    const pubClient = createClient({ url: redisUrl });
    const subClient = pubClient.duplicate();

    try {
      await Promise.all([pubClient.connect(), subClient.connect()]);
      this.logger.log('Successfully connected to Redis.');
      this.adapterConstructor = createAdapter(pubClient, subClient);
    } catch (err) {
      this.logger.error('Failed to connect to Redis:', err);
      throw err;
    }
  }

  createIOServer(port: number, options?: ServerOptions): any {
    this.logger.log('createIOServer method invoked.');
    const server: Server = super.createIOServer(port, {
      ...options,
      cors: {
        origin: true,
        methods: ['GET', 'POST'],
        credentials: true,
      },
    });
    this.logger.log(`Socket.IO server created with path: /socket.io/`);

    server.adapter(this.adapterConstructor);

    this.logger.log(
      'Socket.IO server created with Redis adapter.'
    );
    return server;
  }
}

import { IoAdapter } from '@nestjs/platform-socket.io';
import { Server, ServerOptions } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient } from 'redis';
import { ConfigService } from '@nestjs/config';
import { INestApplication, Logger } from '@nestjs/common';
import { ProjectService } from '../projects/project.service';

export class RedisIoAdapter extends IoAdapter {
  private readonly logger = new Logger(RedisIoAdapter.name);
  private adapterConstructor!: ReturnType<typeof createAdapter>;

  constructor(
    private readonly app: INestApplication,
    private readonly configService: ConfigService
  ) {
    super(app);
    this.logger.log('RedisIoAdapter constructor invoked.');
  }

  async connectToRedis(): Promise<void> {
    const redisHost = this.configService.get<string>('REDIS_HOST', 'localhost');
    const redisPort = this.configService.get<number>('REDIS_PORT', 6379);
    const redisUrl = `redis://${redisHost}:${redisPort}`;

    this.logger.log(`Attempting to connect to Redis at ${redisUrl}...`);

    const pubClient = createClient({ url: redisUrl });
    const subClient = pubClient.duplicate();

    try {
      await Promise.all([pubClient.connect(), subClient.connect()]);
      this.logger.log('Successfully connected to Redis.');
      this.adapterConstructor = createAdapter(pubClient, subClient);
    } catch (err) {
      this.logger.error('Failed to connect to Redis:', err);
      throw err;
    }
  }

  createIOServer(port: number, options?: ServerOptions): any {
    this.logger.log('createIOServer method invoked.');
    const server: Server = super.createIOServer(port, {
      ...options,
      cors: {
        origin: true,
        methods: ['GET', 'POST'],
        credentials: true,
      },
    });
    this.logger.log(`Socket.IO server created with path: /socket.io/`);

    server.adapter(this.adapterConstructor);

    const frontendUrl = this.configService.get<string>('FRONTEND_URL');
    const projectService = this.app.get(ProjectService);
    const logger = this.logger;

    server.use(async (socket, next) => {
      const origin = socket.handshake.headers.origin;

      // Allow main frontend app without further checks
      if (origin === frontendUrl) {
        logger.log(`Allowing origin (frontend): ${origin}`);
        return next();
      }

      // For all other origins (i.e., widgets), perform strict validation
      if (!origin) {
        return next(new Error('Origin header is missing.'));
      }

      const projectId = socket.handshake.query.projectId;
      if (!projectId || typeof projectId !== 'string') {
        return next(new Error('Project ID is missing or invalid.'));
      }

      const project = await projectService.findByProjectId(+projectId);
      if (!project) {
        return next(new Error(`Project with ID ${projectId} not found.`));
      }

      if (
        !project.whitelistedDomains ||
        project.whitelistedDomains.length === 0
      ) {
        logger.warn(
          `Project ${projectId} has no whitelisted domains configured. WS connection denied for origin ${origin}.`
        );
        return next(new Error('Not allowed by CORS'));
      }

      const originUrl = new URL(origin);
      const originDomain = originUrl.hostname;

      if (project.whitelistedDomains.includes(originDomain)) {
        logger.log(`Allowing WS connection from origin (widget): ${origin}`);
        return next();
      }

      logger.warn(
        `Origin ${origin} not in whitelist for project ${projectId}. WS connection blocked.`
      );
      return next(new Error('Not allowed by CORS'));
    });

    this.logger.log(
      'Socket.IO server created with Redis adapter and CORS middleware.'
    );
    return server;
  }
}

export class VisitorMessageReceivedEvent {
  tempId: string;
  content: string;
  visitorUid: string;
  projectId: number;
  socketId: string;
}

export class VisitorIdentifiedEvent {
  projectId: number;
  visitorUid: string;
  socketId: string;
}

export class VisitorTypingEvent {
  isTyping: boolean;
  projectId: number;
  conversationId: number;
}

export class VisitorContextUpdatedEvent {
  currentUrl: string;
  projectId: number;
  conversationId: number;
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { VisitorIdentifiedEvent, VisitorMessageReceivedEvent } from './events';
import { ConversationService } from './services/conversation.service';
import { VisitorService } from './services/visitor.service';
import { RealtimeSessionService } from '../realtime-session/realtime-session.service';
import { BullMqProducerService } from '../event-producer/bullmq-producer.service';
import { EventsGateway } from '../gateway/events.gateway';
import { EntityManager } from 'typeorm';

@Injectable()
export class InboxEventHandlerService {
  private readonly logger = new Logger(InboxEventHandlerService.name);

  constructor(
    private readonly conversationService: ConversationService,
    private readonly visitorService: VisitorService,
    private readonly realtimeSessionService: RealtimeSessionService,
    private readonly bullMqProducerService: BullMqProducerService,
    private readonly eventsGateway: EventsGateway,
    private readonly entityManager: EntityManager
  ) {}

  @OnEvent('visitor.identified')
  async handleVisitorIdentified(payload: VisitorIdentifiedEvent) {
    this.logger.debug(
      `Handling visitor.identified event for visitorUid: ${payload.visitorUid}`
    );

    await this.realtimeSessionService.setVisitorSession(
      payload.visitorUid,
      payload.socketId
    );

    const { visitor, conversation } = await this.entityManager.transaction(
      async (manager) => {
        const visitor = await this.visitorService.findOrCreateByUid(
          payload.projectId,
          payload.visitorUid,
          manager
        );

        let conversation =
          await this.conversationService.getOrCreateHistoryByVisitorId(
            payload.projectId,
            visitor.id,
            manager
          );
        return { visitor, conversation };
      }
    );

    this.eventsGateway.prepareSocketForVisitor(
      payload.socketId,
      visitor,
      conversation,
      payload.projectId,
      payload.visitorUid
    );
  }

  @OnEvent('visitor.message.received')
  async handleVisitorMessageReceived(payload: VisitorMessageReceivedEvent) {
    this.logger.debug(
      `Handling visitor.message.received event from visitorUid: ${payload.visitorUid}`
    );

    await this.realtimeSessionService.setVisitorSession(
      payload.visitorUid,
      payload.socketId
    );
    this.logger.debug(
      `Reset session for visitorUid: ${payload.visitorUid} with socketId: ${payload.socketId}`
    );

    const eventPayload = {
      type: 'NEW_MESSAGE_FROM_VISITOR',
      payload: {
        tempId: payload.tempId,
        content: payload.content,
        visitorUid: payload.visitorUid,
        projectId: payload.projectId,
        socketId: payload.socketId,
      },
      timestamp: new Date().toISOString(),
    };

    await this.bullMqProducerService.sendMessage(eventPayload);
  }

  @OnEvent('redis.message.received')
  async handleRedisMessageReceived(messageData: string) {
    try {
      this.logger.log(messageData);
      const data = JSON.parse(messageData);
      const { message, tempId, visitorUid } = data;
      this.logger.log(
        `Received new message from Redis channel: ${JSON.stringify(message)}`
      );

      const visitorSocketId =
        await this.realtimeSessionService.getVisitorSession(visitorUid);
      const messageForFrontend = {
        id: message.id,
        content: message.content,
        sender: message.fromCustomer ? 'visitor' : 'agent',
        status: message.status,
        timestamp: message.createdAt,
      };

      this.logger.debug(
        `message for frontend: ${JSON.stringify(messageForFrontend)}`
      );
      if (visitorSocketId)
        this.eventsGateway.server
          .to(visitorSocketId)
          .emit('messageSent', { tempId, finalMessage: messageForFrontend });

      const conversation = await this.conversationService.findById(
        message.conversationId
      );

      if (conversation && conversation.projectId) {
        const projectId = conversation.projectId;
        const roomName = `project:${projectId}`;

        this.eventsGateway.server.to(roomName).emit('newMessage', message);

        this.logger.log(`Emitted 'newMessage' to room: ${roomName}`);
      }
    } catch (error) {
      this.logger.error('Error processing message from Redis:', error);
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { InboxController } from './inbox.controller';
import { ConversationService } from './services/conversation.service';
import { MessageService } from './services/message.service';
