        currentPassword: 'old-pw',
        newPassword: 'new-pw',
      };
      const res = { cookie: jest.fn() } as unknown as Response;
      const tokens = {
        accessToken: 'new-access-token',
        refreshToken: 'new-refresh-token',
      };
