    JwtStrategy,
    GoogleStrategy,
    GoogleLinkStrategy,
    TwoFactorAuthenticationStrategy,
    RefreshTokenStrategy,
    EncryptionService,
    ConfigService,
  ],
  exports: [JwtModule, TokenService, RegistrationService, LoginService],
})
export class AuthModule {}

import {
  Controller,
  Post,
  Body,
  UseGuards,
  Request,
  HttpCode,
  HttpStatus,
  Get,
  Res,
  UnauthorizedException,
  Req,
  Query,
} from '@nestjs/common';
import {
  ChangePasswordDto,
  SetPasswordDto,
  ExchangeCodeDto,
  RegisterDto,
  ResendVerificationDto,
  ForgotPasswordDto,
  ResetPasswordDto,
  LoginDto,
} from '@live-chat/shared-dtos';
import { User } from '../database/entities';
import { LocalAuthGuard } from './guards/local-auth.guard';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { type Response } from 'express';
import { RefreshTokenGuard } from './guards/refresh-token.guard';
import { AuthGuard } from '@nestjs/passport';
import { ConfigService } from '@nestjs/config';
import { ApiBody, ApiOperation, ApiResponse, ApiTags } from '@nestjs/swagger';
import { RegistrationService } from './services/registration.service';
import { LoginService } from './services/login.service';
import { PasswordService } from './services/password.service';
import { OAuthService } from './services/oauth.service';
import { TokenService } from './services/token.service';
import { EmailChangeService } from '../user/services/email-change.service';
import { UserService } from '../user/user.service';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Inject } from '@nestjs/common';
import { Cache } from 'cache-manager';

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  private readonly refreshTokenExpiresIn: number;

  constructor(
    private readonly registrationService: RegistrationService,
    private readonly loginService: LoginService,
    private readonly passwordService: PasswordService,
    private readonly oauthService: OAuthService,
    private readonly tokenService: TokenService,
    private readonly emailChangeService: EmailChangeService,
    private readonly userService: UserService,
    private readonly configService: ConfigService,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
  ) {
    const refreshTokenExpiresInString = this.configService.get<string>(
      'JWT_REFRESH_EXPIRES_IN'
    ) as string;
    this.refreshTokenExpiresIn = parseInt(
      refreshTokenExpiresInString.slice(0, -1),
      10
    );
  }

  @Post('register')
  @HttpCode(HttpStatus.CREATED)
  @ApiOperation({ summary: 'Register a new user' })
  @ApiResponse({ status: 201, description: 'User successfully registered.' })
  @ApiResponse({ status: 409, description: 'Email already in use.' })
  async register(@Body() registerDto: RegisterDto) {
    return this.registrationService.register(registerDto);
  }

  @Get('verify-email')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Verify user email with token' })
  @ApiResponse({ status: 200, description: 'Email successfully verified.' })
  @ApiResponse({ status: 404, description: 'Invalid or expired token.' })
  async verifyEmail(@Query('token') token: string) {
    return this.registrationService.verifyEmail(token);
  }

  @Post('resend-verification')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Resend email verification link' })
  @ApiResponse({ status: 200, description: 'Verification email sent.' })
  @ApiResponse({ status: 409, description: 'Email already verified.' })
  async resendVerificationEmail(
    @Body() resendVerificationDto: ResendVerificationDto
  ) {
    return this.registrationService.resendVerificationEmail(resendVerificationDto);
  }

  @UseGuards(LocalAuthGuard)
  @Post('login')
  @HttpCode(HttpStatus.OK)
  @ApiBody({ type: LoginDto })
  @ApiResponse({ status: 200, description: 'User successfully logged in.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (wrong credentials or 2FA required).' })
  @ApiResponse({ status: 403, description: 'Forbidden (e.g., suspended account).' })
  async login(
    @Request()
    req: { user: User; ip: string; headers: { 'user-agent': string } },
    @Res({ passthrough: true }) response: Response,
    @Body() loginDto: LoginDto
  ) {
    const ipAddress = req.ip;
    const userAgent = req.headers['user-agent'] || '';
    const user = req.user as User;

    const result = await this.loginService.login(user, ipAddress, userAgent);

    if (result.status === '2fa_required') {
      response.cookie('2fa_partial_token', result.partialToken, {
        httpOnly: true,
        secure: this.configService.get('NODE_ENV') === 'production',
        sameSite:
          this.configService.get('NODE_ENV') === 'production' ? 'none' : 'lax',
        expires: new Date(Date.now() + 5 * 60 * 1000),
      });

      throw new UnauthorizedException({
        message: '2FA required',
        errorCode: '2FA_REQUIRED',
      });
    }

    const { tokens, user: userResult } = result;
    const { passwordHash, ...safeUser } = userResult;

    response.cookie('refresh_token', tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + this.refreshTokenExpiresIn * 24 * 60 * 60 * 1000
      ),
    });

    return {
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      user: {
        ...safeUser,
        hasPassword: !!passwordHash,
      },
    };
  }

  @UseGuards(RefreshTokenGuard)
  @Get('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Refresh access token using refresh token' })
  @ApiResponse({ status: 200, description: 'Access token successfully refreshed.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid or expired refresh token).' })
  @ApiResponse({ status: 403, description: 'Forbidden (e.g., user not active, token revoked).' })
  async refreshTokens(
    @Request() req,
    @Res({ passthrough: true }) response: Response
  ) {
    const userId = req.user.sub;
    const refreshToken = req.user.refreshToken;
    const tokens = await this.tokenService.refreshUserTokens(userId, refreshToken);

    response.cookie('refresh_token', tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      expires: new Date(
        Date.now() + this.refreshTokenExpiresIn * 24 * 60 * 60 * 1000
      ),
    });

    return { accessToken: tokens.accessToken };
  }

  @UseGuards(JwtAuthGuard)
  @Post('change-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Change user password' })
  @ApiResponse({ status: 200, description: 'Password successfully changed.' })
  @ApiResponse({ status: 400, description: 'Bad Request (e.g., current password missing).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid access token).' })
  @ApiResponse({ status: 403, description: 'Forbidden (e.g., incorrect current password).' })
  async changePassword(
    @Request() req,
    @Body() body: ChangePasswordDto,
    @Res({ passthrough: true }) response: Response
  ) {
    await this.passwordService.changePassword(
      req.user.id,
      body.currentPassword,
      body.newPassword
    );

    // Re-login to get new tokens after password change (which invalidates old ones)
    const user = await this.userService.findOneById(req.user.id);
    const result = await this.loginService.login(
      user,
      req.ip,
      req.headers['user-agent'] || ''
    );

    if (result.status === '2fa_required') {
       // This edge case is rare for password change flow, but handled for type safety
       throw new UnauthorizedException('2FA required');
    }

    response.cookie('refresh_token', result.tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + this.refreshTokenExpiresIn * 24 * 60 * 60 * 1000
      ),
    });

    const message = body.currentPassword
      ? 'Mật khẩu đã được thay đổi thành công.'
      : 'Mật khẩu đã được đặt thành công.';

    return {
      message,
      accessToken: result.tokens.accessToken,
    };
  }

  @UseGuards(JwtAuthGuard)
  @Post('set-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Set password for a user (e.g., OAuth users)' })
  @ApiResponse({ status: 200, description: 'Password successfully set.' })
  @ApiResponse({ status: 400, description: 'Bad Request (user already has a password).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid access token).' })
  async setPassword(
    @Request() req,
    @Body() body: SetPasswordDto,
    @Res({ passthrough: true }) response: Response
  ) {
    await this.passwordService.setPassword(req.user.id, body.newPassword);

    const user = await this.userService.findOneById(req.user.id);
    const result = await this.loginService.login(
      user,
      req.ip,
      req.headers['user-agent'] || ''
    );

    if (result.status === '2fa_required') {
       throw new UnauthorizedException('2FA required');
    }

    response.cookie('refresh_token', result.tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + this.refreshTokenExpiresIn * 24 * 60 * 60 * 1000
      ),
    });
    return {
      message: 'Mật khẩu đã được đặt thành công.',
      accessToken: result.tokens.accessToken,
    };
  }

  @UseGuards(RefreshTokenGuard)
  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Log out the current user' })
  @ApiResponse({ status: 200, description: 'User successfully logged out.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid refresh token).' })
  async logout(@Request() req, @Res({ passthrough: true }) response: Response) {
    const refreshToken = req.cookies['refresh_token'];
    if (refreshToken) {
      await this.tokenService.revokeRefreshToken(req.user.sub, refreshToken);
    }
    response.clearCookie('refresh_token');
    response.clearCookie('2fa_secret');
    response.clearCookie('2fa_partial_token');
    return { message: 'Đăng xuất thành công.' };
  }

  @UseGuards(RefreshTokenGuard)
  @Post('logout-all')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Log out user from all devices' })
  @ApiResponse({ status: 200, description: 'User successfully logged out from all devices.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid refresh token).' })
  async logoutAll(
    @Request() req,
    @Res({ passthrough: true }) response: Response
  ) {
    await this.tokenService.removeAllRefreshTokensForUser(req.user.sub);
    await this.tokenService.invalidateAllTokens(req.user.sub);
    response.clearCookie('refresh_token');
    response.clearCookie('2fa_secret');
    response.clearCookie('2fa_partial_token');
    return { message: 'Đã đăng xuất khỏi tất cả các thiết bị.' };
  }

  @Get('google')
  @UseGuards(AuthGuard('google'))
  @ApiOperation({ summary: 'Initiate Google OAuth login' })
  @ApiResponse({ status: 302, description: 'Redirects to Google for authentication.' })
  async googleAuth() {
    return HttpStatus.OK;
  }

  @Get('google/callback')
  @UseGuards(AuthGuard('google'))
  @ApiOperation({ summary: 'Google OAuth callback' })
  @ApiResponse({ status: 302, description: 'Redirects to frontend after Google authentication.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (Google authentication failed).' })
  async googleAuthRedirect(@Request() req, @Res() res: Response) {
    const user = req.user as User;
    if (!user) {
      throw new UnauthorizedException('Could not authenticate with Google.');
    }

    if (user.isTwoFactorAuthenticationEnabled) {
      const { accessToken } = await this.tokenService.generate2FAPartialToken(
        user.id
      );
      res.cookie('2fa_partial_token', accessToken, {
        httpOnly: true,
        secure: this.configService.get('NODE_ENV') === 'production',
        sameSite:
          this.configService.get('NODE_ENV') === 'production' ? 'none' : 'lax',
        expires: new Date(Date.now() + 5 * 60 * 1000),
      });
      const twoFactorUrl = this.configService.get<string>('FRONTEND_2FA_URL');
      if (!twoFactorUrl) {
        throw new Error('Missing FRONTEND_2FA_URL environment variable.');
      }
      return res.redirect(twoFactorUrl);
    } else {
      const code = await this.oauthService.generateOneTimeCode(user.id);
      const frontendCallbackUrl = this.configService.get<string>(
        'FRONTEND_AUTH_CALLBACK_URL'
      );
      if (!frontendCallbackUrl) {
        throw new Error(
          'Missing FRONTEND_AUTH_CALLBACK_URL environment variable.'
        );
      }
      const redirectUrl = `${frontendCallbackUrl}?code=${code}`;
      return res.redirect(redirectUrl);
    }
  }

  @Post('exchange-code')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Exchange one-time code for tokens' })
  @ApiResponse({ status: 200, description: 'Code successfully exchanged for tokens.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid or expired code).' })
  async exchangeCode(
    @Body() exchangeCodeDto: ExchangeCodeDto,
    @Res({ passthrough: true }) response: Response,
    @Request() req: { ip: string; headers: { 'user-agent': string } }
  ) {
    const result = await this.loginService.exchangeCodeForTokens(
        exchangeCodeDto.code,
        req.ip,
        req.headers['user-agent']
      );

    response.cookie('refresh_token', result.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + this.refreshTokenExpiresIn * 24 * 60 * 60 * 1000
      ),
    });

    return { accessToken: result.accessToken, user: result.user };
  }

  @Post('forgot-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Initiate forgot password process' })
  @ApiResponse({ status: 200, description: 'Password reset email sent (if user exists).' })
  async forgotPassword(@Body() forgotPasswordDto: ForgotPasswordDto) {
    return this.passwordService.forgotPassword(forgotPasswordDto.email);
  }

  @Post('reset-password')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Reset user password with token' })
  @ApiResponse({ status: 200, description: 'Password successfully reset.' })
  @ApiResponse({ status: 400, description: 'Bad Request (invalid or expired token).' })
  async resetPassword(@Body() resetPasswordDto: ResetPasswordDto) {
    return this.passwordService.resetPassword(
      resetPasswordDto.token,
      resetPasswordDto.newPassword
    );
  }

  @UseGuards(JwtAuthGuard)
  @Get('link-google')
  @ApiOperation({ summary: 'Initiate Google account linking' })
  @ApiResponse({ status: 200, description: 'Redirect URL for Google OAuth provided.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid access token).' })
  async linkGoogleInit(@Req() req) {
    const stateToken = await this.oauthService.generateOneTimeCode(req.user.id);
    const apiBaseUrl = this.configService.get('API_BASE_URL');
    const googleAuthUrl = `${apiBaseUrl}/auth/link-google/redirect?state=${stateToken}`;
    return { redirectUrl: googleAuthUrl };
  }

  @Get('link-google/redirect')
  @UseGuards(AuthGuard('google-link'))
  @ApiOperation({ summary: 'Google OAuth redirect for account linking' })
  @ApiResponse({ status: 302, description: 'Redirects to Google for authentication.' })
  async linkGoogleRedirect(@Req() req, @Query('state') state: string) {
    return HttpStatus.OK;
  }

  @Get('link-google/callback')
  @UseGuards(AuthGuard('google-link'))
  @ApiOperation({ summary: 'Google OAuth callback for account linking' })
  @ApiResponse({ status: 302, description: 'Redirects to frontend after account linking.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid state token).' })
  @ApiResponse({ status: 400, description: 'Bad Request (email mismatch).' })
  @ApiResponse({ status: 409, description: 'Conflict (account already linked).' })
  async linkGoogleCallback(@Req() req, @Res() res: Response) {
    const frontendUrl = this.configService.get<string>('FRONTEND_URL');

    try {
      const googleProfile = req.user as any;
      const state = googleProfile.state;

      if (!state) {
        throw new UnauthorizedException('Missing state parameter.');
      }

      const key = `one-time-code:${state}`;
      const userId = await this.cacheManager.get<string>(key);

      if (!userId) {
        throw new UnauthorizedException('Invalid or expired state token.');
      }

      await this.cacheManager.del(key);

      await this.oauthService.linkGoogleAccount(userId, {
        provider: googleProfile.provider,
        providerId: googleProfile.providerId,
        email: googleProfile.email,
        name: googleProfile.name,
        avatarUrl: googleProfile.avatarUrl,
      });

      return res.redirect(`${frontendUrl}/settings/account?linkSuccess=true`);
    } catch (error) {
      const errorMessage = encodeURIComponent(
        error instanceof Error
          ? error.message
          : 'Có lỗi xảy ra khi liên kết tài khoản.'
      );
      return res.redirect(
        `${frontendUrl}/settings/account?linkError=${errorMessage}`
      );
    }
  }

  @UseGuards(JwtAuthGuard)
  @Post('unlink-oauth')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Unlink an OAuth account (e.g., Google)' })
  @ApiResponse({ status: 200, description: 'OAuth account successfully unlinked.' })
  @ApiResponse({ status: 400, description: 'Bad Request (cannot unlink last login method).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid access token).' })
  @ApiResponse({ status: 404, description: 'Not Found (provider not linked).' })
  async unlinkOAuthAccount(@Req() req, @Body() body: { provider: string }) {
    return this.oauthService.unlinkOAuthAccount(req.user.id, body.provider);
  }

  @UseGuards(JwtAuthGuard)
  @Get('linked-accounts')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Get linked OAuth accounts' })
  @ApiResponse({ status: 200, description: 'List of linked OAuth accounts.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (invalid access token).' })
  async getLinkedAccounts(@Req() req) {
    return this.oauthService.getLinkedAccounts(req.user.id);
  }

  @Get('verify-email-change')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Verify email change with token' })
  @ApiResponse({ status: 302, description: 'Redirects to frontend after email change verification.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (token not provided).' })
  async verifyEmailChange(@Query('token') token: string, @Res() res: Response) {
    const frontendUrl = this.configService.get<string>('FRONTEND_URL');

    try {
      if (!token) {
        throw new UnauthorizedException('Token không được cung cấp.');
      }

      const result = await this.emailChangeService.verifyEmailChange(token);

      return res.redirect(
        `${frontendUrl}/login?emailChanged=true&newEmail=${encodeURIComponent(result.newEmail)}`
      );
    } catch (error) {
      const errorMessage = encodeURIComponent(
        error instanceof Error
          ? error.message
          : 'Có lỗi xảy ra khi xác nhận thay đổi email.'
      );
      return res.redirect(
        `${frontendUrl}/settings/security?emailChangeError=${errorMessage}`
      );
    }
  }
}

import {
  Controller,
  Get,
  Patch,
  Delete,
  Body,
  ValidationPipe,
  UseGuards,
  Request,
  Post,
} from '@nestjs/common';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { UserService } from './user.service';
import { EmailChangeDto, UpdateUserDto } from '@live-chat/shared-dtos';
import { User } from '../database/entities';
import { EmailChangeService } from './services/email-change.service';

@Controller('user')
@UseGuards(JwtAuthGuard)
export class UserController {
  constructor(
    private readonly userService: UserService,
    private readonly emailChangeService: EmailChangeService,
  ) {}

  @Get('me')
  async getProfile(
    @Request() req
  ): Promise<Omit<User, 'passwordHash'> & { hasPassword: boolean }> {
    const userId = req.user.id; // take user ID from the request after authentication
    const user = await this.userService.findOneById(userId);

    // Very important: Remove the passwordHash field before returning to the client
    const { passwordHash, ...result } = user;
    return {
      ...result,
      hasPassword: !!passwordHash,
    };
  }

  @Patch('me')
  async updateProfile(
    @Request() req,
    @Body(new ValidationPipe()) updateUserDto: UpdateUserDto
  ): Promise<Omit<User, 'passwordHash'> & { hasPassword: boolean }> {
    const userId = req.user.id;
    const updatedUser = await this.userService.updateProfile(
      userId,
      updateUserDto
    );

    const { passwordHash, ...result } = updatedUser;
    return {
      ...result,
      hasPassword: !!passwordHash,
    };
  }

  @Delete('me')
  async deactivateAccount(@Request() req): Promise<{ message: string }> {
    const userId = req.user.id;
    await this.userService.deactivate(userId);
    return { message: 'Tài khoản của bạn đã được vô hiệu hóa thành công.' };
  }

  @Post('request-email-change')
  async requestEmailChange(@Request() req, @Body() body: EmailChangeDto) {
    const userId = req.user.id;
    return await this.emailChangeService.requestEmailChange(
      userId,
      body.newEmail,
      body.password
    );
  }

  @Get('pending-email-change')
  async getPendingEmailChange(@Request() req) {
    const userId = req.user.id;
    const pendingRequest = await this.emailChangeService.getPendingEmailChange(userId);
    return pendingRequest
      ? {
          newEmail: pendingRequest.newEmail,
          expiresAt: pendingRequest.expiresAt,
        }
      : null;
  }

  @Post('cancel-email-change')
  async cancelEmailChange(@Request() req) {
    const userId = req.user.id;
    return await this.emailChangeService.cancelEmailChange(userId);
  }
}

import {
  Controller,
  Post,
  UseGuards,
  Req,
  Res,
  Body,
  HttpCode,
  HttpStatus,
  UnauthorizedException,
  ForbiddenException,
  ValidationPipe,
  BadRequestException,
} from '@nestjs/common';
import { TwoFactorAuthenticationService } from './two-factor-authentication.service';
import { JwtAuthGuard } from '../guards/jwt-auth.guard';
import type { AuthenticatedRequest } from '../../common/types/authenticated-request.interface';
import { UserService } from '../../user/user.service';
import { TurnOn2faDto } from '@live-chat/shared-dtos';
import { EncryptionService } from '../../common/services/encryption.service';
import * as bcrypt from 'bcrypt';
import { ConfigService } from '@nestjs/config';
import { AuthGuard } from '@nestjs/passport';
import type { TwoFactorRequest } from '../../common/types/two-factor-request.interface';
import { type Response } from 'express';
import { ApiBody, ApiOperation, ApiResponse, ApiTags } from '@nestjs/swagger';
import { UserSecurityService } from '../../user/services/user-security.service';
import { LoginService } from '../services/login.service';

/**
 * Controller for handling two-factor authentication (2FA) related HTTP requests.
 * Provides endpoints for generating 2FA setup, turning 2FA on/off, and authenticating with 2FA.
 */
@ApiTags('2FA')
@Controller('2fa')
export class TwoFactorAuthenticationController {
  constructor(
    private readonly twoFactorAuthService: TwoFactorAuthenticationService,
    private readonly userService: UserService,
    private readonly userSecurityService: UserSecurityService,
    private readonly loginService: LoginService,
    private readonly encryptionService: EncryptionService,
    private readonly configService: ConfigService
  ) {}

  /**
   * Generates a 2FA secret and a QR code Data URL for the authenticated user.
   * The temporary secret is stored in an HttpOnly cookie.
   *
   * @param req - The authenticated request object.
   * @param res - The response object to set the 2FA secret cookie.
   * @returns An object containing the QR code Data URL.
   * @status 200 - OK.
   * @throws UnauthorizedException - If the user is not authenticated.
   */
  @Post('generate')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Generate 2FA secret and QR code' })
  @ApiResponse({ status: 200, description: 'QR code Data URL generated successfully.' })
  @ApiResponse({ status: 401, description: 'Unauthorized.' })
  async generate(@Req() req: AuthenticatedRequest, @Res() res) {
    const { user } = req;
    const { secret, otpAuthUrl } = await this.twoFactorAuthService.generateSecret(user as any);

    // Store the temporary secret in an HttpOnly cookie to be verified later
    res.cookie('2fa_secret', this.encryptionService.encrypt(secret), {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite:
        this.configService.get('NODE_ENV') === 'production' ? 'none' : 'lax',
      expires: new Date(Date.now() + 5 * 60 * 1000), // 5 minutes validity
    });

    const qrCodeDataURL = await this.twoFactorAuthService.generateQrCodeDataURL(otpAuthUrl);
    return res.json({ qrCodeDataURL });
  }

  /**
   * Turns on two-factor authentication for the authenticated user.
   * Verifies the provided 2FA code against the temporary secret stored in the cookie.
   *
   * @param req - The authenticated request object.
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @param res - The response object to clear the 2FA secret cookie.
   * @returns A success message and recovery codes.
   * @status 200 - OK.
   * @throws BadRequestException - If the 2FA secret cookie is not found.
   * @throws UnauthorizedException - If the 2FA code is wrong.
   */
  @Post('turn-on')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Turn on 2FA for the authenticated user' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: '2FA enabled successfully.' })
  @ApiResponse({ status: 400, description: 'Bad Request (2FA secret cookie not found).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (wrong authentication code).' })
  async turnOn(
    @Req() req: AuthenticatedRequest,
    @Body() body: TurnOn2faDto,
    @Res({ passthrough: true }) res: Response
  ) {
    const temporarySecretEncrypted = req.cookies['2fa_secret'];
    if (!temporarySecretEncrypted) {
      throw new BadRequestException(
        '2FA secret cookie not found. Please start over.'
      );
    }
    const temporarySecret = this.encryptionService.decrypt(
      temporarySecretEncrypted
    );

    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      temporarySecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    const { user, recoveryCodes } = await this.userSecurityService.turnOnTwoFactorAuthentication(
      req.user.id,
      temporarySecret
    );

    res.clearCookie('2fa_secret');

    return {
      message: 'Two-factor authentication has been enabled successfully.',
      recoveryCodes,
    };
  }

  /**
   * Authenticates a user with a 2FA code after a partial login.
   * Issues full access and refresh tokens upon successful 2FA verification.
   *
   * @param req - The request object containing partial user information (from 2FA partial guard).
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @param res - The response object to set cookies and return tokens.
   * @returns An object containing the access token and user details.
   * @status 200 - OK.
   * @throws UnauthorizedException - If the user is not found or the 2FA code is wrong.
   * @throws ForbiddenException - If 2FA is not enabled for the account.
   */
  @Post('authenticate')
  @UseGuards(AuthGuard('2fa-partial'))
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Authenticate with 2FA code' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: 'User successfully authenticated with 2FA.' })
  @ApiResponse({ status: 401, description: 'Unauthorized (user not found or wrong code).' })
  @ApiResponse({ status: 403, description: 'Forbidden (2FA not enabled).' })
  async authenticate(
    @Req() req: TwoFactorRequest,
    @Body() body: TurnOn2faDto,
    @Res() res
  ) {
    const ipAddress = req.ip;
    const userAgent = req.headers['user-agent'] || 'unknown';

    const user = await this.userService.findOneById(req.user.sub);

    if (!user) {
      throw new UnauthorizedException('User not found');
    }

    if (!user.isTwoFactorAuthenticationEnabled) {
      throw new ForbiddenException('2FA is not enabled for this account.');
    }

    const decryptedSecret = this.encryptionService.decrypt(
      user.twoFactorAuthenticationSecret as string
    );
    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      decryptedSecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    const data = await this.loginService.loginAfter2FA(
      user,
      ipAddress,
      userAgent
    );
    const { accessToken, refreshToken, user: userResult } = data;

    const refreshTokenExpiresIn = this.configService.get<string>(
      'JWT_REFRESH_EXPIRES_IN'
    ) as string;
    const refreshTokenExpiryDays = parseInt(
      refreshTokenExpiresIn.slice(0, -1),
      10
    );
    // Set the refresh token in an HttpOnly cookie
    res.cookie('refresh_token', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
      expires: new Date(
        Date.now() + refreshTokenExpiryDays * 24 * 60 * 60 * 1000
      ),
    });

    // Clear the temporary cookies
    res.clearCookie('2fa_partial_token');
    res.clearCookie('2fa_secret');

    // Return full tokens, setting the refresh token in the cookie
    res.json({ accessToken, user: userResult });
  }

  /**
   * Turns off two-factor authentication for the authenticated user.
   * Requires the user to provide a valid 2FA code for verification.
   *
   * @param req - The authenticated request object.
   * @param body - The TurnOn2faDto containing the 2FA code.
   * @returns A success message.
   * @status 200 - OK.
   * @throws ForbiddenException - If 2FA is not enabled for the account.
   * @throws UnauthorizedException - If the 2FA code is wrong.
   */
  @Post('turn-off')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Turn off 2FA for the authenticated user' })
  @ApiBody({ type: TurnOn2faDto })
  @ApiResponse({ status: 200, description: '2FA disabled successfully.' })
  @ApiResponse({ status: 403, description: 'Forbidden (2FA not enabled).' })
  @ApiResponse({ status: 401, description: 'Unauthorized (wrong authentication code).' })
  async turnOff(
    @Req() req: AuthenticatedRequest,
    @Body() body: TurnOn2faDto // Reuse the DTO that has the 'code' field
  ) {
    const user = await this.userService.findOneById(req.user.id);

    if (!user.isTwoFactorAuthenticationEnabled) {
      throw new ForbiddenException('2FA is not enabled for this account.');
    }

    const decryptedSecret = this.encryptionService.decrypt(
      user.twoFactorAuthenticationSecret as string
    );

    const isCodeValid = this.twoFactorAuthService.isCodeValid(
      body.code,
      decryptedSecret
    );

    if (!isCodeValid) {
      throw new UnauthorizedException('Wrong authentication code');
    }

    await this.userSecurityService.turnOffTwoFactorAuthentication(req.user.id);

    return { message: 'Two-factor authentication has been disabled.' };
  }
}

import { Strategy } from 'passport-local';
import { PassportStrategy } from '@nestjs/passport';
import {
  Injectable,
  UnauthorizedException,
  ForbiddenException,
} from '@nestjs/common';
import { PasswordService } from '../services/password.service';
import { User } from '../../database/entities';

@Injectable()
export class LocalStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly passwordService: PasswordService) {
    // Configuration for Passport-local.
    // By default, it will look for 'username' and 'password' fields in the request body.
    // Here, we explicitly specify that our username field is 'email'.
    super({ usernameField: 'email' });
  }

  /**
   * Passport will automatically call this validate function when LocalAuthGuard is activated.
   * @param email Value from the 'email' field in the request body.
   * @param password Value from the 'password' field in the request body.
   * @returns User object if authentication is successful.
   * @throws UnauthorizedException if authentication fails.
   */
  async validate(email: string, password: string): Promise<User> {
    // Delegate email and password checking to PasswordService.
    const user = await this.passwordService.validateUser(email, password);

    // If PasswordService returns null, it means the information is invalid.
    if (!user) {
      throw new UnauthorizedException('Email hoặc mật khẩu không chính xác.');
    }

    // Check if the user's email is verified.
    if (!user.isEmailVerified) {
      throw new ForbiddenException(
        'Vui lòng xác thực email của bạn trước khi đăng nhập.'
      );
    }

    // If authentication is successful, return the entire user object.
    // Passport will automatically attach this object to request.user.
    return user;
  }
}

import { PassportStrategy } from '@nestjs/passport';
import { Strategy, VerifyCallback, Profile } from 'passport-google-oauth20';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { OAuthService } from '../services/oauth.service';

/**
 * Passport strategy for authenticating users via Google OAuth 2.0.
 * This strategy handles the initial Google login flow, validating the Google profile
 * and either finding an existing user, linking to an existing user by email,
 * or creating a new user and identity.
 */
@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  constructor(
    private readonly configService: ConfigService,
    private readonly oauthService: OAuthService
  ) {
    super({
      clientID: configService.get<string>('GOOGLE_CLIENT_ID') as string,
      clientSecret: configService.get<string>('GOOGLE_CLIENT_SECRET') as string,
      callbackURL: `${configService.get<string>('API_BASE_URL')}/auth/google/callback`,
      scope: ['email', 'profile'],
    });
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: Profile,
    done: VerifyCallback
  ): Promise<any> {
    const { id, displayName, emails, photos } = profile;
    if (!emails || emails.length === 0) {
      return done(new Error('No email associated with this account!'), false);
    }

    if (!photos || photos.length === 0) {
      return done(
        new Error('No profile picture associated with this account!'),
        false
      );
    }

    const googleProfile = {
      provider: 'google',
      providerId: id,
      email: emails[0].value,
      name: displayName,
      avatarUrl: photos[0].value,
    };

    const user = await this.oauthService.validateOAuthUser(googleProfile);
    done(null, user);
  }
}

