import { EventConsumerService } from './event-consumer.service';
import { EntityManager } from 'typeorm';
import { Message, Visitor } from '../database/entities';
import {
  MessageStatus,
  WorkerEventTypes,
  WorkerEvent,
  NewMessageFromVisitorPayload,
} from '@live-chat/shared-types';
import { VisitorPersistenceService } from '../inbox/services/persistence/visitor.persistence.service';
import { ConversationPersistenceService } from '../inbox/services/persistence/conversation.persistence.service';
import { MessagePersistenceService } from '../inbox/services/persistence/message.persistence.service';
import { OutboxPersistenceService } from './outbox.persistence.service';

describe('EventConsumerService', () => {
  let service: EventConsumerService;
  let visitorPersistenceService: jest.Mocked<VisitorPersistenceService>;
  let conversationPersistenceService: jest.Mocked<ConversationPersistenceService>;
  let messagePersistenceService: jest.Mocked<MessagePersistenceService>;
  let outboxPersistenceService: jest.Mocked<OutboxPersistenceService>;
  let entityManager: jest.Mocked<EntityManager>;

  beforeEach(async () => {
    const mockEntityManager = {
      transaction: jest.fn().mockImplementation((cb) => cb(mockEntityManager)),
      query: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EventConsumerService,
        {
          provide: VisitorPersistenceService,
          useValue: {
            findOrCreateByUid: jest.fn(),
          },
        },
        {
          provide: ConversationPersistenceService,
          useValue: {
            findOrCreateByVisitorId: jest.fn(),
            updateLastMessage: jest.fn(),
          },
        },
        {
          provide: MessagePersistenceService,
          useValue: {
            createMessage: jest.fn(),
          },
        },
        {
          provide: OutboxPersistenceService,
          useValue: {
            createEvent: jest.fn(),
          },
        },
        {
          provide: EntityManager,
          useValue: mockEntityManager,
        },
      ],
    }).compile();

    service = module.get<EventConsumerService>(EventConsumerService);
    visitorPersistenceService = module.get(VisitorPersistenceService);
    conversationPersistenceService = module.get(ConversationPersistenceService);
    messagePersistenceService = module.get(MessagePersistenceService);
    outboxPersistenceService = module.get(OutboxPersistenceService);
    entityManager = module.get(EntityManager);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('processEvent', () => {
    it('should handle NEW_MESSAGE_FROM_VISITOR event', async () => {
      const handleNewMessageSpy = jest
        .spyOn(service as any, 'handleNewMessageFromVisitor')
        .mockResolvedValue(undefined);

      const event: WorkerEvent<NewMessageFromVisitorPayload> = {
        type: WorkerEventTypes.NEW_MESSAGE_FROM_VISITOR,
        payload: {
          tempId: 'temp-1',
          content: 'Hello',
          visitorUid: 'visitor-123',
          projectId: 1,
          socketId: 'socket-abc',
        },
      };

      await service.processEvent(event);

      expect(handleNewMessageSpy).toHaveBeenCalledWith(event.payload);
    });

    it('should log warning for unhandled event type', async () => {
      // Cast to WorkerEvent to test unhandled type scenario
      const event = {
        type: 'UNKNOWN_TYPE',
        payload: {},
      } as unknown as WorkerEvent;

      await expect(service.processEvent(event)).resolves.not.toThrow();
    });
  });

  describe('handleNewMessageFromVisitor', () => {
    it('should create entities and insert outbox event', async () => {
      const payload: NewMessageFromVisitorPayload = {
        tempId: 'temp-1',
        content: 'Hello',
        visitorUid: 'visitor-123',
        projectId: 1,
        socketId: 'socket-abc',
      };

      const visitor = new Visitor();
      visitor.id = 1;
      visitor.visitorUid = 'visitor-123';

      const conversation = { id: 100 };
      const savedMessage = { id: 'msg-1' } as Message;

      visitorPersistenceService.findOrCreateByUid.mockResolvedValue(visitor);
      conversationPersistenceService.findOrCreateByVisitorId.mockResolvedValue(
        conversation as any
      );
      messagePersistenceService.createMessage.mockResolvedValue(savedMessage);
      outboxPersistenceService.createEvent.mockResolvedValue({} as any);

      // Call private method via casting
      await (service as any).handleNewMessageFromVisitor(payload);

      expect(visitorPersistenceService.findOrCreateByUid).toHaveBeenCalledWith(
        payload.projectId,
        payload.visitorUid,
        expect.anything()
      );
      expect(
        conversationPersistenceService.findOrCreateByVisitorId
      ).toHaveBeenCalledWith(payload.projectId, visitor.id, expect.anything());
      expect(messagePersistenceService.createMessage).toHaveBeenCalledWith(
        payload.tempId,
        payload.visitorUid,
        expect.objectContaining({
          conversationId: conversation.id,
          content: payload.content,
          senderId: visitor.visitorUid,
          status: MessageStatus.SENT,
        }),
        expect.anything()
      );
      expect(
        conversationPersistenceService.updateLastMessage
      ).toHaveBeenCalled();

      // Verify outbox persistence service was called
      expect(outboxPersistenceService.createEvent).toHaveBeenCalledWith(
        'message',
        savedMessage.id,
        WorkerEventTypes.NEW_MESSAGE_FROM_VISITOR,
        expect.objectContaining({
          message: savedMessage,
          tempId: payload.tempId,
          visitorUid: payload.visitorUid,
        }),
        expect.anything()
      );
    });
  });
});

// src/event-consumer/event-consumer.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { EntityManager } from 'typeorm';
import {
  MessageStatus,
  WorkerEventTypes,
  WorkerEvent,
  NewMessageFromVisitorPayload,
} from '@live-chat/shared-types';
import { VisitorPersistenceService } from '../inbox/services/persistence/visitor.persistence.service';
import { ConversationPersistenceService } from '../inbox/services/persistence/conversation.persistence.service';
import { MessagePersistenceService } from '../inbox/services/persistence/message.persistence.service';
import { OutboxPersistenceService } from './outbox.persistence.service';

@Injectable()
export class EventConsumerService {
  private readonly logger = new Logger(EventConsumerService.name);

  constructor(
    private readonly conversationPersistenceService: ConversationPersistenceService,
    private readonly visitorPersistenceService: VisitorPersistenceService,
    private readonly messagePersistenceService: MessagePersistenceService,
    private readonly outboxPersistenceService: OutboxPersistenceService,
    private readonly entityManager: EntityManager
  ) {}

  /**
   * Process an incoming worker event.
   * Uses typed events from @live-chat/shared-types for type safety.
   */
  public async processEvent(event: WorkerEvent): Promise<void> {
    const { type, payload } = event;

    this.logger.log(`Processing event type: ${type}`);

    try {
      switch (type) {
        case WorkerEventTypes.NEW_MESSAGE_FROM_VISITOR:
          await this.handleNewMessageFromVisitor(
            payload as NewMessageFromVisitorPayload
          );
          break;
        default:
          this.logger.warn(`Unhandled event type: ${type}`);
      }
    } catch (error) {
      this.logger.error(`Error processing event ${type}`, error);
      throw error;
    }
  }

  private async handleNewMessageFromVisitor(
    payload: NewMessageFromVisitorPayload
  ): Promise<void> {
    this.logger.log(`Handling new message from visitor: ${payload.visitorUid}`);
    const { tempId, visitorUid, projectId, content } = payload;

    await this.entityManager.transaction(async (manager) => {
      this.logger.log(`[Transaction] Started for visitor: ${visitorUid}`);

      const visitor = await this.visitorPersistenceService.findOrCreateByUid(
        projectId,
        visitorUid,
        manager
      );
      this.logger.log(`[Transaction] Found or created visitor: ${visitor.id}`);

      const conversation =
        await this.conversationPersistenceService.findOrCreateByVisitorId(
          projectId,
          visitor.id,
          manager
        );
      this.logger.log(
        `[Transaction] Found or created conversation: ${conversation.id}`
      );

      const savedMessage = await this.messagePersistenceService.createMessage(
        tempId,
        visitorUid,
        {
          conversationId: conversation.id,
          content: content,
          senderId: visitor.visitorUid,
          recipientId: `project_${projectId}`,
          fromCustomer: true,
          status: MessageStatus.SENT,
        },
        manager
      );
      this.logger.log(`[Transaction] Created message: ${savedMessage.id}`);

      await this.conversationPersistenceService.updateLastMessage(
        conversation.id,
        content,
        new Date(),
        manager
      );
      this.logger.log(
        `[Transaction] Updated last message for conversation: ${conversation.id}`
      );

      // Use OutboxPersistenceService instead of raw SQL
      await this.outboxPersistenceService.createEvent(
        'message',
        savedMessage.id,
        WorkerEventTypes.NEW_MESSAGE_FROM_VISITOR,
        {
          message: savedMessage,
          tempId,
          visitorUid,
        },
        manager
      );
      this.logger.log(
        `[Transaction] Inserted event for message ${savedMessage.id} into outbox.`
      );
    });
  }
}

import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { Logger } from '@nestjs/common';
import { Injectable } from '@nestjs/common';
import { EventConsumerService } from './event-consumer.service';

@Processor('live-chat-events-queue')
@Injectable()
export class EventProcessor extends WorkerHost {
  private readonly logger = new Logger(EventProcessor.name);

  constructor(private readonly eventConsumerService: EventConsumerService) {
    super();
  }

  async process(job: Job<any, any, string>): Promise<any> {
    this.logger.log(`Processing job ${job.id} of type ${job.name}`);
    try {
      if (job.name === 'event-job') {
        const payload = job.data;
        const event = payload;

        await this.eventConsumerService.processEvent(event);
      }
    } catch (error) {
       this.logger.error(`Failed to process job ${job.id}`, error);
       throw error;
    }
  }
}

import { Injectable, Logger, OnModuleInit, OnModuleDestroy, Inject } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { Client } from 'pg';
import { ConfigService } from '@nestjs/config';
import { REDIS_PUBLISHER_CLIENT } from '../redis/redis.module';
import { Redis } from 'ioredis';

@Injectable()
export class OutboxListenerService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(OutboxListenerService.name);
  private pgClient: Client;

  constructor(
    private readonly dataSource: DataSource,
    private readonly configService: ConfigService,
    @Inject(REDIS_PUBLISHER_CLIENT) private readonly redisPublisher: Redis
  ) {}

  async onModuleInit() {
    this.logger.log('Initializing Outbox Listener...');

    this.pgClient = new Client({
      host: this.configService.get<string>('PSQL_HOST'),
      port: this.configService.get<number>('PSQL_PORT'),
      user: this.configService.get<string>('PSQL_USER'),
      password: this.configService.get<string>('PSQL_PASSWORD'),
      database: this.configService.get<string>('PSQL_DATABASE'),
    });

    try {
      await this.pgClient.connect();
      this.logger.log('Dedicated PostgreSQL client connected for LISTEN/NOTIFY.');

      this.pgClient.on('notification', async (msg) => {
        this.logger.debug(`Received notification on channel: ${msg.channel}`);
        if (msg.channel === 'outbox_channel') {
          await this.processOutboxEvents();
        }
      });

      await this.pgClient.query('LISTEN outbox_channel');
      this.logger.log('Successfully listening on "outbox_channel".');

      // Optional: Add a fallback poller for added robustness
      setInterval(() => this.processOutboxEvents(), 60000); // every 60 seconds
    } catch (error) {
      this.logger.error('Failed to initialize Outbox Listener', error);
    }
  }

  async onModuleDestroy() {
    if (this.pgClient) {
      this.logger.log('Closing PostgreSQL client...');
      await this.pgClient.end();
    }
  }

  private async processOutboxEvents() {
    this.logger.debug('Processing outbox events...');
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();

    try {
      await queryRunner.startTransaction();

      // Select and lock rows to prevent race conditions if you run multiple listeners
      const events = await queryRunner.manager.query(
        `SELECT * FROM outbox_events ORDER BY created_at ASC LIMIT 100 FOR UPDATE SKIP LOCKED`
      );

      if (events.length === 0) {
        await queryRunner.commitTransaction();
        return;
      }

      this.logger.log(`Found ${events.length} events to process.`);

      for (const event of events) {
        await this.redisPublisher.publish(
          'new_message_channel',
          JSON.stringify(event.payload)
        );
      }

      const eventIds = events.map((e) => e.id);
      // Use parameterized query for array inclusion
      await queryRunner.manager.query(
        `DELETE FROM outbox_events WHERE id = ANY($1)`,
        [eventIds]
      );

      await queryRunner.commitTransaction();
      this.logger.log(
        `Successfully processed and deleted ${events.length} events.`
      );
    } catch (error) {
      this.logger.error('Error processing outbox events', error);
      await queryRunner.rollbackTransaction();
    } finally {
      await queryRunner.release();
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EntityManager, Repository } from 'typeorm';
import { InjectRepository } from '@nestjs/typeorm';
import { OutboxEvent } from '../database/entities';
import { WorkerEventType } from '@live-chat/shared-types';

/**
 * Payload structure for outbox events.
 */
export interface OutboxEventPayload {
  message: unknown;
  tempId: string;
  visitorUid: string;
  [key: string]: unknown; // Index signature for Record<string, unknown> compatibility
}

@Injectable()
export class OutboxPersistenceService {
  private readonly logger = new Logger(OutboxPersistenceService.name);

  constructor(
    @InjectRepository(OutboxEvent)
    private readonly outboxRepository: Repository<OutboxEvent>
  ) {}

  /**
   * Creates an outbox event within a transaction.
   * Uses TypeORM entity instead of raw SQL for type safety.
   *
   * @param aggregateType - The type of aggregate (e.g., 'message')
   * @param aggregateId - The ID of the aggregate
   * @param eventType - The type of event (from WorkerEventTypes)
   * @param payload - The event payload
   * @param manager - The EntityManager from an active transaction
   */
  async createEvent(
    aggregateType: string,
    aggregateId: string | number,
    eventType: WorkerEventType,
    payload: OutboxEventPayload,
    manager: EntityManager
  ): Promise<OutboxEvent> {
    const outboxRepo = manager.getRepository(OutboxEvent);

    const event = outboxRepo.create({
      aggregateType,
      aggregateId: String(aggregateId),
      eventType,
      payload,
    });

    const savedEvent = await outboxRepo.save(event);

    this.logger.log(
      `Inserted outbox event for ${aggregateType}:${aggregateId} (type: ${eventType})`
    );

    return savedEvent;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class BullMqProducerService {
  private readonly logger = new Logger(BullMqProducerService.name);

  constructor(
    @InjectQueue('live-chat-events-queue') private readonly queue: Queue
  ) {}

  async sendMessage(payload: any): Promise<string> {
    try {
      const job = await this.queue.add('event-job', payload, {
        removeOnComplete: true,
        removeOnFail: false,
      });
      this.logger.log(`Successfully added job ${job.id} to BullMQ.`);
      this.logger.debug(`Job payload: ${JSON.stringify(payload)}`);
      return job.id as string;
    } catch (error) {
      if (error instanceof Error) {
        this.logger.error(
          `Failed to add job to BullMQ: ${error.message}`,
          error.stack
        );
      } else {
        this.logger.error(
          `An unknown error occurred while adding a job to BullMQ`,
          error
        );
      }
      throw error;
    }
  }
}

