// src/mail/mail.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as nodemailer from 'nodemailer';
import { User, Invitation, Project } from '../database/entities';
import { EmailTemplateService } from './email-template.service';

@Injectable()
export class MailService {
  private transporter: nodemailer.Transporter;
  private readonly logger = new Logger(MailService.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly emailTemplateService: EmailTemplateService
  ) {
  // Create a transporter object using the SMTP transport
    this.transporter = nodemailer.createTransport({
      host: this.configService.get<string>('MAIL_HOST'), // 'smtp.gmail.com'
      port: this.configService.get<number>('MAIL_PORT'), // 465
      secure: this.configService.get<boolean>('MAIL_SECURE'), // true
      auth: {
        user: this.configService.get<string>('MAIL_USER'), // Your Gmail address from .env
        pass: this.configService.get<string>('MAIL_APP_PASSWORD'), // Your App Password from .env
      },
    });
  }

  /**
   * Sends an email.
   * @param to The recipient's email address.
   * @param subject The subject of the email.
   * @param html The HTML content of the email.
   */
  async sendMail(to: string, subject: string, html: string): Promise<void> {
    const mailOptions = {
      from: `"Live Chat" <${this.configService.get<string>('MAIL_USER')}>`, // sender address
      to: to, // list of receivers
      subject: subject, // Subject line
      html: html, // html body
    };

    try {
      const info = await this.transporter.sendMail(mailOptions);
      this.logger.log(`Message sent: ${info.messageId}`);
    } catch (error) {
      this.logger.error('Error sending email:', error);
      // Depending on your app's needs, you might want to throw the error
      // or handle it gracefully.
      throw new Error('Could not send email.');
    }
  }

  async sendUserConfirmation(user: User, token: string) {
    const { subject, html } = this.emailTemplateService.getUserConfirmationTemplate(user, token);
    await this.sendMail(user.email, subject, html);
  }

  async sendPasswordResetEmail(user: User, token: string) {
    const { subject, html } = this.emailTemplateService.getPasswordResetTemplate(user, token);
    await this.sendMail(user.email, subject, html);
  }

  /**
   * Send email change verification to new email address
   * @param user User requesting email change
   * @param newEmail New email address
   * @param token Verification token
   */
  async sendEmailChangeVerification(
    user: User,
    newEmail: string,
    token: string
  ) {
    const { subject, html } = this.emailTemplateService.getEmailChangeVerificationTemplate(user, newEmail, token);
    await this.sendMail(newEmail, subject, html);
  }

  /**
   * Send confirmation to old email address after successful email change
   * @param oldEmail Old email address
   * @param newEmail New email address
   * @param userName User's full name
   */
  async sendEmailChangeConfirmation(
    oldEmail: string,
    newEmail: string,
    userName: string
  ) {
    const { subject, html } = this.emailTemplateService.getEmailChangeConfirmationTemplate(oldEmail, newEmail, userName);
    await this.sendMail(oldEmail, subject, html);
  }

  /**
   * Send notification to old email address about email change request
   * @param user User requesting email change
   * @param newEmail New email address
   */
  async sendEmailChangeNotification(user: User, newEmail: string) {
    const { subject, html } = this.emailTemplateService.getEmailChangeNotificationTemplate(user, newEmail);
    await this.sendMail(user.email, subject, html);
  }

  async sendInvitationEmail(invitation: Invitation, project: Project, existingUser?: User) {
    const { subject, html, invitationUrl } = this.emailTemplateService.getInvitationTemplate(invitation, project, existingUser);

    if (!existingUser) {
      this.logger.log(`Sending NEW USER invitation to ${invitation.email} - Link: ${invitationUrl}`);
    } else {
      this.logger.log(`Sending EXISTING USER invitation to ${invitation.email} (userId: ${existingUser.id}) - Link: ${invitationUrl}`);
    }

    await this.sendMail(invitation.email, subject, html);
  }
}

import 'crypto';
import { Logger, ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import cookieParser from 'cookie-parser';
import { json } from 'body-parser';
import { RedisIoAdapter } from './gateway/redis-io.adapter';
import { ConfigService } from '@nestjs/config';
import { LoggerMiddleware } from './common/middleware/logger.middleware';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { execSync } from 'child_process';

/**
 * Kill any process currently using a specific port.
 * This prevents EADDRINUSE errors during development restarts.
 */
function killPort(port: number): void {
  try {
    // Find and kill processes using the port (Linux/macOS)
    execSync(`lsof -ti :${port} | xargs -r kill -9 2>/dev/null || true`, {
      stdio: 'ignore',
    });
    Logger.log(`Cleared port ${port} if it was in use.`, 'Bootstrap');
  } catch {
    // Ignore errors - port might not be in use
  }
}

async function bootstrap() {
  const PORT = 3000;

  // Kill any existing process on the port before starting
  killPort(PORT);

  const app = await NestFactory.create(AppModule, {
    bodyParser: false,
  });

  const configService = app.get(ConfigService);

  app.enableCors({
    origin: true,
    methods: 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
    credentials: true,
  });

  // Setup Redis Adapter for WebSocket
  const redisIoAdapter = new RedisIoAdapter(app, configService);
  await redisIoAdapter.connectToRedis();
  app.useWebSocketAdapter(redisIoAdapter);
  Logger.log('WebSocket adapter (RedisIoAdapter) has been set.', 'main.ts');

  const logger = new LoggerMiddleware();
  app.use(logger.use.bind(logger));
  app.use(json());
  app.use(cookieParser());
  app.useGlobalPipes(new ValidationPipe());
  app.setGlobalPrefix('api/v1');

  // Swagger/OpenAPI Setup
  const swaggerConfig = new DocumentBuilder()
    .setTitle('Live Chat API')
    .setDescription('API documentation for the Live Chat application')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('api', app, document);

  await app.listen(PORT);
  Logger.log(`Application listening on port ${PORT}`, 'Bootstrap');
}

bootstrap();

import {
  Injectable,
  BadRequestException,
  NotFoundException,
  ForbiddenException,
  ConflictException,
  Logger,
} from '@nestjs/common';
import { EntityManager } from 'typeorm';
import * as crypto from 'crypto';
import { CreateInvitationDto } from '@live-chat/shared-dtos';
import { Invitation, Project, User, ProjectMember } from '../database/entities';
import { InvitationStatus, ProjectRole } from '@live-chat/shared-types';
import { MailService } from '../mail/mail.service';

@Injectable()
export class InvitationService {
  private readonly logger = new Logger(InvitationService.name);

  constructor(
    private readonly entityManager: EntityManager,
    private readonly mailService: MailService
  ) {}

  /**
   * Creates an invitation and sends an email to the invitee
   */
  async createInvitation(
    createInvitationDto: CreateInvitationDto,
    inviterId: string
  ): Promise<Invitation> {
    const { email, projectId, role = ProjectRole.AGENT } = createInvitationDto;

    // 1. Verify that the inviter is a MANAGER of the project
    const inviterMembership = await this.entityManager.findOne(ProjectMember, {
      where: { projectId, userId: inviterId },
    });

    if (!inviterMembership || inviterMembership.role !== ProjectRole.MANAGER) {
      throw new ForbiddenException(
        'Only managers can invite members to this project.'
      );
    }

    // 2. Check if project exists
    const project = await this.entityManager.findOne(Project, {
      where: { id: projectId },
    });

    if (!project) {
      throw new NotFoundException('Project not found.');
    }

    // 3. Check if the user is already a member
    const existingUser = await this.entityManager.findOne(User, {
      where: { email },
    });

    if (existingUser) {
      const existingMembership = await this.entityManager.findOne(
        ProjectMember,
        {
          where: { projectId, userId: existingUser.id },
        }
      );

      if (existingMembership) {
        throw new ConflictException(
          'This user is already a member of the project.'
        );
      }
    }

    // 4. Check if there's a pending invitation for this email and project
    const existingInvitation = await this.entityManager.findOne(Invitation, {
      where: {
        email,
        projectId,
        status: InvitationStatus.PENDING,
      },
    });

    if (existingInvitation) {
      throw new ConflictException(
        'A pending invitation already exists for this email.'
      );
    }

    // 5. Generate a secure token
    const token = crypto.randomBytes(32).toString('hex');

    // 6. Set expiration (7 days from now)
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    // 7. Create and save the invitation
    const invitation = this.entityManager.create(Invitation, {
      email,
      projectId,
      inviterId,
      role,
      token,
      status: InvitationStatus.PENDING,
      expiresAt,
    });

    const savedInvitation = await this.entityManager.save(invitation);

    // 8. Send the invitation email
    await this.mailService.sendInvitationEmail(
      savedInvitation,
      project,
      existingUser ?? undefined
    );

    return savedInvitation;
  }

  /**
   * Accepts an invitation and adds the user to the project
   * This can be called after a user registers (for new users) or directly (for existing users)
   */
  async acceptInvitation(token: string, userId: string): Promise<void> {
    this.logger.log(`🔵 [AcceptInvitation] Starting acceptance process`);
    this.logger.log(`🔵 [AcceptInvitation] Token: ${token}`);
    this.logger.log(`🔵 [AcceptInvitation] UserId: ${userId}`);

    // 1. Find the invitation by token
    const invitation = await this.entityManager.findOne(Invitation, {
      where: { token },
    });

    if (!invitation) {
      this.logger.error(
        `❌ [AcceptInvitation] Invitation not found for token: ${token}`
      );
      throw new NotFoundException('Invitation not found.');
    }

    this.logger.log(`✅ [AcceptInvitation] Found invitation:`, {
      id: invitation.id,
      email: invitation.email,
      projectId: invitation.projectId,
      role: invitation.role,
      status: invitation.status,
      expiresAt: invitation.expiresAt,
    });

    // 2. Check if invitation is still pending
    if (invitation.status !== InvitationStatus.PENDING) {
      this.logger.error(
        `❌ [AcceptInvitation] Invitation status is not PENDING: ${invitation.status}`
      );
      throw new BadRequestException('This invitation has already been used.');
    }

    // 3. Check if invitation has expired
    if (new Date() > invitation.expiresAt) {
      this.logger.error(
        `❌ [AcceptInvitation] Invitation has expired: ${invitation.expiresAt}`
      );
      // Mark as expired
      invitation.status = InvitationStatus.EXPIRED;
      await this.entityManager.save(invitation);
      throw new BadRequestException('This invitation has expired.');
    }

    // 4. Get the user's email
    const user = await this.entityManager.findOne(User, {
      where: { id: userId },
    });

    if (!user) {
      this.logger.error(`❌ [AcceptInvitation] User not found: ${userId}`);
      throw new NotFoundException('User not found.');
    }

    this.logger.log(`✅ [AcceptInvitation] Found user: ${user.email}`);

    // 5. Verify the invitation is for this user's email
    if (user.email !== invitation.email) {
      this.logger.error(
        `❌ [AcceptInvitation] Email mismatch: user.email=${user.email}, invitation.email=${invitation.email}`
      );
      throw new ForbiddenException(
        'This invitation was sent to a different email address.'
      );
    }

    this.logger.log(`✅ [AcceptInvitation] Email match verified`);

    // 6. Check if user is already a member
    const existingMembership = await this.entityManager.findOne(ProjectMember, {
      where: { projectId: invitation.projectId, userId },
    });

    if (existingMembership) {
      this.logger.warn(
        `⚠️ [AcceptInvitation] User is already a member of project ${invitation.projectId}`
      );
      // Mark invitation as accepted anyway
      invitation.status = InvitationStatus.ACCEPTED;
      await this.entityManager.save(invitation);
      throw new ConflictException('You are already a member of this project.');
    }

    this.logger.log(
      `✅ [AcceptInvitation] User is not yet a member, proceeding to add...`
    );

    // 7. Add user to project with the specified role
    await this.entityManager.transaction(async (transactionalEntityManager) => {
      const membership = transactionalEntityManager.create(ProjectMember, {
        projectId: invitation.projectId,
        userId,
        role: invitation.role as ProjectRole,
      });

      this.logger.log(`🔵 [AcceptInvitation] Creating membership:`, {
        projectId: invitation.projectId,
        userId,
        role: invitation.role,
      });

      await transactionalEntityManager.save(membership);

      this.logger.log(`✅ [AcceptInvitation] Membership saved successfully`);

      // Mark invitation as accepted
      invitation.status = InvitationStatus.ACCEPTED;
      await transactionalEntityManager.save(invitation);

      this.logger.log(`✅ [AcceptInvitation] Invitation marked as ACCEPTED`);
    });

    this.logger.log(`🎉 [AcceptInvitation] Process completed successfully!`);
  }

  /**
   * Gets invitation details by token (for registration page to pre-fill email)
   */
  async getInvitationByToken(token: string): Promise<any> {
    const invitation = await this.entityManager.findOne(Invitation, {
      where: { token },
    });

    if (!invitation) {
      throw new NotFoundException('Invitation not found.');
    }

    // Check if invitation has expired
    if (new Date() > invitation.expiresAt) {
      throw new BadRequestException('This invitation has expired.');
    }

    // Check if invitation is still pending
    if (invitation.status !== InvitationStatus.PENDING) {
      throw new BadRequestException('This invitation has already been used.');
    }

    // Load project details
    const project = await this.entityManager.findOne(Project, {
      where: { id: invitation.projectId },
    });

    return {
      ...invitation,
      project,
    };
  }

  /**
   * Gets all pending invitations for a project (manager only)
   */
  async getProjectInvitations(
    projectId: number,
    userId: string
  ): Promise<Invitation[]> {
    // Verify that the user is a MANAGER of the project
    const membership = await this.entityManager.findOne(ProjectMember, {
      where: { projectId, userId },
    });

    if (!membership || membership.role !== ProjectRole.MANAGER) {
      throw new ForbiddenException(
        'Only managers can view project invitations.'
      );
    }

    return this.entityManager.find(Invitation, {
      where: { projectId },
      order: { createdAt: 'DESC' },
    });
  }

  /**
   * Cancels/deletes a pending invitation (manager only)
   */
  async cancelInvitation(invitationId: string, userId: string): Promise<void> {
    const invitation = await this.entityManager.findOne(Invitation, {
      where: { id: invitationId },
    });

    if (!invitation) {
      throw new NotFoundException('Invitation not found.');
    }

    // Verify that the user is a MANAGER of the project
    const membership = await this.entityManager.findOne(ProjectMember, {
      where: { projectId: invitation.projectId, userId },
    });

    if (!membership || membership.role !== ProjectRole.MANAGER) {
      throw new ForbiddenException('Only managers can cancel invitations.');
    }

    await this.entityManager.remove(invitation);
  }
}

