import {
  Controller,
  Get,
  Post,
  Body,
  Patch,
  Param,
  UseGuards,
  ParseIntPipe,
  Delete,
  Query,
} from '@nestjs/common';
import { ProjectService } from './project.service';
import {
  CreateProjectDto,
  UpdateProjectDto,
  WidgetSettingsDto,
  CreateInvitationDto,
  AcceptInvitationDto,
} from '@live-chat/shared-dtos';
import { User } from '../database/entities';
