  @Column({ type: "text", nullable: true })
  content: string | null;

  @Column({ type: "jsonb", nullable: true })
  attachments: any | null;

  @Column({ type: "varchar", name: "sender_id" })
  senderId: string;

  @Column({ type: "varchar", name: "recipient_id" })
